var __index = {"config":{"lang":["en","zh"],"separator":"[\\s\\-,:!=\\[\\]()\"/]+|(?!\\b)(?=[A-Z][a-z])|(?<=\\w)(?=\\.)","pipeline":["stopWordFilter"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"MICOS-2024","text":"<p> \u4e13\u4e1a\u5b8f\u57fa\u56e0\u7ec4\u5206\u6790\u5e73\u53f0 \u7aef\u5230\u7aef\u5206\u6790\u4ece\u539f\u59cb\u6d4b\u5e8f\u6570\u636e\u5230\u751f\u7269\u5b66\u6d1e\u5bdf </p>"},{"location":"index.html#select-language","title":"\u9009\u62e9\u6587\u6863\u8bed\u8a00 / Select Language","text":"<ul> <li> <p> English Documentation</p> <p>Professional metagenomic analysis platform with comprehensive documentation</p> <p> Go to English Docs</p> </li> <li> <p> \u4e2d\u6587\u6587\u6863</p> <p>\u4e13\u4e1a\u5b8f\u57fa\u56e0\u7ec4\u5206\u6790\u5e73\u53f0\uff0c\u63d0\u4f9b\u5b8c\u6574\u7684\u4e2d\u6587\u6587\u6863\u652f\u6301</p> <p> \u8bbf\u95ee\u4e2d\u6587\u6587\u6863</p> </li> </ul>"},{"location":"index.html#what-is-micos-2024","title":"What is MICOS-2024?","text":"<p>MICOS-2024 (Metagenomic Intelligence and Comprehensive Omics Suite) \u662f\u4e00\u4e2a\u7aef\u5230\u7aef\u5b8f\u57fa\u56e0\u7ec4\u5206\u6790\u5e73\u53f0\uff0c\u6574\u5408 Kraken2\u3001QIIME2\u3001HUMAnN \u7b49\u4e1a\u754c\u6807\u51c6\u751f\u7269\u4fe1\u606f\u5b66\u5de5\u5177\uff0c\u63d0\u4f9b\u4ece\u539f\u59cb\u6d4b\u5e8f\u6570\u636e\u5230\u751f\u7269\u5b66\u6d1e\u5bdf\u7684\u5b8c\u6574\u5206\u6790\u6d41\u7a0b\u3002</p>"},{"location":"index.html#_1","title":"\u6838\u5fc3\u80fd\u529b","text":"<ul> <li> \u8d28\u91cf\u63a7\u5236 - \u5bbf\u4e3b DNA \u53bb\u9664\u4e0e\u8d28\u91cf\u8fc7\u6ee4 (KneadData, FastQC)</li> <li>:material-account-tree: \u7269\u79cd\u5206\u7c7b - \u5feb\u901f\u7269\u79cd\u5206\u7c7b (Kraken2, Bracken)</li> <li> \u591a\u6837\u6027\u5206\u6790 - Alpha/Beta \u591a\u6837\u6027\u6307\u6807 (QIIME2)</li> <li> \u529f\u80fd\u6ce8\u91ca - \u57fa\u56e0\u5bb6\u65cf\u548c\u901a\u8def\u5206\u6790 (HUMAnN)</li> <li> \u5dee\u5f02\u5206\u6790 - \u7edf\u8ba1\u6bd4\u8f83\u5206\u6790</li> <li> \u7f51\u7edc\u5206\u6790 - \u5fae\u751f\u7269\u5171\u73b0\u7f51\u7edc</li> </ul>"},{"location":"index.html#_2","title":"\u5feb\u901f\u94fe\u63a5","text":"\u94fe\u63a5 \u8bf4\u660e GitHub \u6e90\u4ee3\u7801\u4ed3\u5e93 Issues \u95ee\u9898\u53cd\u9988 Discussions \u793e\u533a\u8ba8\u8bba <p> License: MIT | Team: MICOS-2024 Team </p>"},{"location":"ARCHIVED.html","title":"\u9879\u76ee\u5f52\u6863\u8bf4\u660e","text":"<p>\u672c\u6587\u6863\u8bb0\u5f55 MICOS-2024 \u9879\u76ee\u91cd\u6784\u5f52\u6863\u4fe1\u606f</p>"},{"location":"ARCHIVED.html#_2","title":"\u5f52\u6863\u65e5\u671f","text":"<p>2026-04-27</p>"},{"location":"ARCHIVED.html#_3","title":"\u9879\u76ee\u72b6\u6001","text":"<p>\u5df2\u5b8c\u6210 - \u9879\u76ee\u5df2\u8fbe\u5230\u300c\u6700\u7ec8\u5b8c\u7ed3\u72b6\u6001\u300d</p>"},{"location":"ARCHIVED.html#_4","title":"\u91cd\u6784\u6458\u8981","text":""},{"location":"ARCHIVED.html#_5","title":"\u5df2\u5b8c\u6210\u7684\u5de5\u4f5c","text":"\u9636\u6bb5 \u5185\u5bb9 \u72b6\u6001 Phase 1 \u4f9d\u8d56\u7ba1\u7406\u89c4\u8303\u5316\u3001\u6587\u6863\u6e05\u7406\u3001ADR \u8865\u5145 \u2705 Phase 2 CI/CD \u7cbe\u7b80\u3001GitHub \u5143\u6570\u636e\u66f4\u65b0 \u2705 Phase 3 AI \u5de5\u5177\u94fe\u914d\u7f6e (AGENTS.md, CLAUDE.md) \u2705 Phase 4 \u6267\u884c\u3001\u9a8c\u8bc1\u3001\u63d0\u4ea4\u3001\u63a8\u9001 \u2705"},{"location":"ARCHIVED.html#_6","title":"\u53d8\u66f4\u7edf\u8ba1","text":"\u6307\u6807 \u6570\u503c \u5220\u9664\u6587\u4ef6 9 \u4e2a \u65b0\u589e\u6587\u4ef6 22 \u4e2a \u4ee3\u7801\u53d8\u66f4 +3,467 / -1,825 \u884c ADR \u6570\u91cf 5 \u4e2a \u4e2d\u6587\u6587\u6863\u8986\u76d6\u7387 100%"},{"location":"ARCHIVED.html#_7","title":"\u5173\u952e\u6587\u4ef6","text":"\u6587\u4ef6 \u7528\u9014 <code>AGENTS.md</code> AI \u7f16\u7a0b\u52a9\u624b\u5b8c\u6574\u4e0a\u4e0b\u6587 <code>CLAUDE.md</code> Claude Code \u9879\u76ee\u914d\u7f6e <code>.github/copilot-instructions.md</code> GitHub Copilot \u6307\u4ee4 <code>CODEOWNERS</code> \u4ee3\u7801\u6240\u6709\u6743\u5b9a\u4e49"},{"location":"ARCHIVED.html#_8","title":"\u540e\u7eed\u7ef4\u62a4","text":"<p>\u672c\u9879\u76ee\u5df2\u8fbe\u5230\u7a33\u5b9a\u72b6\u6001\uff0c\u540e\u7eed\u7ef4\u62a4\u5efa\u8bae\uff1a</p> <ol> <li>Bug \u4fee\u590d: \u6309\u9700\u8fdb\u884c</li> <li>\u4f9d\u8d56\u66f4\u65b0: \u6bcf\u5b63\u5ea6\u68c0\u67e5\u4e00\u6b21</li> <li>\u6587\u6863\u540c\u6b65: \u4e2d\u82f1\u6587\u6863\u4fdd\u6301\u540c\u6b65</li> <li>\u65b0\u529f\u80fd: \u9700\u8981\u5145\u5206\u8bc4\u4f30\u540e\u6dfb\u52a0</li> </ol>"},{"location":"ARCHIVED.html#_9","title":"\u8054\u7cfb\u65b9\u5f0f","text":"<ul> <li>\u7ec4\u7ec7: BGI-MICOS</li> <li>\u4ed3\u5e93: https://github.com/LessUp/micos-2024</li> <li>\u6587\u6863: https://bgi-micos.github.io/MICOS-2024/</li> </ul> <p>\u672c\u5f52\u6863\u7531 Claude Code \u81ea\u52a8\u751f\u6210</p>"},{"location":"en/index.html","title":"MICOS-2024","text":"<p>Professional Metagenomic Analysis Platform</p> <p>End-to-end analysis from raw sequencing data to biological insights</p>"},{"location":"en/index.html#what-is-micos-2024","title":"What is MICOS-2024?","text":"<p>MICOS-2024 (Metagenomic Intelligence and Comprehensive Omics Suite) is an end-to-end metagenomic analysis platform that integrates industry-standard bioinformatics tools into a unified, reproducible workflow.</p>"},{"location":"en/index.html#core-capabilities","title":"Core Capabilities","text":"Module Description Tools  Quality Control Host DNA removal and quality filtering KneadData, FastQC :material-account-tree: Taxonomic Profiling Rapid species classification Kraken2, Bracken  Diversity Analysis Alpha/Beta diversity metrics QIIME2  Functional Annotation Gene family and pathway analysis HUMAnN 3.x  Differential Analysis Statistical comparison of taxa/functions DESeq2, ALDEx2  Network Analysis Microbial co-occurrence networks NetworkX, igraph"},{"location":"en/index.html#key-features","title":"Key Features","text":"<ul> <li> Containerized - Docker &amp; Singularity support for reproducibility</li> <li> High Performance - Multi-threading, optimized for large datasets</li> <li> Rich Visualizations - Interactive HTML reports, Krona charts</li> <li> Modular Design - Run complete pipeline or individual steps</li> <li> WDL Workflows - Cromwell-compatible for cloud/HPC deployment</li> </ul>"},{"location":"en/index.html#quick-start","title":"Quick Start","text":"<pre><code># 1. Clone the repository\ngit clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\n\n# 2. Install via Docker (recommended)\ndocker compose -f deploy/docker-compose.example.yml up -d\n\n# 3. Run analysis\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16\n</code></pre> <p> Full Installation Guide</p>"},{"location":"en/index.html#documentation","title":"Documentation","text":"Document Description Installation Guide Complete installation instructions Configuration Guide Parameter configuration Taxonomic Profiling Species classification and visualization Functional Profiling Gene family and pathway analysis API Reference Complete CLI command reference"},{"location":"en/index.html#links","title":"Links","text":"<ul> <li> GitHub Repository</li> <li> Issue Tracker</li> <li> Discussions</li> </ul> <p> \u4e2d\u6587\u6587\u6863 | GitHub </p>"},{"location":"en/api-reference.html","title":"API Reference","text":"<p>Complete reference for MICOS-2024 command-line interface.</p>"},{"location":"en/api-reference.html#table-of-contents","title":"Table of Contents","text":"<ul> <li>Overview</li> <li>Global Options</li> <li>Commands</li> <li>full-run</li> <li>run</li> <li>validate-config</li> </ul>"},{"location":"en/api-reference.html#overview","title":"Overview","text":"<p>MICOS-2024 provides a unified command-line interface (CLI) for metagenomic analysis. All commands follow the pattern:</p> <pre><code>python -m micos.cli [GLOBAL_OPTIONS] &lt;COMMAND&gt; [COMMAND_OPTIONS]\n</code></pre>"},{"location":"en/api-reference.html#getting-help","title":"Getting Help","text":"<pre><code># General help\npython -m micos.cli --help\n\n# Command-specific help\npython -m micos.cli full-run --help\npython -m micos.cli run quality-control --help\n</code></pre>"},{"location":"en/api-reference.html#global-options","title":"Global Options","text":"Option Short Description Default <code>--config</code> <code>-c</code> Path to configuration file <code>config/analysis.yaml</code> <code>--verbose</code> <code>-v</code> Enable verbose output <code>false</code> <code>--log-file</code> <code>-l</code> Path to log file <code>logs/micos.log</code> <code>--threads</code> <code>-t</code> Number of parallel threads <code>16</code> <code>--dry-run</code> <code>-n</code> Show what would be executed <code>false</code> <code>--version</code> <code>-V</code> Show version information -"},{"location":"en/api-reference.html#examples","title":"Examples","text":"<pre><code># Use custom config\npython -m micos.cli --config my_config.yaml full-run --input-dir data/\n\n# Verbose output with custom log\npython -m micos.cli --verbose --log-file analysis.log full-run ...\n\n# Dry run (preview only)\npython -m micos.cli --dry-run full-run --input-dir data/\n</code></pre>"},{"location":"en/api-reference.html#commands","title":"Commands","text":""},{"location":"en/api-reference.html#full-run","title":"full-run","text":"<p>Execute the complete analysis pipeline from raw reads to final report.</p>"},{"location":"en/api-reference.html#synopsis","title":"Synopsis","text":"<pre><code>python -m micos.cli full-run [OPTIONS]\n</code></pre>"},{"location":"en/api-reference.html#required-arguments","title":"Required Arguments","text":"Argument Description Example <code>--input-dir</code> Directory containing raw FASTQ files <code>--input-dir data/raw</code> <code>--results-dir</code> Directory for output files <code>--results-dir results</code>"},{"location":"en/api-reference.html#database-arguments","title":"Database Arguments","text":"Argument Description Example <code>--kneaddata-db</code> Path to KneadData database <code>--kneaddata-db /db/human_genome</code> <code>--kraken2-db</code> Path to Kraken2 database <code>--kraken2-db /db/kraken2_standard</code>"},{"location":"en/api-reference.html#optional-arguments","title":"Optional Arguments","text":"Argument Description Default <code>--threads</code> Maximum parallel threads <code>16</code> <code>--samples</code> Comma-separated sample list All samples <code>--skip-qc</code> Skip quality control <code>false</code> <code>--skip-taxonomy</code> Skip taxonomic profiling <code>false</code> <code>--skip-functional</code> Skip functional annotation <code>false</code> <code>--skip-diversity</code> Skip diversity analysis <code>false</code>"},{"location":"en/api-reference.html#examples_1","title":"Examples","text":"<pre><code># Basic usage\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16 \\\n  --kneaddata-db /db/human_genome \\\n  --kraken2-db /db/kraken2_standard\n\n# Analyze specific samples only\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --samples SampleA,SampleB,SampleC\n\n# Skip functional analysis (taxonomy only)\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --skip-functional\n</code></pre>"},{"location":"en/api-reference.html#output-structure","title":"Output Structure","text":"<pre><code>results/\n\u251c\u2500\u2500 quality_control/\n\u2502   \u251c\u2500\u2500 fastqc_reports/\n\u2502   \u2514\u2500\u2500 kneaddata/\n\u251c\u2500\u2500 taxonomic_profiling/\n\u2502   \u251c\u2500\u2500 *.kraken\n\u2502   \u251c\u2500\u2500 *.report\n\u2502   \u251c\u2500\u2500 *.krona.html\n\u2502   \u2514\u2500\u2500 feature-table.biom\n\u251c\u2500\u2500 functional_annotation/\n\u2502   \u251c\u2500\u2500 *_genefamilies.tsv\n\u2502   \u2514\u2500\u2500 *_pathabundance.tsv\n\u251c\u2500\u2500 diversity_analysis/\n\u2502   \u251c\u2500\u2500 alpha_diversity/\n\u2502   \u2514\u2500\u2500 beta_diversity/\n\u2514\u2500\u2500 report.html\n</code></pre>"},{"location":"en/api-reference.html#run","title":"run","text":"<p>Execute individual analysis modules.</p>"},{"location":"en/api-reference.html#synopsis_1","title":"Synopsis","text":"<pre><code>python -m micos.cli run &lt;MODULE&gt; [OPTIONS]\n</code></pre>"},{"location":"en/api-reference.html#available-modules","title":"Available Modules","text":"Module Description <code>quality-control</code> FastQC and KneadData processing <code>taxonomic-profiling</code> Kraken2 classification <code>diversity-analysis</code> QIIME2 diversity metrics <code>functional-annotation</code> HUMAnN functional profiling <code>summarize-results</code> Generate HTML report"},{"location":"en/api-reference.html#quality-control","title":"quality-control","text":"<pre><code>python -m micos.cli run quality-control [OPTIONS]\n</code></pre> <p>Arguments:</p> Argument Required Description <code>--input-dir</code> \u2713 Raw FASTQ directory <code>--output-dir</code> \u2713 QC results directory <code>--kneaddata-db</code> \u2713 Host genome database <code>--threads</code> Parallel threads <p>Example: <pre><code>python -m micos.cli run quality-control \\\n  --input-dir data/raw_input \\\n  --output-dir results/quality_control \\\n  --kneaddata-db /db/human_genome \\\n  --threads 8\n</code></pre></p>"},{"location":"en/api-reference.html#taxonomic-profiling","title":"taxonomic-profiling","text":"<pre><code>python -m micos.cli run taxonomic-profiling [OPTIONS]\n</code></pre> <p>Arguments:</p> Argument Required Description <code>--input-dir</code> \u2713 Cleaned FASTQ directory (QC output) <code>--output-dir</code> \u2713 Taxonomy results directory <code>--kraken2-db</code> \u2713 Kraken2 database path <code>--confidence</code> Classification confidence threshold <code>--threads</code> Parallel threads <p>Example: <pre><code>python -m micos.cli run taxonomic-profiling \\\n  --input-dir results/quality_control/kneaddata \\\n  --output-dir results/taxonomic_profiling \\\n  --kraken2-db /db/kraken2_standard \\\n  --confidence 0.1 \\\n  --threads 16\n</code></pre></p>"},{"location":"en/api-reference.html#diversity-analysis","title":"diversity-analysis","text":"<pre><code>python -m micos.cli run diversity-analysis [OPTIONS]\n</code></pre> <p>Arguments:</p> Argument Required Description <code>--input-biom</code> \u2713 BIOM feature table path <code>--output-dir</code> \u2713 Diversity results directory <code>--metadata</code> Sample metadata file <code>--sampling-depth</code> Rarefaction depth <p>Example: <pre><code>python -m micos.cli run diversity-analysis \\\n  --input-biom results/taxonomic_profiling/feature-table.biom \\\n  --output-dir results/diversity_analysis \\\n  --metadata metadata.tsv \\\n  --sampling-depth 10000\n</code></pre></p>"},{"location":"en/api-reference.html#functional-annotation","title":"functional-annotation","text":"<pre><code>python -m micos.cli run functional-annotation [OPTIONS]\n</code></pre> <p>Arguments:</p> Argument Required Description <code>--input-dir</code> \u2713 Cleaned FASTQ directory <code>--output-dir</code> \u2713 Functional results directory <code>--threads</code> Parallel threads <code>--nucleotide-db</code> ChocoPhlAN database <code>--protein-db</code> UniRef database <p>Example: <pre><code>python -m micos.cli run functional-annotation \\\n  --input-dir results/quality_control/kneaddata \\\n  --output-dir results/functional_annotation \\\n  --threads 8\n</code></pre></p>"},{"location":"en/api-reference.html#summarize-results","title":"summarize-results","text":"<pre><code>python -m micos.cli run summarize-results [OPTIONS]\n</code></pre> <p>Arguments:</p> Argument Required Description <code>--results-dir</code> \u2713 Main results directory <code>--output-file</code> \u2713 Output HTML report path <code>--format</code> Output format (html, pdf) <p>Example: <pre><code>python -m micos.cli run summarize-results \\\n  --results-dir results \\\n  --output-file results/final_report.html\n</code></pre></p>"},{"location":"en/api-reference.html#validate-config","title":"validate-config","text":"<p>Validate configuration file before running analysis.</p>"},{"location":"en/api-reference.html#synopsis_2","title":"Synopsis","text":"<pre><code>python -m micos.cli validate-config [OPTIONS]\n</code></pre> <p>Arguments:</p> Argument Required Description <code>--config</code> Path to configuration file <p>Example: <pre><code># Validate default config\npython -m micos.cli validate-config\n\n# Validate custom config\npython -m micos.cli validate-config --config my_config.yaml\n</code></pre></p> <p>Output: <pre><code>\u2713 Configuration file syntax valid\n\u2713 Required fields present\n\u2713 Database paths exist\n\u2713 Parameter values in valid range\n\u26a0 Warning: Sampling depth not specified (will auto-detect)\nConfiguration validation completed successfully!\n</code></pre></p>"},{"location":"en/api-reference.html#configuration-file-reference","title":"Configuration File Reference","text":""},{"location":"en/api-reference.html#location","title":"Location","text":"<p>Default configuration search order: 1. Path specified with <code>--config</code> 2. <code>./config/analysis.yaml</code> 3. <code>~/.config/micos/analysis.yaml</code></p>"},{"location":"en/api-reference.html#structure","title":"Structure","text":"<pre><code># config/analysis.yaml\n\nproject:\n  name: \"My_Study\"\n  description: \"Metagenomic analysis of gut samples\"\n\npaths:\n  input_dir: \"data/raw\"\n  output_dir: \"results\"\n\nresources:\n  max_threads: 16\n  max_memory: \"32GB\"\n\nquality_control:\n  kneaddata:\n    min_quality: 20\n    min_length: 50\n\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.1\n    threads: 16\n\ndiversity_analysis:\n  qiime2:\n    sampling_depth: 10000\n\nfunctional_annotation:\n  humann:\n    threads: 8\n</code></pre>"},{"location":"en/api-reference.html#return-codes","title":"Return Codes","text":"Code Meaning 0 Success 1 General error 2 Invalid arguments 3 Configuration error 4 Missing dependencies 5 Database error 6 I/O error 130 Interrupted by user"},{"location":"en/api-reference.html#environment-variables","title":"Environment Variables","text":"Variable Description Example <code>MICOS_CONFIG</code> Default config file path <code>/path/to/config.yaml</code> <code>MICOS_THREADS</code> Default thread count <code>16</code> <code>MICOS_LOG_LEVEL</code> Logging level <code>INFO</code>, <code>DEBUG</code> <code>KRAKEN2_DB_PATH</code> Default Kraken2 database <code>/db/kraken2</code>"},{"location":"en/api-reference.html#batch-processing","title":"Batch Processing","text":""},{"location":"en/api-reference.html#running-multiple-samples","title":"Running Multiple Samples","text":"<pre><code># Process multiple datasets\nfor dataset in dataset1 dataset2 dataset3; do\n  python -m micos.cli full-run \\\n    --input-dir \"data/${dataset}\" \\\n    --results-dir \"results/${dataset}\" \\\n    --config \"config/${dataset}.yaml\"\ndone\n</code></pre>"},{"location":"en/api-reference.html#parallel-sample-processing","title":"Parallel Sample Processing","text":"<pre><code># GNU parallel for parallel sample processing\nls data/*/ | parallel -j 4 \\\n  'python -m micos.cli run taxonomic-profiling \\\n    --input-dir data/{} \\\n    --output-dir results/{}/taxonomy'\n</code></pre>"},{"location":"en/api-reference.html#see-also","title":"See Also","text":"<ul> <li>Configuration Guide - Detailed configuration options</li> <li>User Manual - Step-by-step usage guide</li> <li>Troubleshooting - Common issues and solutions</li> </ul>"},{"location":"en/configuration.html","title":"Configuration Guide","text":"<p>Complete reference for configuring MICOS-2024 analysis parameters.</p>"},{"location":"en/configuration.html#table-of-contents","title":"Table of Contents","text":"<ul> <li>Configuration Overview</li> <li>Configuration Files</li> <li>Project Configuration</li> <li>Resource Configuration</li> <li>Module-Specific Parameters</li> <li>Configuration Validation</li> <li>Best Practices</li> <li>Examples</li> </ul>"},{"location":"en/configuration.html#configuration-overview","title":"Configuration Overview","text":"<p>MICOS-2024 uses a multi-layer configuration system based on YAML format. The system supports:</p> <ul> <li>Modular configuration: Each analysis module has independent settings</li> <li>Variable substitution: Use <code>${variable}</code> syntax for reusable values</li> <li>Configuration inheritance: Default \u2192 Project \u2192 Command-line overrides</li> <li>Automatic validation: Check configuration before analysis starts</li> </ul>"},{"location":"en/configuration.html#configuration-hierarchy","title":"Configuration Hierarchy","text":"<pre><code>1. Default values (built into code)\n   \u2193\n2. Configuration files (config/analysis.yaml)\n   \u2193\n3. Environment variables (MICOS_* variables)\n   \u2193\n4. Command-line arguments (highest priority)\n</code></pre>"},{"location":"en/configuration.html#configuration-files","title":"Configuration Files","text":""},{"location":"en/configuration.html#file-structure","title":"File Structure","text":"<pre><code>config/\n\u251c\u2500\u2500 analysis.yaml          # Main analysis parameters\n\u251c\u2500\u2500 databases.yaml         # Database paths\n\u251c\u2500\u2500 samples.tsv           # Sample metadata\n\u2514\u2500\u2500 config.conf           # Cromwell workflow settings\n</code></pre>"},{"location":"en/configuration.html#quick-setup","title":"Quick Setup","text":"<pre><code># Copy template files\ncp config/analysis.yaml.template config/analysis.yaml\ncp config/databases.yaml.template config/databases.yaml\ncp config/samples.tsv.template config/samples.tsv\n\n# Edit configurations\nnano config/analysis.yaml\nnano config/databases.yaml\nnano config/samples.tsv\n</code></pre>"},{"location":"en/configuration.html#project-configuration","title":"Project Configuration","text":""},{"location":"en/configuration.html#basic-project-information","title":"Basic Project Information","text":"<pre><code>project:\n  name: \"Gut_Microbiome_Study_2024\"\n  description: \"Analysis of human gut microbiome in treatment vs control\"\n  version: \"1.0.0\"\n  author: \"Research Team\"\n  email: \"team@example.com\"\n</code></pre>"},{"location":"en/configuration.html#path-configuration","title":"Path Configuration","text":"<pre><code>paths:\n  input_dir: \"data/raw_input\"           # Raw data directory\n  output_dir: \"results\"                  # Results directory\n  temp_dir: \"/tmp/micos\"                 # Temporary files (use fast storage)\n  log_dir: \"logs\"                        # Log files directory\n\n  # Database paths (can also use databases.yaml)\n  databases:\n    kraken2: \"/data/databases/kraken2/standard\"\n    kneaddata: \"/data/databases/kneaddata/human_genome\"\n    humann: \"/data/databases/humann\"\n</code></pre>"},{"location":"en/configuration.html#path-variables","title":"Path Variables","text":"<p>Use variable substitution for cleaner configuration:</p> <pre><code>paths:\n  base_dir: \"/project/micos_analysis\"\n  input_dir: \"${paths.base_dir}/data\"\n  output_dir: \"${paths.base_dir}/results\"\n  temp_dir: \"${paths.base_dir}/tmp\"\n</code></pre>"},{"location":"en/configuration.html#resource-configuration","title":"Resource Configuration","text":""},{"location":"en/configuration.html#compute-resources","title":"Compute Resources","text":"<pre><code>resources:\n  max_threads: 16              # Maximum parallel threads\n  max_memory: \"32GB\"           # Maximum memory allocation\n  max_time: \"24h\"              # Maximum runtime per task\n\n  # Per-module thread allocation\n  thread_allocation:\n    quality_control: 8\n    taxonomic_profiling: 16\n    functional_annotation: 8\n    diversity_analysis: 4\n</code></pre>"},{"location":"en/configuration.html#resource-guidelines","title":"Resource Guidelines","text":"Dataset Size Threads Memory Temp Storage Small (&lt; 10 samples) 8 16 GB 50 GB Medium (10-50 samples) 16 32 GB 200 GB Large (50-200 samples) 32 64 GB 1 TB Very Large (&gt; 200 samples) 64+ 128 GB 2 TB+"},{"location":"en/configuration.html#storage-optimization","title":"Storage Optimization","text":"<pre><code>resources:\n  # Use SSD for temporary files\n  temp_dir: \"/ssd/tmp\"\n\n  # Enable compression\n  compression:\n    enabled: true\n    level: 6              # gzip compression level (1-9)\n\n  # Cleanup settings\n  cleanup:\n    remove_intermediate: true\n    keep_logs: true\n</code></pre>"},{"location":"en/configuration.html#module-specific-parameters","title":"Module-Specific Parameters","text":""},{"location":"en/configuration.html#quality-control-module","title":"Quality Control Module","text":"<pre><code>quality_control:\n  enabled: true\n\n  fastqc:\n    enabled: true\n    threads: 4\n    memory: \"2GB\"\n\n  kneaddata:\n    enabled: true\n    threads: 8\n\n    # Quality filtering\n    min_quality: 20           # Minimum base quality score\n    min_length: 50            # Minimum read length after trimming\n\n    # Trimmomatic options\n    trimmomatic_options: \"SLIDINGWINDOW:4:20 MINLEN:50\"\n\n    # Host removal\n    reference_db: \"${paths.databases.kneaddata}\"\n\n    # Additional options\n    remove_intermediate: true\n    bypass_trf: false         # Skip tandem repeat filtering\n    threads: 8\n</code></pre>"},{"location":"en/configuration.html#taxonomic-profiling-module","title":"Taxonomic Profiling Module","text":"<pre><code>taxonomic_profiling:\n  enabled: true\n\n  kraken2:\n    enabled: true\n    threads: 16\n\n    # Classification parameters\n    confidence: 0.1           # Confidence threshold (0-1)\n                            # Lower = more classified reads, potentially more false positives\n                            # Higher = fewer classified reads, higher precision\n    min_base_quality: 20      # Minimum base quality for classification\n    min_hit_groups: 2         # Minimum number of hit groups\n\n    # Memory options\n    memory_mapping: true      # Use memory-mapped I/O (faster, more memory)\n\n    # Output options\n    use_names: true           # Include taxonomic names in output\n    report_zeros: false       # Include taxa with zero counts\n\n  kraken_biom:\n    enabled: true\n    format: \"hdf5\"            # hdf5 or json\n\n  krona:\n    enabled: true\n    max_depth: 7              # Maximum taxonomic depth for visualization\n</code></pre>"},{"location":"en/configuration.html#kraken2-confidence-parameter-guide","title":"Kraken2 Confidence Parameter Guide","text":"Confidence Use Case Expected Classification Rate 0.0 Maximum sensitivity 80-95% 0.1 Balanced (default) 60-80% 0.3 Higher precision 40-60% 0.5 Conservative 20-40%"},{"location":"en/configuration.html#diversity-analysis-module","title":"Diversity Analysis Module","text":"<pre><code>diversity_analysis:\n  enabled: true\n\n  qiime2:\n    enabled: true\n\n    # Feature table filtering\n    feature_filtering:\n      min_frequency: 10       # Minimum count per feature\n      min_samples: 3          # Minimum samples feature must appear in\n\n    # Rarefaction depth (auto-detect if not specified)\n    # sampling_depth: 10000\n\n    # Alpha diversity metrics\n    alpha_metrics:\n      - \"shannon\"            # Shannon diversity index\n      - \"chao1\"              # Chao1 richness estimator\n      - \"simpson\"            # Simpson index\n      - \"observed_features\"   # Number of observed ASVs/OTUs\n      - \"pielou_e\"           # Pielou's evenness\n\n    # Beta diversity metrics\n    beta_metrics:\n      - \"braycurtis\"         # Bray-Curtis dissimilarity\n      - \"jaccard\"            # Jaccard distance\n      - \"unweighted_unifrac\" # Unweighted UniFrac\n      - \"weighted_unifrac\"   # Weighted UniFrac\n</code></pre>"},{"location":"en/configuration.html#choosing-sampling-depth","title":"Choosing Sampling Depth","text":"<pre><code># Method 1: Auto-detect (recommended for beginners)\ndiversity_analysis:\n  qiime2:\n    sampling_depth: \"auto\"\n\n# Method 2: Manual based on data\n# Use 10th percentile of read counts per sample\ndiversity_analysis:\n  qiime2:\n    sampling_depth: 10000\n\n# Method 3: Based on negative controls\ndiversity_analysis:\n  qiime2:\n    sampling_depth: 1000    # Above negative control threshold\n</code></pre>"},{"location":"en/configuration.html#functional-annotation-module","title":"Functional Annotation Module","text":"<pre><code>functional_annotation:\n  enabled: true\n\n  humann:\n    enabled: true\n    threads: 8\n\n    # Database paths\n    nucleotide_database: \"${paths.databases.humann}/chocophlan\"\n    protein_database: \"${paths.databases.humann}/uniref90\"\n\n    # Search options\n    search_mode: \"diamond\"    # diamond or bowtie2\n\n    # Annotation databases\n    pathway_database: \"metacyc\"   # metacyc or reactome\n\n    # Output normalization\n    normalization: \"cpm\"      # cpm (copies per million) or relab\n</code></pre>"},{"location":"en/configuration.html#humann-database-selection","title":"HUMAnN Database Selection","text":"Database Size Speed Use Case UniRef50 ~5 GB Fast Quick screening UniRef90 ~20 GB Moderate Standard analysis UniRef100 ~50 GB Slow Maximum coverage"},{"location":"en/configuration.html#differential-abundance-module","title":"Differential Abundance Module","text":"<pre><code>differential_abundance:\n  enabled: true\n\n  methods:\n    # DESeq2 for raw count data\n    deseq2:\n      enabled: true\n      alpha: 0.05\n      fold_change_threshold: 2.0\n      min_count: 10\n\n    # ALDEx2 for compositional data\n    aldex2:\n      enabled: true\n      mc_samples: 128\n      test: \"t\"                 # t-test or wilcox\n      effect_size_threshold: 1.0\n\n    # ANCOM-BC for bias correction\n    ancom_bc:\n      enabled: true\n      alpha: 0.05\n      p_adj_method: \"BH\"        # Benjamini-Hochberg\n      zero_cut: 0.90\n      lib_cut: 1000\n\n  visualization:\n    volcano_plot: true\n    ma_plot: true\n    heatmap: true\n    top_features: 50\n</code></pre>"},{"location":"en/configuration.html#network-analysis-module","title":"Network Analysis Module","text":"<pre><code>network_analysis:\n  enabled: true\n\n  correlation:\n    method: \"spearman\"        # spearman, pearson, or sparcc\n    min_abundance: 0.001      # Minimum relative abundance\n    min_prevalence: 0.1       # Minimum fraction of samples\n\n  network_construction:\n    correlation_threshold: 0.6\n    pvalue_threshold: 0.05\n    multiple_testing_correction: \"BH\"\n\n  topology_analysis:\n    centrality_metrics: true\n    module_detection: true\n    key_species_identification: true\n</code></pre>"},{"location":"en/configuration.html#configuration-validation","title":"Configuration Validation","text":""},{"location":"en/configuration.html#automatic-validation","title":"Automatic Validation","text":"<p>MICOS-2024 validates configuration before running:</p> <pre><code># Validate configuration\npython -m micos.cli validate-config --config config/analysis.yaml\n\n# Dry run to test configuration\npython -m micos.cli full-run \\\n  --config config/analysis.yaml \\\n  --dry-run\n</code></pre>"},{"location":"en/configuration.html#validation-checks","title":"Validation Checks","text":"Check Description Failure Action YAML syntax Valid YAML format Error + exit Required fields All mandatory fields present Error + exit Path existence Input/output directories exist Warning/Error Parameter ranges Values within valid ranges Warning Database integrity Database files are valid Error + exit Resource limits Memory/threads within system limits Warning"},{"location":"en/configuration.html#manual-validation","title":"Manual Validation","text":"<pre><code># Python validation\nimport yaml\nfrom micos.config import validate_config\n\nwith open('config/analysis.yaml') as f:\n    config = yaml.safe_load(f)\n\nvalidation_result = validate_config(config)\nif not validation_result.valid:\n    print(validation_result.errors)\n</code></pre>"},{"location":"en/configuration.html#best-practices","title":"Best Practices","text":""},{"location":"en/configuration.html#1-start-with-templates","title":"1. Start with Templates","text":"<pre><code># Always start from templates\ncp config/*.template config/\n# Then customize\n</code></pre>"},{"location":"en/configuration.html#2-use-relative-paths","title":"2. Use Relative Paths","text":"<pre><code># Good - portable across systems\npaths:\n  input_dir: \"data/raw\"\n  output_dir: \"results\"\n\n# Less portable\npaths:\n  input_dir: \"/home/user/specific/path/data\"\n</code></pre>"},{"location":"en/configuration.html#3-version-control-configuration","title":"3. Version Control Configuration","text":"<pre><code># Track configuration templates\ngit add config/*.template\n\n# Don't track actual configs (may contain paths specific to your system)\necho \"config/*.yaml\" &gt;&gt; .gitignore\n</code></pre>"},{"location":"en/configuration.html#4-document-customizations","title":"4. Document Customizations","text":"<pre><code>project:\n  name: \"Study_2024\"\n\nanalysis:\n  # Increased confidence due to high-quality data\n  kraken2:\n    confidence: 0.15\n</code></pre>"},{"location":"en/configuration.html#5-test-with-subset","title":"5. Test with Subset","text":"<pre><code># test_config.yaml - analyze only first 3 samples\nsamples:\n  subset: 3\n</code></pre>"},{"location":"en/configuration.html#examples","title":"Examples","text":""},{"location":"en/configuration.html#example-1-quick-test-configuration","title":"Example 1: Quick Test Configuration","text":"<pre><code>project:\n  name: \"Quick_Test\"\n\npaths:\n  input_dir: \"test_data\"\n  output_dir: \"test_results\"\n\nresources:\n  max_threads: 4\n  max_memory: \"8GB\"\n\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.1\n\n# Use MiniKraken for speed\ndatabases:\n  kraken2: \"/db/minikraken2_v2_8GB\"\n</code></pre>"},{"location":"en/configuration.html#example-2-production-pipeline","title":"Example 2: Production Pipeline","text":"<pre><code>project:\n  name: \"Clinical_Study_Phase2\"\n  version: \"2.1.0\"\n  description: \"Large-scale clinical metagenomics analysis\"\n\npaths:\n  base_dir: \"/projects/clinical_study\"\n  input_dir: \"${paths.base_dir}/raw_data\"\n  output_dir: \"${paths.base_dir}/results\"\n  temp_dir: \"/ssd/tmp\"\n\nresources:\n  max_threads: 32\n  max_memory: \"128GB\"\n\nquality_control:\n  kneaddata:\n    min_quality: 25\n    min_length: 75\n    threads: 16\n\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.1\n    threads: 32\n    memory_mapping: true\n\ndiversity_analysis:\n  qiime2:\n    sampling_depth: 50000\n    alpha_metrics: [\"shannon\", \"chao1\", \"observed_features\"]\n    beta_metrics: [\"braycurtis\", \"weighted_unifrac\"]\n\ndifferential_abundance:\n  methods:\n    deseq2:\n      enabled: true\n      alpha: 0.01\n      fold_change_threshold: 4.0\n</code></pre>"},{"location":"en/configuration.html#example-3-environmental-metagenomics","title":"Example 3: Environmental Metagenomics","text":"<pre><code>project:\n  name: \"Soil_Microbiome_Survey\"\n\n# Environmental samples - adjust parameters\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.05          # Lower confidence for diverse samples\n\nfunctional_annotation:\n  humann:\n    # Use UniRef50 for faster processing of diverse samples\n    protein_database: \"/db/humann/uniref50\"\n</code></pre>"},{"location":"en/configuration.html#configuration-reference","title":"Configuration Reference","text":""},{"location":"en/configuration.html#complete-parameter-list","title":"Complete Parameter List","text":"<p>See the configuration templates for all available parameters:</p> <ul> <li><code>config/analysis.yaml.template</code> - Analysis parameters</li> <li><code>config/databases.yaml.template</code> - Database paths</li> <li><code>config/samples.tsv.template</code> - Sample metadata</li> </ul>"},{"location":"en/configuration.html#next-steps","title":"Next Steps","text":"<ul> <li>\ud83d\udcd6 User Manual - Learn to run analyses</li> <li>\ud83e\uddec Taxonomic Profiling - Species classification details</li> <li>\ud83e\uddea Functional Profiling - Functional annotation details</li> </ul>"},{"location":"en/diversity-analysis.html","title":"Diversity Analysis","text":"<p>Comprehensive guide to microbial community diversity analysis in MICOS-2024.</p>"},{"location":"en/diversity-analysis.html#table-of-contents","title":"Table of Contents","text":"<ul> <li>Overview</li> <li>Types of Diversity</li> <li>Input Requirements</li> <li>Running the Analysis</li> <li>Alpha Diversity</li> <li>Beta Diversity</li> <li>Statistical Testing</li> <li>Visualization</li> <li>Interpretation Guidelines</li> <li>Advanced Topics</li> </ul>"},{"location":"en/diversity-analysis.html#overview","title":"Overview","text":"<p>Diversity analysis measures the richness (number of taxa) and evenness (distribution of abundances) of microbial communities. These metrics provide insights into:</p> <ul> <li>Community health: Higher diversity often associated with stability</li> <li>Treatment effects: Changes in diversity under different conditions</li> <li>Ecological patterns: Spatial and temporal variation</li> <li>Comparative studies: Differences between ecosystems</li> </ul>"},{"location":"en/diversity-analysis.html#types-of-diversity","title":"Types of Diversity","text":""},{"location":"en/diversity-analysis.html#alpha-diversity-within-sample","title":"Alpha Diversity (Within-Sample)","text":"<p>Measures diversity within individual samples:</p> Metric What it Measures Best Used For Richness Number of taxa Community complexity Shannon Richness + Evenness General diversity Simpson Dominance Detecting dominance Faith's PD Phylogenetic diversity Evolutionary breadth"},{"location":"en/diversity-analysis.html#beta-diversity-between-samples","title":"Beta Diversity (Between-Samples)","text":"<p>Measures dissimilarity between samples:</p> Metric Weighting Best Used For Bray-Curtis Abundance Community composition Jaccard Presence/Absence Species overlap UniFrac Phylogenetic Evolutionary turnover Aitchison Composition Zero-inflated data"},{"location":"en/diversity-analysis.html#gamma-diversity","title":"Gamma Diversity","text":"<p>Total diversity across the entire dataset (landscape scale).</p>"},{"location":"en/diversity-analysis.html#input-requirements","title":"Input Requirements","text":""},{"location":"en/diversity-analysis.html#data-format","title":"Data Format","text":"Format Description Source BIOM Standard format for microbiome data Kraken-biom, QIIME2 TSV Tab-delimited feature table Custom tables QZA QIIME2 artifact QIIME2 exports"},{"location":"en/diversity-analysis.html#feature-table-structure","title":"Feature Table Structure","text":"<pre><code># OTU/ASV table (samples as columns)\n#OTU ID Sample1 Sample2 Sample3\nk__Bacteria;p__Firmicutes   125 89  203\nk__Bacteria;p__Bacteroidetes    534 612 445\n...\n</code></pre>"},{"location":"en/diversity-analysis.html#metadata-requirements","title":"Metadata Requirements","text":"Column Description Required For sample-id Unique identifier All analyses group Experimental group Group comparisons subject-id Subject identifier Paired/longitudinal time-point Time of collection Longitudinal [any] Additional covariates Multivariate analysis"},{"location":"en/diversity-analysis.html#running-the-analysis","title":"Running the Analysis","text":""},{"location":"en/diversity-analysis.html#option-1-micos-cli","title":"Option 1: MICOS CLI","text":"<pre><code># Diversity analysis from BIOM file\npython -m micos.cli run diversity-analysis \\\n  --input-biom results/taxonomic_profiling/feature-table.biom \\\n  --output-dir results/diversity_analysis \\\n  --metadata metadata.tsv\n\n# As part of full pipeline\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16 \\\n  --kneaddata-db /db/kneaddata \\\n  --kraken2-db /db/kraken2\n</code></pre>"},{"location":"en/diversity-analysis.html#option-2-direct-qiime2","title":"Option 2: Direct QIIME2","text":"<pre><code># Import BIOM to QIIME2\nqiime tools import \\\n  --input-path feature-table.biom \\\n  --type 'FeatureTable[Frequency]' \\\n  --output-path table.qza\n\n# Import metadata\nqiime metadata tabulate \\\n  --m-input-file metadata.tsv \\\n  --o-visualization metadata.qzv\n\n# Rarefy table\nqiime feature-table rarefy \\\n  --i-table table.qza \\\n  --p-sampling-depth 10000 \\\n  --o-rarefied-table table-rarefied.qza\n</code></pre>"},{"location":"en/diversity-analysis.html#alpha-diversity","title":"Alpha Diversity","text":""},{"location":"en/diversity-analysis.html#metrics-overview","title":"Metrics Overview","text":""},{"location":"en/diversity-analysis.html#1-richness-estimators","title":"1. Richness Estimators","text":"Metric Description Interpretation Observed Features Raw count of taxa Simple richness Chao1 Estimated total richness Accounts for unobserved taxa ACE Abundance-based coverage Alternative richness estimate <p>Formula - Chao1: <pre><code>Chao1 = S_obs + (n\u2081\u00b2 / 2n\u2082)\nWhere:\n  S_obs = observed species\n  n\u2081 = number of singletons\n  n\u2082 = number of doubletons\n</code></pre></p>"},{"location":"en/diversity-analysis.html#2-diversity-indices","title":"2. Diversity Indices","text":"Metric Formula Range Notes Shannon -\u03a3(p\u1d62 \u00d7 ln(p\u1d62)) 0 to ~7 Accounts for richness and evenness Simpson 1 - \u03a3(p\u1d62\u00b2) 0 to 1 Probability two random reads are different Inverse Simpson 1 / \u03a3(p\u1d62\u00b2) 1 to N Higher = more diverse"},{"location":"en/diversity-analysis.html#3-evenness-measures","title":"3. Evenness Measures","text":"Metric Description Range Pielou's J Shannon / ln(S) 0-1 Simpson's E (1/D) / S 0-1 Heip's E (e^H - 1) / (S - 1) 0-1"},{"location":"en/diversity-analysis.html#implementation","title":"Implementation","text":"<pre><code># Calculate alpha diversity\nqiime diversity alpha \\\n  --i-table table.qza \\\n  --p-metric shannon \\\n  --o-alpha-diversity shannon.qza\n\n# Multiple metrics at once\nqiime diversity alpha-rarefaction \\\n  --i-table table.qza \\\n  --p-metrics shannon \\\n  --p-metrics chao1 \\\n  --p-metrics observed_features \\\n  --p-min-depth 1000 \\\n  --p-max-depth 50000 \\\n  --m-metadata-file metadata.tsv \\\n  --o-visualization alpha-rarefaction.qzv\n</code></pre>"},{"location":"en/diversity-analysis.html#statistical-testing","title":"Statistical Testing","text":"<pre><code># Group comparison\nqiime diversity alpha-group-significance \\\n  --i-alpha-diversity shannon.qza \\\n  --m-metadata-file metadata.tsv \\\n  --m-metadata-column group \\\n  --o-visualization shannon-significance.qzv\n</code></pre> <p>Common Tests: - Kruskal-Wallis: Non-parametric group comparison - Pairwise Wilcoxon: Post-hoc comparisons - Linear mixed effects: Longitudinal data</p>"},{"location":"en/diversity-analysis.html#beta-diversity","title":"Beta Diversity","text":""},{"location":"en/diversity-analysis.html#distance-metrics","title":"Distance Metrics","text":""},{"location":"en/diversity-analysis.html#1-compositional-metrics","title":"1. Compositional Metrics","text":"Metric Type Formula Characteristics Bray-Curtis Abundance-based D = \u03a3|A\u1d62 - B\u1d62| / \u03a3(A\u1d62 + B\u1d62) Jaccard Binary D = 1 - (|A \u2229 B| / |A \u222a B|) Canberra Weighted by abundance Emphasizes rare taxa"},{"location":"en/diversity-analysis.html#2-phylogenetic-metrics","title":"2. Phylogenetic Metrics","text":"Metric Weighting Sensitive To Unweighted UniFrac Presence/absence Phylogenetic novelty Weighted UniFrac Abundance Phylogenetic turnover Generalized UniFrac Balanced Tunable parameter \u03b1"},{"location":"en/diversity-analysis.html#3-transformation-based","title":"3. Transformation-Based","text":"Metric Method Use Case Aitchison CLR + Euclidean Compositional data RPCA Robust PCA Zero-inflated data DEICODE Matrix completion Sparse datasets"},{"location":"en/diversity-analysis.html#implementation_1","title":"Implementation","text":"<pre><code># Calculate beta diversity\nqiime diversity beta \\\n  --i-table table.qza \\\n  --p-metric braycurtis \\\n  --o-distance-matrix braycurtis.qza\n\n# Phylogenetic diversity (requires tree)\nqiime diversity beta-phylogenetic \\\n  --i-table table.qza \\\n  --i-phylogeny tree.qza \\\n  --p-metric unweighted_unifrac \\\n  --o-distance-matrix unweighted-unifrac.qza\n</code></pre>"},{"location":"en/diversity-analysis.html#dimensionality-reduction","title":"Dimensionality Reduction","text":"<pre><code># PCoA\nqiime diversity pcoa \\\n  --i-distance-matrix braycurtis.qza \\\n  --o-pcoa braycurtis-pcoa.qza\n\n# Emperor visualization\nqiime emperor plot \\\n  --i-pcoa braycurtis-pcoa.qza \\\n  --m-metadata-file metadata.tsv \\\n  --o-visualization braycurtis-emperor.qzv\n</code></pre>"},{"location":"en/diversity-analysis.html#statistical-testing_1","title":"Statistical Testing","text":""},{"location":"en/diversity-analysis.html#permanova","title":"PERMANOVA","text":"<p>Tests if groups differ in multivariate space:</p> <pre><code>qiime diversity beta-group-significance \\\n  --i-distance-matrix braycurtis.qza \\\n  --m-metadata-file metadata.tsv \\\n  --m-metadata-column group \\\n  --p-method permanova \\\n  --o-visualization braycurtis-permanova.qzv\n</code></pre> <p>Interpretation: - p &lt; 0.05: Significant difference between groups - R\u00b2: Proportion of variance explained by grouping</p>"},{"location":"en/diversity-analysis.html#permdisp","title":"PERMDISP","text":"<p>Tests homogeneity of multivariate dispersions:</p> <pre><code>qiime diversity beta-group-significance \\\n  --i-distance-matrix braycurtis.qza \\\n  --m-metadata-file metadata.tsv \\\n  --m-metadata-column group \\\n  --p-method permdisp \\\n  --o-visualization braycurtis-permdisp.qzv\n</code></pre>"},{"location":"en/diversity-analysis.html#visualization","title":"Visualization","text":""},{"location":"en/diversity-analysis.html#alpha-diversity-plots","title":"Alpha Diversity Plots","text":"<pre><code>import seaborn as sns\nimport matplotlib.pyplot as plt\n\n# Box plot\ndata = pd.read_csv('alpha_diversity.tsv', sep='\\t')\nsns.boxplot(data=data, x='group', y='shannon')\nplt.title('Shannon Diversity by Group')\nplt.savefig('shannon_boxplot.pdf')\n\n# Rarefaction curve\n# (Use QIIME2 visualization: alpha-rarefaction.qzv)\n</code></pre>"},{"location":"en/diversity-analysis.html#beta-diversity-plots","title":"Beta Diversity Plots","text":"<pre><code>from skbio.stats.ordination import pcoa\nfrom skbio import DistanceMatrix\nimport matplotlib.pyplot as plt\n\n# Load distance matrix\ndm = DistanceMatrix.read('braycurtis.tsv')\n\n# PCoA\npcoa_results = pcoa(dm)\n\n# Plot\nfig, ax = plt.subplots(figsize=(8, 6))\nfor group in metadata['group'].unique():\n    mask = metadata['group'] == group\n    ax.scatter(pcoa_results.samples.loc[mask, 'PC1'],\n               pcoa_results.samples.loc[mask, 'PC2'],\n               label=group)\nax.set_xlabel(f'PC1 ({pcoa_results.proportion_explained[0]:.1%})')\nax.set_ylabel(f'PC2 ({pcoa_results.proportion_explained[1]:.1%})')\nax.legend()\nplt.savefig('pcoa_plot.pdf')\n</code></pre>"},{"location":"en/diversity-analysis.html#interpretation-guidelines","title":"Interpretation Guidelines","text":""},{"location":"en/diversity-analysis.html#alpha-diversity_1","title":"Alpha Diversity","text":""},{"location":"en/diversity-analysis.html#typical-values-human-gut","title":"Typical Values (Human Gut)","text":"Metric Range Notes Observed features 50-200 Varies with sampling depth Shannon 2.5-4.5 &gt;4 indicates high diversity Chao1 100-400 Estimate of total richness Pielou's J 0.6-0.9 &gt;0.8 indicates even distribution"},{"location":"en/diversity-analysis.html#ecological-interpretation","title":"Ecological Interpretation","text":"Scenario Interpretation Low richness, high evenness Few dominant species, well-balanced High richness, low evenness Many rare species, few dominant Low alpha in treatment Potential dysbiosis or stress High alpha in healthy Diverse, resilient community"},{"location":"en/diversity-analysis.html#beta-diversity_1","title":"Beta Diversity","text":""},{"location":"en/diversity-analysis.html#pcoa-interpretation","title":"PCoA Interpretation","text":"Pattern Interpretation Tight clusters by group Strong group effect Overlapping clusters Similar communities Gradient pattern Continuous environmental driver Outliers Unique community composition"},{"location":"en/diversity-analysis.html#distance-comparison","title":"Distance Comparison","text":"Comparison Typical Values Context Within-group distances Lower Similar communities Between-group distances Higher Distinct communities Technical replicates Very low Measurement precision"},{"location":"en/diversity-analysis.html#advanced-topics","title":"Advanced Topics","text":""},{"location":"en/diversity-analysis.html#rarefaction-and-sequencing-depth","title":"Rarefaction and Sequencing Depth","text":"<pre><code># Configuration for rarefaction\ndiversity_analysis:\n  qiime2:\n    sampling_depth: \"auto\"    # Auto-detect\n    # Or specify manually\n    # sampling_depth: 10000\n</code></pre> <p>Choosing sampling depth: 1. Examine rarefaction curves 2. Select depth where curves plateau 3. Include maximum samples possible 4. Exclude samples below minimum depth</p>"},{"location":"en/diversity-analysis.html#longitudinal-analysis","title":"Longitudinal Analysis","text":"<pre><code># Mixed effects model for longitudinal data\nfrom statsmodels.regression.mixed_linear_model import MixedLM\n\n# Model: alpha ~ time * treatment + (1|subject)\nmodel = MixedLM.from_formula(\n    'shannon ~ time_point * treatment',\n    groups='subject_id',\n    data=metadata\n)\nresult = model.fit()\nprint(result.summary())\n</code></pre>"},{"location":"en/diversity-analysis.html#multivariate-analysis","title":"Multivariate Analysis","text":"<pre><code># Adonis2 (PERMANOVA with covariates)\nfrom skbio.stats.distance import permanova\n\n# Test group effect while controlling for age\nresults = permanova(\n    distance_matrix=dm,\n    grouping=metadata['group'],\n    covariates=metadata[['age', 'bmi']],\n    permutations=999\n)\n</code></pre>"},{"location":"en/diversity-analysis.html#core-microbiome-analysis","title":"Core Microbiome Analysis","text":"<pre><code># Identify core features\nfrom qiime2 import Artifact\n\n# Load feature table\ntable = Artifact.load('table.qza')\n\n# Define core (present in &gt;50% of samples, &gt;0.1% abundance)\ncore_features = table.view(pd.DataFrame)\ncore_features = core_features[\n    (core_features &gt; 0).sum(axis=1) / len(core_features.columns) &gt; 0.5\n]\ncore_features = core_features[core_features.sum(axis=1) &gt; 0.001]\n</code></pre>"},{"location":"en/diversity-analysis.html#see-also","title":"See Also","text":"<ul> <li>Taxonomic Profiling - Species classification</li> <li>Functional Profiling - Functional analysis</li> <li>Configuration Guide - Parameter settings</li> <li>QIIME2 Documentation - Detailed QIIME2 guides</li> </ul>"},{"location":"en/faq.html","title":"Frequently Asked Questions (FAQ)","text":"<p>Quick answers to common questions about MICOS-2024.</p>"},{"location":"en/faq.html#general-questions","title":"General Questions","text":""},{"location":"en/faq.html#what-is-micos-2024","title":"What is MICOS-2024?","text":"<p>MICOS-2024 (Metagenomic Intelligence and Comprehensive Omics Suite) is an integrated platform for end-to-end metagenomic analysis. It combines quality control, taxonomic profiling, functional annotation, and diversity analysis into a unified workflow.</p>"},{"location":"en/faq.html#who-should-use-micos-2024","title":"Who should use MICOS-2024?","text":"<ul> <li>Biologists: With minimal bioinformatics experience</li> <li>Bioinformaticians: Who need standardized, reproducible workflows</li> <li>Clinical researchers: Analyzing microbiome samples</li> <li>Ecologists: Studying environmental microbiomes</li> </ul>"},{"location":"en/faq.html#how-does-micos-2024-compare-to-other-tools","title":"How does MICOS-2024 compare to other tools?","text":"Feature MICOS-2024 Qiime2 MG-RAST mothur End-to-end workflow \u2705 Partial \u2705 Partial WDL workflows \u2705 \u274c \u274c \u274c Docker support \u2705 \u2705 \u274c \u274c CLI interface \u2705 \u2705 Web \u2705 Pipeline flexibility High Medium Low Medium"},{"location":"en/faq.html#installation-questions","title":"Installation Questions","text":""},{"location":"en/faq.html#whats-the-recommended-installation-method","title":"What's the recommended installation method?","text":"<p>Docker for: - Maximum reproducibility - Easy deployment on servers - Production environments</p> <p>Conda for: - Development work - Custom modifications - Systems without Docker</p>"},{"location":"en/faq.html#how-much-disk-space-do-i-need","title":"How much disk space do I need?","text":"Component Minimum Recommended Software installation 5 GB 10 GB Kraken2 database 70 GB 150 GB (PlusPF) HUMAnN database 30 GB 50 GB Analysis output 100 GB 500 GB Total ~200 GB ~700 GB"},{"location":"en/faq.html#can-i-install-without-administrator-privileges","title":"Can I install without administrator privileges?","text":"<p>Yes! Both installation methods work without sudo: - Docker: Requires user added to <code>docker</code> group - Conda: Installs entirely in user directory</p>"},{"location":"en/faq.html#do-i-need-a-gpu","title":"Do I need a GPU?","text":"<p>No. MICOS-2024 is CPU-based. GPU acceleration is not currently supported.</p>"},{"location":"en/faq.html#analysis-questions","title":"Analysis Questions","text":""},{"location":"en/faq.html#how-long-does-analysis-take","title":"How long does analysis take?","text":"<p>Approximate times per sample (10M paired-end reads):</p> Step Time Notes Quality Control 10-30 min Depends on host genome size Taxonomic Profiling 5-15 min With Kraken2 standard Functional Annotation 1-4 hours Depends on database Diversity Analysis 10-30 min Per calculation Total 2-6 hours Highly parallelizable <p>Speed tips: - Use SSD for temporary files - Increase <code>--threads</code> parameter - Use MiniKraken for testing</p>"},{"location":"en/faq.html#what-sequencing-depth-do-i-need","title":"What sequencing depth do I need?","text":"Study Type Minimum Recommended Pilot/testing 1M reads/sample 2M reads/sample General profiling 5M reads/sample 10M reads/sample Rare species detection 20M reads/sample 50M reads/sample Functional analysis 10M reads/sample 30M reads/sample"},{"location":"en/faq.html#can-i-analyze-single-end-data","title":"Can I analyze single-end data?","text":"<p>Yes, MICOS-2024 supports both paired-end and single-end data. However: - Paired-end recommended for better taxonomic resolution - Single-end sufficient for functional profiling - Specify format in configuration or let auto-detection handle it</p>"},{"location":"en/faq.html#what-about-amplicon-data-16s","title":"What about amplicon data (16S)?","text":"<p>While MICOS-2024 is optimized for shotgun metagenomics, it can process 16S data:</p> <pre><code># Configuration for amplicon data\nquality_control:\n  kneaddata:\n    bypass_trf: true    # Skip tandem repeat filter (not needed)\n\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.05    # Lower for conserved regions\n</code></pre> <p>For dedicated 16S analysis, consider DADA2 or QIIME2's q2-dada2 plugin.</p>"},{"location":"en/faq.html#database-questions","title":"Database Questions","text":""},{"location":"en/faq.html#which-kraken2-database-should-i-use","title":"Which Kraken2 database should I use?","text":"Database Size Best For MiniKraken2 (8GB) Small Testing, limited RAM Standard (70GB) Medium General purpose PlusPF (100GB) Large Including fungi/protozoa PlusPFP (150GB) X-Large Maximum coverage Custom Variable Specific organisms"},{"location":"en/faq.html#can-i-use-custom-reference-databases","title":"Can I use custom reference databases?","text":"<p>Yes:</p> <pre><code># Build custom Kraken2 database\nkraken2-build --download-taxonomy --db custom_db\nkraken2-build --add-to-library my_genomes/*.fa --db custom_db\nkraken2-build --build --threads 16 --db custom_db\n\n# Use in MICOS\nkraken2-db: \"/path/to/custom_db\"\n</code></pre>"},{"location":"en/faq.html#do-i-need-to-build-databases-myself","title":"Do I need to build databases myself?","text":"<p>No. Pre-built databases are available: - Kraken2: AWS Index - HUMAnN: <code>humann_databases --download</code> - KneadData: <code>kneaddata_database --download</code></p>"},{"location":"en/faq.html#results-questions","title":"Results Questions","text":""},{"location":"en/faq.html#why-are-most-of-my-reads-unclassified","title":"Why are most of my reads unclassified?","text":"<p>Possible reasons:</p> Reason Check Solution Database too small Use Standard not MiniKraken Download larger DB Confidence too high Check config Lower to 0.05-0.1 Novel organisms Literature search Build custom DB Data quality Run FastQC Improve QC parameters Environmental sample Sample type Use PlusPF database"},{"location":"en/faq.html#which-diversity-metric-should-i-use","title":"Which diversity metric should I use?","text":"<p>Alpha Diversity: - Shannon: General diversity (richness + evenness) - Chao1: Richness estimation - Observed: Simple species count</p> <p>Beta Diversity: - Bray-Curtis: Standard for abundance data - UniFrac: When phylogeny matters - Aitchison: For compositional data with zeros</p>"},{"location":"en/faq.html#how-do-i-interpret-statistical-results","title":"How do I interpret statistical results?","text":"Test p &lt; 0.05 means Visualization PERMANOVA Groups differ significantly PCoA plot Kruskal-Wallis Alpha diversity differs Box plot LEfSe Specific taxa different Bar plot"},{"location":"en/faq.html#whats-a-good-diversity-value","title":"What's a \"good\" diversity value?","text":"<p>Human gut typical ranges:</p> Metric Low Normal High Shannon &lt;2.5 2.5-4.0 &gt;4.0 Species richness &lt;50 50-150 &gt;150 <p>Note: Context-dependent! Compare within same sample type.</p>"},{"location":"en/faq.html#troubleshooting-questions","title":"Troubleshooting Questions","text":""},{"location":"en/faq.html#analysis-failed-where-do-i-start","title":"Analysis failed - where do I start?","text":"<ol> <li>Check logs: <code>tail -n 50 logs/analysis.log</code></li> <li>Verify inputs: Input files exist and valid</li> <li>Check resources: <code>free -h</code>, <code>df -h</code></li> <li>Test with subset: Run on 1-2 samples first</li> </ol>"},{"location":"en/faq.html#can-i-resume-a-failed-analysis","title":"Can I resume a failed analysis?","text":"<p>Yes, if outputs from completed steps exist:</p> <pre><code># MICOS will skip completed steps\npython -m micos.cli full-run \\\n  --input-dir data/raw \\\n  --results-dir results \\\n  --threads 16\n  # Steps already done will be skipped\n</code></pre> <p>For manual control, run individual modules: <pre><code>python -m micos.cli run taxonomic-profiling ...\npython -m micos.cli run functional-annotation ...\n</code></pre></p>"},{"location":"en/faq.html#how-do-i-update-micos-2024","title":"How do I update MICOS-2024?","text":"<pre><code># Update code\ngit pull origin main\n\n# Docker - rebuild image\ndocker compose -f deploy/docker-compose.example.yml build\n\n# Conda - update environment\nconda activate micos-2024\npip install -e . --upgrade\n</code></pre>"},{"location":"en/faq.html#performance-questions","title":"Performance Questions","text":""},{"location":"en/faq.html#can-i-run-micos-on-a-laptop","title":"Can I run MICOS on a laptop?","text":"<p>For small datasets (test data, &lt;5 samples): - Minimum: 16GB RAM, 4 cores - Recommended: 32GB RAM, 8 cores</p> <p>For production analysis, use servers or cloud instances.</p>"},{"location":"en/faq.html#how-do-i-optimize-for-speed","title":"How do I optimize for speed?","text":"Action Improvement Trade-off Use SSD for temp 2-3x faster Need SSD storage Increase threads Linear to ~32 More RAM needed Use MiniKraken 5-10x faster Lower sensitivity Disable gap filling 2x faster Less pathway info"},{"location":"en/faq.html#can-i-run-micos-on-a-cluster","title":"Can I run MICOS on a cluster?","text":"<p>Yes! Several approaches:</p> <ol> <li>WDL/Cromwell: Use provided workflows</li> <li>Snakemake: Convert to Snakemake workflow</li> <li>Manual parallelization: Split samples, merge results</li> </ol>"},{"location":"en/faq.html#integration-questions","title":"Integration Questions","text":""},{"location":"en/faq.html#can-i-use-micos-output-with-other-tools","title":"Can I use MICOS output with other tools?","text":"<p>Yes! Output formats are standard:</p> Output Format Compatible With Feature table BIOM QIIME2, phyloseq, vegan Taxonomy TSV R, Python, Excel Pathways TSV Gephi, Cytoscape, R"},{"location":"en/faq.html#how-do-i-import-to-r","title":"How do I import to R?","text":"<pre><code>library(phyloseq)\n\n# Import BIOM\nphyseq &lt;- import_biom(\"feature-table.biom\")\n\n# Import metadata\nsample_data &lt;- read.csv(\"metadata.tsv\", sep=\"\\t\", row.names=1)\nsample_data(physeq) &lt;- sample_data(sample_data)\n</code></pre>"},{"location":"en/faq.html#how-do-i-import-to-python","title":"How do I import to Python?","text":"<pre><code>import pandas as pd\nimport biom\n\n# Load BIOM table\nwith biom.load_table(\"feature-table.biom\") as table:\n    df = table.to_dataframe()\n\n# Load taxonomy\ntaxonomy = pd.read_csv(\"taxonomy.tsv\", sep=\"\\t\", index_col=0)\n</code></pre>"},{"location":"en/faq.html#citation-and-license","title":"Citation and License","text":""},{"location":"en/faq.html#how-do-i-cite-micos-2024","title":"How do I cite MICOS-2024?","text":"<pre><code>@software{micos2024,\n  title = {MICOS-2024: Metagenomic Intelligence and Comprehensive Omics Suite},\n  author = {MICOS-2024 Team},\n  year = {2024},\n  url = {https://github.com/BGI-MICOS/MICOS-2024},\n  version = {1.1.0}\n}\n</code></pre> <p>Also cite individual tools used (Kraken2, HUMAnN, QIIME2, etc.)</p>"},{"location":"en/faq.html#what-license-is-micos-2024-under","title":"What license is MICOS-2024 under?","text":"<p>MIT License - free for academic and commercial use.</p>"},{"location":"en/faq.html#still-have-questions","title":"Still Have Questions?","text":"<ul> <li>\ud83d\udcd6 Check the User Manual</li> <li>\ud83d\udd27 See Troubleshooting</li> <li>\ud83d\udcac Start a Discussion</li> <li>\ud83d\udc1b Report an Issue</li> </ul>"},{"location":"en/functional-profiling.html","title":"Functional Profiling","text":"<p>Complete guide to functional annotation and pathway analysis using HUMAnN within MICOS-2024.</p>"},{"location":"en/functional-profiling.html#table-of-contents","title":"Table of Contents","text":"<ul> <li>Overview</li> <li>Methodology</li> <li>Input Requirements</li> <li>Running the Analysis</li> <li>Parameter Configuration</li> <li>Output Files</li> <li>Result Interpretation</li> <li>Downstream Analysis</li> <li>Advanced Topics</li> <li>Troubleshooting</li> </ul>"},{"location":"en/functional-profiling.html#overview","title":"Overview","text":"<p>Functional profiling characterizes the metabolic potential of microbial communities by quantifying gene families and metabolic pathways. Unlike taxonomic profiling which answers \"who is there?\", functional profiling answers \"what can they do?\"</p>"},{"location":"en/functional-profiling.html#key-features","title":"Key Features","text":"<ul> <li>Gene family quantification: UniRef90 protein clusters</li> <li>Pathway analysis: MetaCyc metabolic pathways</li> <li>Species stratification: Attribute functions to specific taxa</li> <li>Multi-sample integration: Compare functional profiles across samples</li> </ul>"},{"location":"en/functional-profiling.html#methodology","title":"Methodology","text":""},{"location":"en/functional-profiling.html#humann-analysis-pipeline","title":"HUMAnN Analysis Pipeline","text":"<pre><code>Input Reads\n    \u2193\n[MetaPhlAn] \u2192 Taxonomic profile\n    \u2193\n[Mapping] \u2192 Split reads by species\n    \u2193\n[ChocoPhlAn] \u2192 Align to pangenomes (nucleotide)\n    \u2193\n[UniRef90] \u2192 Align unmapped to proteins\n    \u2193\n[Pathway Reconstruction] \u2192 MinPath + gap filling\n    \u2193\nGene Families + Pathway Abundance + Coverage\n</code></pre>"},{"location":"en/functional-profiling.html#algorithm-overview","title":"Algorithm Overview","text":"<ol> <li>Taxonomic Profiling (MetaPhlAn)</li> <li>Quickly identify species present</li> <li> <p>Guide nucleotide search strategy</p> </li> <li> <p>Nucleotide-level Search (ChocoPhlAn)</p> </li> <li>Map reads to species-specific gene families</li> <li> <p>High sensitivity for known species</p> </li> <li> <p>Protein-level Search (UniRef90)</p> </li> <li>Diamond alignment for unmapped reads</li> <li> <p>Detect novel functions</p> </li> <li> <p>Pathway Reconstruction (MinPath)</p> </li> <li>Identify complete metabolic pathways</li> <li>Conservative: pathway must have all required reactions</li> </ol>"},{"location":"en/functional-profiling.html#functional-ontologies","title":"Functional Ontologies","text":"Level Database Description Gene Families UniRef90 Groups of protein sequences (&gt;90% identical) Pathways MetaCyc Curated metabolic pathways Modules KEGG Functional units of metabolism"},{"location":"en/functional-profiling.html#input-requirements","title":"Input Requirements","text":""},{"location":"en/functional-profiling.html#input-data","title":"Input Data","text":"Source Format Description KneadData output FASTQ Quality-controlled, host-removed reads Any cleaned reads FASTQ/FASTA Adapter-trimmed, quality-filtered"},{"location":"en/functional-profiling.html#file-structure","title":"File Structure","text":"<pre><code>input_dir/\n\u251c\u2500\u2500 sample1_paired_1.fastq.gz\n\u251c\u2500\u2500 sample1_paired_2.fastq.gz\n\u251c\u2500\u2500 sample1_unmatched_1.fastq.gz\n\u251c\u2500\u2500 sample1_unmatched_2.fastq.gz\n\u251c\u2500\u2500 sample2_paired_1.fastq.gz\n\u2514\u2500\u2500 ...\n</code></pre> <p>Note: HUMAnN automatically detects paired and unpaired reads.</p>"},{"location":"en/functional-profiling.html#database-requirements","title":"Database Requirements","text":"Database Size Description ChocoPhlAn ~10 GB Nucleotide pangenome database UniRef90 ~20 GB Protein families (&gt;90% identity) UniRef50 ~5 GB Reduced protein families (&gt;50% identity) MetaCyc Included Metabolic pathway definitions <p>Storage tip: Use UniRef50 for faster processing, UniRef90 for comprehensive results.</p>"},{"location":"en/functional-profiling.html#running-the-analysis","title":"Running the Analysis","text":""},{"location":"en/functional-profiling.html#option-1-micos-cli","title":"Option 1: MICOS CLI","text":"<pre><code># Functional annotation only\npython -m micos.cli run functional-annotation \\\n  --input-dir results/quality_control/kneaddata \\\n  --output-dir results/functional_annotation \\\n  --threads 16\n\n# As part of full pipeline\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16 \\\n  --kneaddata-db /db/kneaddata \\\n  --kraken2-db /db/kraken2\n</code></pre>"},{"location":"en/functional-profiling.html#option-2-direct-humann","title":"Option 2: Direct HUMAnN","text":"<pre><code># Basic run\nhumann --input sample.fastq \\\n  --output output_dir/ \\\n  --nucleotide-database /db/chocophlan \\\n  --protein-database /db/uniref90 \\\n  --threads 16\n\n# Separate steps for control\n# Step 1: Gene family quantification\nhumann --input sample.fastq \\\n  --output output_dir/ \\\n  --bypass-translated-search\n\n# Step 2: Regroup to other ontologies\nhumann_regroup_table \\\n  -i sample_genefamilies.tsv \\\n  -g uniref90_ko \\\n  -o sample_ko.tsv\n\n# Step 3: Pathway annotation\nhumann --input sample.fastq \\\n  --output output_dir/ \\\n  --resume \\\n  --gap-fill on \\\n  --minpath on\n</code></pre>"},{"location":"en/functional-profiling.html#parameter-configuration","title":"Parameter Configuration","text":""},{"location":"en/functional-profiling.html#humann-configuration","title":"HUMAnN Configuration","text":"<pre><code>functional_annotation:\n  enabled: true\n\n  humann:\n    enabled: true\n    threads: 16\n\n    # Database paths\n    nucleotide_database: \"${paths.databases}/humann/chocophlan\"\n    protein_database: \"${paths.databases}/humann/uniref90\"\n\n    # Search options\n    search_mode: \"diamond\"    # diamond or usearch\n\n    # Sensitivity vs speed trade-off\n    diamond_options: \"--mid-sensitive\"\n\n    # Pathway options\n    pathway_coverage: true\n    gap_fill: true            # Fill pathway gaps\n    minpath: true             # Use MinPath for pathway selection\n\n    # Output options\n    remove_temp: true\n</code></pre>"},{"location":"en/functional-profiling.html#database-selection-guide","title":"Database Selection Guide","text":"Database Time Sensitivity Use Case ChocoPhlAn only Fast Species-dependent Known species abundant + UniRef50 Moderate Good Balance speed/coverage + UniRef90 Slow Best Maximum sensitivity"},{"location":"en/functional-profiling.html#performance-tuning","title":"Performance Tuning","text":"<pre><code>functional_annotation:\n  humann:\n    # Fast mode (for large datasets)\n    threads: 32\n    diamond_options: \"--fast\"\n\n    # Comprehensive mode (for publication)\n    threads: 16\n    diamond_options: \"--sensitive\"\n    gap_fill: true\n    pathway_coverage: true\n</code></pre>"},{"location":"en/functional-profiling.html#output-files","title":"Output Files","text":""},{"location":"en/functional-profiling.html#directory-structure","title":"Directory Structure","text":"<pre><code>results/functional_annotation/\n\u251c\u2500\u2500 sample_genefamilies.tsv         # Gene family abundances\n\u251c\u2500\u2500 sample_genefamilies-cpm.tsv     # Normalized to CPM\n\u251c\u2500\u2500 sample_pathabundance.tsv        # Pathway abundances\n\u251c\u2500\u2500 sample_pathcoverage.tsv         # Pathway coverage\n\u251c\u2500\u2500 sample_pathabundance-cpm.tsv    # Normalized pathway\n\u2514\u2500\u2500 sample.log                      # Run log\n</code></pre>"},{"location":"en/functional-profiling.html#gene-families-file","title":"Gene Families File","text":"Column Description Example # Gene Family UniRef90 cluster UniRef90_A0A0A0MQD6 Sample1 Abundance (RPK) 45.23 Sample2 Abundance (RPK) 12.56 <p>Special entries: - <code>UNMAPPED</code>: Reads not matching any gene - <code>UNGROUPED</code>: Genes not in any UniRef cluster</p>"},{"location":"en/functional-profiling.html#pathway-abundance-file","title":"Pathway Abundance File","text":"Column Description Example # Pathway MetaCyc pathway GLYCOLYSIS Sample1 Abundance 145.2 <p>Stratified format: <code>PATHWAY|Species</code> shows species contribution</p> <p>Example: <pre><code>GLYCOLYSIS|g__Bacteroides.s__Bacteroides_thetaiotaomicron    45.2\nGLYCOLYSIS|g__Faecalibacterium.s__Faecalibacterium_prausnitzii    32.1\nGLYCOLYSIS|unclassified    12.5\n</code></pre></p>"},{"location":"en/functional-profiling.html#pathway-coverage-file","title":"Pathway Coverage File","text":"<p>Coverage indicates pathway completeness (0-1 scale):</p> Coverage Interpretation 1.0 Complete pathway present 0.5-0.9 Partial pathway &lt; 0.5 Fragmented pathway"},{"location":"en/functional-profiling.html#result-interpretation","title":"Result Interpretation","text":""},{"location":"en/functional-profiling.html#quality-metrics","title":"Quality Metrics","text":""},{"location":"en/functional-profiling.html#mapping-rate","title":"Mapping Rate","text":"<pre><code># Check mapping statistics in log file\ngrep \"total aligned\" sample.log\n</code></pre> Mapping Rate Interpretation Action &lt; 20% Poor Check data quality and database 20-50% Moderate Acceptable for novel communities 50-70% Good Standard performance &gt; 70% Excellent High-quality reference genomes"},{"location":"en/functional-profiling.html#unmapped-reads","title":"Unmapped Reads","text":"<p>High unmapped rate may indicate: - Novel taxa not in reference - Viral sequences - Host contamination (check QC) - Low-quality sequencing</p>"},{"location":"en/functional-profiling.html#functional-richness","title":"Functional Richness","text":"<pre><code># Count unique gene families\ncut -f1 sample_genefamilies.tsv | tail -n +2 | wc -l\n\n# Count pathways\ncut -f1 sample_pathabundance.tsv | tail -n +2 | wc -l\n</code></pre> <p>Typical ranges for human gut: - Gene families: 100,000-500,000 - Pathways: 200-400</p>"},{"location":"en/functional-profiling.html#top-functions","title":"Top Functions","text":"<pre><code># Top gene families (after normalization)\nsort -k2,2nr sample_genefamilies-cpm.tsv | head -20\n\n# Top pathways\nsort -k2,2nr sample_pathabundance-cpm.tsv | head -20\n</code></pre>"},{"location":"en/functional-profiling.html#downstream-analysis","title":"Downstream Analysis","text":""},{"location":"en/functional-profiling.html#normalization","title":"Normalization","text":"<pre><code># CPM (Copies Per Million) normalization\nhumann_renorm_table \\\n  -i sample_genefamilies.tsv \\\n  -o sample_genefamilies-cpm.tsv \\\n  --units cpm\n\n# Relative abundance (fraction of total)\nhumann_renorm_table \\\n  -i sample_genefamilies.tsv \\\n  -o sample_genefamilies-relab.tsv \\\n  --units relab\n</code></pre>"},{"location":"en/functional-profiling.html#stratification-analysis","title":"Stratification Analysis","text":"<pre><code># Split stratified table\nhumann_split_stratified_table \\\n  -i sample_genefamilies-cpm.tsv \\\n  -o stratified/\n\n# Outputs:\n#   stratified/sample_genefamilies-stratified.tsv\n#   stratified/sample_genefamilies-unstratified.tsv\n</code></pre>"},{"location":"en/functional-profiling.html#regrouping-to-other-ontologies","title":"Regrouping to Other Ontologies","text":"<pre><code># To KEGG Orthology (KO)\nhumann_regroup_table \\\n  -i sample_genefamilies.tsv \\\n  -g uniref90_ko \\\n  -o sample_ko.tsv\n\n# To GO terms\nhumann_regroup_table \\\n  -i sample_genefamilies.tsv \\\n  -g uniref90_go \\\n  -o sample_go.tsv\n\n# To EC numbers\nhumann_regroup_table \\\n  -i sample_genefamilies.tsv \\\n  -g uniref90_ec \\\n  -o sample_ec.tsv\n</code></pre>"},{"location":"en/functional-profiling.html#multi-sample-analysis","title":"Multi-Sample Analysis","text":"<pre><code># Join multiple samples\nhumann_join_tables \\\n  -i results/functional_annotation/ \\\n  -o merged_genefamilies.tsv \\\n  --file_name genefamilies\n\n# Normalize merged table\nhumann_renorm_table \\\n  -i merged_genefamilies.tsv \\\n  -o merged_genefamilies-cpm.tsv \\\n  --units cpm\n</code></pre>"},{"location":"en/functional-profiling.html#association-testing","title":"Association Testing","text":"<pre><code># Test association with metadata\nhumann_associate \\\n  -i merged_genefamilies-cpm.tsv \\\n  -m metadata.tsv \\\n  -f group \\\n  -o association_results.tsv\n</code></pre>"},{"location":"en/functional-profiling.html#differential-abundance","title":"Differential Abundance","text":"<pre><code># Using Python/Pandas\nimport pandas as pd\nfrom scipy import stats\n\n# Load normalized data\ndf = pd.read_csv('merged_genefamilies-cpm.tsv', \n                 sep='\\t', index_col=0)\n\n# Load metadata\nmeta = pd.read_csv('metadata.tsv', sep='\\t', index_col=0)\n\n# Perform t-test for each gene family\nresults = []\nfor gene in df.index:\n    group_a = df.loc[gene, meta['group'] == 'Control']\n    group_b = df.loc[gene, meta['group'] == 'Treatment']\n\n    t_stat, p_val = stats.ttest_ind(group_a, group_b)\n    results.append({'gene': gene, 'p_value': p_val})\n\nresults_df = pd.DataFrame(results)\n</code></pre>"},{"location":"en/functional-profiling.html#advanced-topics","title":"Advanced Topics","text":""},{"location":"en/functional-profiling.html#custom-gene-families","title":"Custom Gene Families","text":"<pre><code># Create custom database\nhumann_databases --download chocophlan full /custom/path\n\n# Add custom sequences\ncat custom_genes.fa &gt;&gt; /custom/path/chocophlan/*.ffn\n</code></pre>"},{"location":"en/functional-profiling.html#focused-pathway-analysis","title":"Focused Pathway Analysis","text":"<pre><code># Analyze specific pathways only\nhumann --input sample.fastq \\\n  --output output/ \\\n  --pathways metacyc \\\n  --gap-fill on \\\n  --pathway min\n</code></pre>"},{"location":"en/functional-profiling.html#metatranscriptome-integration","title":"Metatranscriptome Integration","text":"<pre><code># Use HUMAnN with transcriptomic data\nhumann --input sample_rna.fastq \\\n  --output rnaseq_output/ \\\n  --bypass-prescreen  # Don't skip protein search\n</code></pre>"},{"location":"en/functional-profiling.html#troubleshooting","title":"Troubleshooting","text":""},{"location":"en/functional-profiling.html#issue-running-too-slow","title":"Issue: Running Too Slow","text":"<p>Solutions: <pre><code># Use faster settings\nfunctional_annotation:\n  humann:\n    diamond_options: \"--fast\"\n    threads: 32\n    # Or use UniRef50 instead of UniRef90\n    protein_database: \"/db/uniref50\"\n</code></pre></p>"},{"location":"en/functional-profiling.html#issue-memory-errors","title":"Issue: Memory Errors","text":"<p>Solutions: <pre><code># Reduce threads\nhumann --threads 8 ...\n\n# Use memory-efficient mode\nhumann --memory-use minimum ...\n\n# Process samples sequentially instead of parallel\n</code></pre></p>"},{"location":"en/functional-profiling.html#issue-most-reads-unmapped","title":"Issue: Most Reads Unmapped","text":"<p>Diagnostic steps: <pre><code># 1. Check input quality\nfastqc sample.fastq\n\n# 2. Verify database installation\nls -lh /db/humann/chocophlan/\nls -lh /db/humann/uniref90/\n\n# 3. Check species coverage in MetaPhlAn output\n# If unknown species dominate, need broader database\n</code></pre></p>"},{"location":"en/functional-profiling.html#issue-empty-pathway-results","title":"Issue: Empty Pathway Results","text":"<p>Solutions: <pre><code>functional_annotation:\n  humann:\n    gap_fill: true        # Enable gap filling\n    minpath: false        # Disable strict MinPath\n</code></pre></p>"},{"location":"en/functional-profiling.html#see-also","title":"See Also","text":"<ul> <li>Taxonomic Profiling - Species classification</li> <li>Diversity Analysis - Community structure</li> <li>Configuration Guide - Parameter details</li> <li>HUMAnN Documentation - Official HUMAnN docs</li> </ul>"},{"location":"en/installation.html","title":"Installation Guide","text":"<p>Complete installation instructions for MICOS-2024.</p>"},{"location":"en/installation.html#table-of-contents","title":"Table of Contents","text":"<ul> <li>System Requirements</li> <li>Installation Methods</li> <li>Docker (Recommended)</li> <li>Conda/Mamba</li> <li>Source Installation</li> <li>Database Setup</li> <li>Verification</li> <li>Offline Installation</li> <li>Troubleshooting</li> </ul>"},{"location":"en/installation.html#system-requirements","title":"System Requirements","text":""},{"location":"en/installation.html#minimum-requirements","title":"Minimum Requirements","text":"Component Minimum Recommended Operating System Linux (Ubuntu 18.04+) / macOS 11+ Linux (Ubuntu 20.04+) CPU 4 cores 16+ cores Memory (RAM) 16 GB 32+ GB Storage 100 GB HDD 500+ GB SSD Network Internet for installation Internet for database downloads"},{"location":"en/installation.html#software-prerequisites","title":"Software Prerequisites","text":"Software Version Required For Python 3.9+ Core platform Docker 20.10+ Containerized deployment Conda/Mamba 4.10+ Package management"},{"location":"en/installation.html#database-storage-requirements","title":"Database Storage Requirements","text":"Database Size Purpose Kraken2 Standard ~70 GB Species classification Kraken2 MiniKraken ~8 GB Quick testing KneadData Human Genome ~4 GB Host DNA removal HUMAnN ChocoPhlAn ~10 GB Functional annotation HUMAnN UniRef90 ~20 GB Protein families"},{"location":"en/installation.html#installation-methods","title":"Installation Methods","text":""},{"location":"en/installation.html#method-1-docker-installation-recommended","title":"Method 1: Docker Installation (Recommended)","text":"<p>Docker provides the most reproducible environment with all dependencies pre-installed.</p>"},{"location":"en/installation.html#step-1-install-docker","title":"Step 1: Install Docker","text":"<pre><code># Linux (Ubuntu/Debian)\ncurl -fsSL https://get.docker.com -o get-docker.sh\nsudo sh get-docker.sh\nsudo usermod -aG docker $USER\nnewgrp docker\n\n# Verify installation\ndocker --version\ndocker compose version\n</code></pre>"},{"location":"en/installation.html#step-2-clone-repository","title":"Step 2: Clone Repository","text":"<pre><code>git clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\n</code></pre>"},{"location":"en/installation.html#step-3-deploy-with-docker-compose","title":"Step 3: Deploy with Docker Compose","text":"<pre><code># Start all services\ndocker compose -f deploy/docker-compose.example.yml up -d\n\n# Verify services are running\ndocker compose -f deploy/docker-compose.example.yml ps\n\n# View logs\ndocker compose -f deploy/docker-compose.example.yml logs -f\n</code></pre>"},{"location":"en/installation.html#step-4-access-container","title":"Step 4: Access Container","text":"<pre><code># Enter the main analysis container\ndocker compose -f deploy/docker-compose.example.yml exec micos bash\n\n# Run analysis\npython -m micos.cli --help\n</code></pre> <p>Advantages: - \u2705 Complete environment isolation - \u2705 No dependency conflicts - \u2705 Easy to reproduce across systems</p>"},{"location":"en/installation.html#method-2-conda-installation","title":"Method 2: Conda Installation","text":"<p>Conda/Mamba provides flexible installation with good performance.</p>"},{"location":"en/installation.html#step-1-install-miniforge-recommended","title":"Step 1: Install Miniforge (Recommended)","text":"<pre><code># Download Miniforge installer\nwget https://github.com/conda-forge/miniforge/releases/latest/download/Miniforge3-Linux-x86_64.sh\n\n# Run installer\nbash Miniforge3-Linux-x86_64.sh -b -p $HOME/miniforge\n\n# Initialize shell\n$HOME/miniforge/bin/conda init bash\nsource ~/.bashrc\n</code></pre>"},{"location":"en/installation.html#step-2-create-environment","title":"Step 2: Create Environment","text":"<pre><code># Clone repository\ngit clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\n\n# Create environment with mamba (faster)\nmamba env create -f environment.yml\n\n# Activate environment\nconda activate micos-2024\n</code></pre>"},{"location":"en/installation.html#step-3-install-micos-package","title":"Step 3: Install MICOS Package","text":"<pre><code># Install in editable mode for development\npip install -e .\n\n# Or install normally\npip install .\n</code></pre>"},{"location":"en/installation.html#step-4-verify-tools","title":"Step 4: Verify Tools","text":"<pre><code># Check core dependencies\nkraken2 --version\nhumann --version\nqiime --version\nkneaddata --version\n</code></pre> <p>Advantages: - \u2705 Native performance - \u2705 Easy customization - \u2705 Good for development</p>"},{"location":"en/installation.html#method-3-source-installation","title":"Method 3: Source Installation","text":"<p>For developers who want to modify the code.</p>"},{"location":"en/installation.html#step-1-system-dependencies","title":"Step 1: System Dependencies","text":"<pre><code># Ubuntu/Debian\nsudo apt-get update\nsudo apt-get install -y \\\n    build-essential \\\n    python3-dev \\\n    python3-pip \\\n    git \\\n    wget \\\n    curl\n\n# Install bioinformatics tools manually\n# See individual tool documentation for details\n</code></pre>"},{"location":"en/installation.html#step-2-python-environment","title":"Step 2: Python Environment","text":"<pre><code># Create virtual environment\npython3 -m venv micos-env\nsource micos-env/bin/activate\n\n# Install Python dependencies\npip install -r requirements.txt\npip install -r requirements-dev.txt  # For development\n</code></pre>"},{"location":"en/installation.html#step-3-install-micos","title":"Step 3: Install MICOS","text":"<pre><code>git clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\npip install -e .\n</code></pre> <p>Advantages: - \u2705 Full control over installation - \u2705 Easy to modify source code - \u2705 Minimal overhead</p>"},{"location":"en/installation.html#database-setup","title":"Database Setup","text":""},{"location":"en/installation.html#automated-database-download","title":"Automated Database Download","text":"<pre><code># Run database download script\npython scripts/download_databases.py \\\n  --output-dir /path/to/databases \\\n  --databases kraken2,kneaddata,humann\n</code></pre>"},{"location":"en/installation.html#manual-database-setup","title":"Manual Database Setup","text":""},{"location":"en/installation.html#kraken2-database","title":"Kraken2 Database","text":"<pre><code># Create database directory\nmkdir -p /path/to/kraken2_db\n\n# Download and build standard database (requires ~70GB)\nkraken2-build --download-taxonomy --db /path/to/kraken2_db\nkraken2-build --download-library bacteria --db /path/to/kraken2_db\nkraken2-build --download-library archaea --db /path/to/kraken2_db\nkraken2-build --build --db /path/to/kraken2_db --threads 16\n\n# Or download pre-built MiniKraken (quick start, ~8GB)\nwget https://genome-idx.s3.amazonaws.com/kraken/minikraken2_v2_8GB_201904_UPDATE.tgz\ntar -xzf minikraken2_v2_8GB_201904_UPDATE.tgz\n</code></pre>"},{"location":"en/installation.html#kneaddata-database","title":"KneadData Database","text":"<pre><code># Download human genome reference\nkneaddata_database --download human_genome bowtie2 /path/to/kneaddata_db\n</code></pre>"},{"location":"en/installation.html#humann-database","title":"HUMAnN Database","text":"<pre><code># Download functional databases\nhumann_databases --download chocophlan full /path/to/humann_db\nhumann_databases --download uniref uniref90_diamond /path/to/humann_db\n</code></pre>"},{"location":"en/installation.html#database-configuration","title":"Database Configuration","text":"<p>Create <code>config/databases.yaml</code>:</p> <pre><code>database_root: \"/path/to/databases\"\n\nquality_control:\n  kneaddata:\n    human_genome: \"${database_root}/kneaddata/human_genome\"\n\ntaxonomy:\n  kraken2:\n    standard: \"${database_root}/kraken2/standard\"\n    minikraken: \"${database_root}/kraken2/minikraken\"\n\nfunctional:\n  humann:\n    chocophlan: \"${database_root}/humann/chocophlan\"\n    uniref90: \"${database_root}/humann/uniref90\"\n</code></pre>"},{"location":"en/installation.html#verification","title":"Verification","text":""},{"location":"en/installation.html#step-1-installation-verification","title":"Step 1: Installation Verification","text":"<pre><code># Run verification script\n./scripts/verify_installation.sh\n</code></pre> <p>Expected output: <pre><code>\u2713 Python 3.9+ found\n\u2713 Kraken2 installed\n\u2713 HUMAnN installed\n\u2713 QIIME2 installed\n\u2713 Kneaddata installed\n\u2713 All dependencies satisfied\n</code></pre></p>"},{"location":"en/installation.html#step-2-test-run","title":"Step 2: Test Run","text":"<pre><code># Download test data\npython scripts/download_test_data.py --output-dir test_data\n\n# Run quick test\npython -m micos.cli full-run \\\n  --input-dir test_data \\\n  --results-dir test_results \\\n  --threads 4 \\\n  --kneaddata-db /path/to/kneaddata_db \\\n  --kraken2-db /path/to/kraken2_minikraken\n</code></pre>"},{"location":"en/installation.html#step-3-check-output","title":"Step 3: Check Output","text":"<pre><code># Verify outputs exist\nls test_results/\n# Should show: quality_control/, taxonomic_profiling/, functional_annotation/, report.html\n</code></pre>"},{"location":"en/installation.html#offline-installation","title":"Offline Installation","text":"<p>For systems without internet access:</p>"},{"location":"en/installation.html#step-1-prepare-on-online-system","title":"Step 1: Prepare on Online System","text":"<pre><code># Download packages\npip download \\\n  -r requirements.txt \\\n  -d ./offline_packages \\\n  --platform manylinux2014_x86_64\n\n# Export conda environment\nconda env export --no-builds &gt; environment-offline.yml\n\n# Download databases (see Database Setup section)\n</code></pre>"},{"location":"en/installation.html#step-2-transfer-to-offline-system","title":"Step 2: Transfer to Offline System","text":"<p>Transfer these directories to the offline system: - <code>offline_packages/</code> - <code>MICOS-2024/</code> (source code) - Database files</p>"},{"location":"en/installation.html#step-3-install-offline","title":"Step 3: Install Offline","text":"<pre><code># Install from local packages\npip install --no-index --find-links=./offline_packages -r requirements.txt\n\n# Install MICOS\npip install -e MICOS-2024/\n</code></pre>"},{"location":"en/installation.html#troubleshooting","title":"Troubleshooting","text":""},{"location":"en/installation.html#issue-docker-permission-denied","title":"Issue: Docker Permission Denied","text":"<pre><code># Add user to docker group\nsudo usermod -aG docker $USER\nnewgrp docker\n\n# Verify\ndocker run hello-world\n</code></pre>"},{"location":"en/installation.html#issue-conda-environment-creation-fails","title":"Issue: Conda Environment Creation Fails","text":"<pre><code># Clear conda cache\nconda clean --all\n\n# Update conda\nconda update -n base conda\n\n# Try with mamba\nconda install mamba -c conda-forge -n base\nmamba env create -f environment.yml --force\n</code></pre>"},{"location":"en/installation.html#issue-database-download-fails","title":"Issue: Database Download Fails","text":"<pre><code># Use mirror sites\n# For China users:\nexport KRAKEN2_DB_MIRROR=\"https://mirrors.tuna.tsinghua.edu.cn/\"\n\n# Or download manually from:\n# https://benlangmead.github.io/aws-indexes/k2\n</code></pre>"},{"location":"en/installation.html#issue-memory-error-during-database-build","title":"Issue: Memory Error During Database Build","text":"<pre><code># Reduce threads during build\nkraken2-build --build --db /path/to/db --threads 4\n\n# Or use pre-built databases\nwget https://genome-idx.s3.amazonaws.com/kraken/k2_standard_20231009.tar.gz\n</code></pre>"},{"location":"en/installation.html#next-steps","title":"Next Steps","text":"<ul> <li>\ud83d\udcd6 User Manual - Learn how to use MICOS-2024</li> <li>\u2699\ufe0f Configuration Guide - Customize your analysis</li> <li>\ud83e\uddea Test Data - Run example analysis</li> </ul>"},{"location":"en/installation.html#getting-help","title":"Getting Help","text":"<ul> <li>\ud83d\udccb FAQ</li> <li>\ud83d\udd27 Troubleshooting</li> <li>\ud83d\udcac GitHub Discussions</li> <li>\ud83d\udc1b Report Issues</li> </ul>"},{"location":"en/taxonomic-profiling.html","title":"Taxonomic Profiling","text":"<p>Complete guide to taxonomic classification and diversity analysis using MICOS-2024.</p>"},{"location":"en/taxonomic-profiling.html#table-of-contents","title":"Table of Contents","text":"<ul> <li>Overview</li> <li>Methodology</li> <li>Workflow</li> <li>Input Requirements</li> <li>Running the Analysis</li> <li>Parameter Configuration</li> <li>Output Files</li> <li>Result Interpretation</li> <li>Advanced Topics</li> <li>Troubleshooting</li> </ul>"},{"location":"en/taxonomic-profiling.html#overview","title":"Overview","text":"<p>The taxonomic profiling module identifies and quantifies the microbial species present in your metagenomic samples. It integrates quality control, sequence classification, and diversity analysis into a comprehensive pipeline.</p>"},{"location":"en/taxonomic-profiling.html#key-features","title":"Key Features","text":"<ul> <li>High-speed classification: Kraken2 processes ~10M reads/minute</li> <li>Accurate abundance estimation: Bracken improves species-level quantification</li> <li>Interactive visualization: Krona charts for exploring taxonomic composition</li> <li>Diversity metrics: Alpha and beta diversity via QIIME2</li> <li>Statistical analysis: Differential abundance testing</li> </ul>"},{"location":"en/taxonomic-profiling.html#methodology","title":"Methodology","text":""},{"location":"en/taxonomic-profiling.html#classification-algorithm-kraken2","title":"Classification Algorithm (Kraken2)","text":"<p>Kraken2 uses k-mer based classification:</p> <ol> <li>Database Construction: Reference genomes are broken into k-mers (default k=35)</li> <li>Minimizer Indexing: Reduces memory usage by storing minimizers only</li> <li>Classification: Input reads matched against database using LCA (Lowest Common Ancestor) algorithm</li> <li>Confidence Scoring: Classification confidence based on k-mer coverage</li> </ol> <pre><code>Read: ATCGATCGATCGATCGATCGATCG...\n         \u2193\nK-mers: [ATCGATCGATCGATC], [TCGATCGATCGATCG], ...\n         \u2193\nDatabase lookup \u2192 LCA assignment \u2192 Confidence score\n</code></pre>"},{"location":"en/taxonomic-profiling.html#abundance-correction-bracken","title":"Abundance Correction (Bracken)","text":"<p>Bracken corrects for: - Genome size bias: Larger genomes contribute more reads - Database coverage: Incomplete reference databases - Strain variation: Multiple strains of same species</p>"},{"location":"en/taxonomic-profiling.html#taxonomic-ranks","title":"Taxonomic Ranks","text":"Rank Code Example Domain D Bacteria Phylum P Proteobacteria Class C Gammaproteobacteria Order O Enterobacterales Family F Enterobacteriaceae Genus G Escherichia Species S Escherichia coli"},{"location":"en/taxonomic-profiling.html#workflow","title":"Workflow","text":"<pre><code>graph TD\n    A[Raw FASTQ] --&gt; B[Quality Control&lt;br/&gt;KneadData]\n    B --&gt; C[Taxonomic Classification&lt;br/&gt;Kraken2]\n    C --&gt; D[Abundance Correction&lt;br/&gt;Bracken]\n    C --&gt; E[Krona Visualization]\n    D --&gt; F[BIOM Format Conversion]\n    F --&gt; G[Diversity Analysis&lt;br/&gt;QIIME2]\n    G --&gt; H[Statistical Analysis]</code></pre>"},{"location":"en/taxonomic-profiling.html#step-by-step-process","title":"Step-by-Step Process","text":"<ol> <li>Quality Control: Remove host DNA and low-quality reads</li> <li>Classification: Assign reads to taxa using Kraken2</li> <li>Correction: Estimate true abundances with Bracken</li> <li>Visualization: Generate Krona interactive charts</li> <li>Diversity Analysis: Calculate alpha/beta diversity metrics</li> </ol>"},{"location":"en/taxonomic-profiling.html#input-requirements","title":"Input Requirements","text":""},{"location":"en/taxonomic-profiling.html#data-format","title":"Data Format","text":"Format Extension Paired/Single FASTQ (gzip) <code>.fastq.gz</code> Paired or Single FASTQ <code>.fastq</code> Paired or Single"},{"location":"en/taxonomic-profiling.html#naming-convention","title":"Naming Convention","text":"<pre><code>Paired-end:\n  Sample1_R1.fastq.gz\n  Sample1_R2.fastq.gz\n\nSingle-end:\n  Sample1.fastq.gz\n</code></pre>"},{"location":"en/taxonomic-profiling.html#quality-requirements","title":"Quality Requirements","text":"Metric Minimum Recommended Read length \u2265 50 bp \u2265 100 bp Quality score (Q30) &gt; 70% &gt; 85% Depth per sample 1M reads 10M+ reads"},{"location":"en/taxonomic-profiling.html#database-requirements","title":"Database Requirements","text":"Database Size Download Kraken2 Standard ~70 GB AWS Index Kraken2 PlusPF ~100 GB Includes fungi &amp; protozoa MiniKraken2 ~8 GB For testing"},{"location":"en/taxonomic-profiling.html#running-the-analysis","title":"Running the Analysis","text":""},{"location":"en/taxonomic-profiling.html#option-1-complete-pipeline","title":"Option 1: Complete Pipeline","text":"<pre><code>python -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16 \\\n  --kneaddata-db /path/to/kneaddata_db \\\n  --kraken2-db /path/to/kraken2_db\n</code></pre>"},{"location":"en/taxonomic-profiling.html#option-2-taxonomic-profiling-only","title":"Option 2: Taxonomic Profiling Only","text":"<pre><code>python -m micos.cli run taxonomic-profiling \\\n  --input-dir data/cleaned_reads \\\n  --output-dir results/taxonomy \\\n  --threads 16 \\\n  --kraken2-db /path/to/kraken2_db \\\n  --confidence 0.1\n</code></pre>"},{"location":"en/taxonomic-profiling.html#option-3-manual-steps","title":"Option 3: Manual Steps","text":"<pre><code># Step 1: Run Kraken2\nkraken2 --db /path/to/kraken2_db \\\n  --paired sample_R1.fastq sample_R2.fastq \\\n  --output sample.kraken \\\n  --report sample.report \\\n  --confidence 0.1 \\\n  --threads 16\n\n# Step 2: Run Bracken\nbracken -d /path/to/kraken2_db \\\n  -i sample.report \\\n  -o sample.bracken \\\n  -r 150 \\\n  -l S\n\n# Step 3: Convert to BIOM\nkraken-biom *.report --fmt hdf5 -o feature-table.biom\n\n# Step 4: Generate Krona\nktImportTaxonomy -o sample.krona.html sample.report\n</code></pre>"},{"location":"en/taxonomic-profiling.html#parameter-configuration","title":"Parameter Configuration","text":""},{"location":"en/taxonomic-profiling.html#kraken2-parameters","title":"Kraken2 Parameters","text":"<pre><code>taxonomic_profiling:\n  kraken2:\n    # Classification confidence (0.0 - 1.0)\n    # Higher = more stringent, fewer classified reads\n    confidence: 0.1\n\n    # Minimum base quality for k-mer matching\n    min_base_quality: 20\n\n    # Minimum hit groups required\n    min_hit_groups: 2\n\n    # Use memory-mapped database (faster, more RAM)\n    memory_mapping: true\n\n    # Include scientific names in output\n    use_names: true\n</code></pre>"},{"location":"en/taxonomic-profiling.html#confidence-threshold-selection","title":"Confidence Threshold Selection","text":"Value Sensitivity Precision Use Case 0.0 Very High Lower Exploratory analysis 0.1 High Good Default, balanced 0.3 Moderate High Conservative analysis 0.5 Low Very High High confidence only"},{"location":"en/taxonomic-profiling.html#bracken-parameters","title":"Bracken Parameters","text":"<pre><code>taxonomic_profiling:\n  bracken:\n    enabled: true\n\n    # Read length (matches your data)\n    read_length: 150\n\n    # Taxonomic level for abundance\n    # D, P, C, O, F, G, S\n    level: \"S\"\n\n    # Threshold for Bracken re-estimation\n    threshold: 10\n</code></pre>"},{"location":"en/taxonomic-profiling.html#output-files","title":"Output Files","text":""},{"location":"en/taxonomic-profiling.html#directory-structure","title":"Directory Structure","text":"<pre><code>results/taxonomic_profiling/\n\u251c\u2500\u2500 raw/\n\u2502   \u251c\u2500\u2500 sample1.kraken      # Raw classification output\n\u2502   \u2514\u2500\u2500 sample1.report      # Taxonomic report\n\u251c\u2500\u2500 bracken/\n\u2502   \u2514\u2500\u2500 sample1.bracken     # Corrected abundances\n\u251c\u2500\u2500 krona/\n\u2502   \u2514\u2500\u2500 sample1.krona.html  # Interactive visualization\n\u2514\u2500\u2500 biom/\n    \u2514\u2500\u2500 feature-table.biom  # QIIME2-compatible table\n</code></pre>"},{"location":"en/taxonomic-profiling.html#kraken2-report-format","title":"Kraken2 Report Format","text":"Column Description Example 1 Percentage of reads 56.32 2 Number of reads (clade) 563200 3 Number of reads (direct) 10000 4 Rank code S 5 NCBI TaxID 562 6 Scientific name Escherichia coli <p>Rank codes: D=Domain, P=Phylum, C=Class, O=Order, F=Family, G=Genus, S=Species</p>"},{"location":"en/taxonomic-profiling.html#bracken-output-format","title":"Bracken Output Format","text":"Column Description name Taxonomic name taxonomy_id NCBI TaxID taxonomy_lvl Taxonomic level kraken_assigned_reads Raw Kraken2 counts added_reads Estimated additional reads new_est_reads Total estimated reads fraction_total Proportion of total"},{"location":"en/taxonomic-profiling.html#biom-format","title":"BIOM Format","text":"<p>The BIOM file contains: - Observation IDs: Taxa (e.g., k__Bacteria; p__Proteobacteria; ...) - Sample IDs: Your sample names - Data: Count matrix (samples \u00d7 taxa)</p>"},{"location":"en/taxonomic-profiling.html#result-interpretation","title":"Result Interpretation","text":""},{"location":"en/taxonomic-profiling.html#quality-metrics","title":"Quality Metrics","text":""},{"location":"en/taxonomic-profiling.html#classification-rate","title":"Classification Rate","text":"<pre><code># Calculate classification percentage\n# Look for: &gt;70% classified at species level\n\ngrep -E \"^\\s+[0-9]+\\s+[0-9]+\\s+[0-9]+\\s+[URS]\" sample.report | \\\n  awk '{sum+=$2} END {print \"Classified reads:\", sum}'\n</code></pre> Classification Rate Interpretation Action &lt; 50% High unclassified Check database coverage, consider lower confidence 50-70% Moderate Acceptable for most analyses 70-90% Good Standard performance &gt; 90% Excellent High-quality data and good database coverage"},{"location":"en/taxonomic-profiling.html#taxonomic-composition","title":"Taxonomic Composition","text":"<pre><code># Top genera\ngrep \"^G\" sample.report | sort -k1,1nr | head -10\n\n# Top species\ngrep \"^S\" sample.report | sort -k1,1nr | head -10\n</code></pre>"},{"location":"en/taxonomic-profiling.html#krona-visualization","title":"Krona Visualization","text":"<p>The Krona HTML allows: - Exploring taxonomic hierarchy: Click to zoom in/out - Comparing samples: Multiple reports in one chart - Exporting: SVG/PNG export for publication</p>"},{"location":"en/taxonomic-profiling.html#diversity-metrics","title":"Diversity Metrics","text":""},{"location":"en/taxonomic-profiling.html#alpha-diversity-within-sample","title":"Alpha Diversity (Within Sample)","text":"Metric Measures Range Notes Shannon Diversity (richness + evenness) 0 - ~7 Higher = more diverse Chao1 Richness estimator 0+ Sensitive to rare taxa Simpson Evenness 0-1 Lower = more even Observed Features Raw richness 0+ Number of taxa <p>Typical values for human gut: - Shannon: 2.5-4.5 - Observed species: 50-200</p>"},{"location":"en/taxonomic-profiling.html#beta-diversity-between-samples","title":"Beta Diversity (Between Samples)","text":"Metric Type Use Case Bray-Curtis Abundance-based Community composition Jaccard Presence/absence Species overlap UniFrac Phylogenetic Evolutionary distance Weighted UniFrac Abundance + phylogeny Combined view"},{"location":"en/taxonomic-profiling.html#advanced-topics","title":"Advanced Topics","text":""},{"location":"en/taxonomic-profiling.html#custom-database-creation","title":"Custom Database Creation","text":"<pre><code># Build custom Kraken2 database\nkraken2-build --download-taxonomy --db custom_db\nkraken2-build --add-to-library custom_genome.fa --db custom_db\nkraken2-build --build --threads 16 --db custom_db\n</code></pre>"},{"location":"en/taxonomic-profiling.html#strain-level-analysis","title":"Strain-Level Analysis","text":"<pre><code># Use higher-confidence threshold for strain analysis\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.3\n    use_names: true\n</code></pre>"},{"location":"en/taxonomic-profiling.html#time-series-analysis","title":"Time-Series Analysis","text":"<pre><code># Run with metadata for longitudinal analysis\npython -m micos.cli run diversity-analysis \\\n  --input-biom feature-table.biom \\\n  --metadata metadata.tsv \\\n  --output-dir results/diversity\n</code></pre>"},{"location":"en/taxonomic-profiling.html#troubleshooting","title":"Troubleshooting","text":""},{"location":"en/taxonomic-profiling.html#issue-low-classification-rate","title":"Issue: Low Classification Rate","text":"<p>Symptoms: &lt;50% reads classified</p> <p>Solutions: <pre><code># 1. Lower confidence threshold\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.05\n\n# 2. Use larger database\n# Switch from MiniKraken to Standard\n\n# 3. Check data quality\n# Run FastQC on input reads\n</code></pre></p>"},{"location":"en/taxonomic-profiling.html#issue-database-loading-slow","title":"Issue: Database Loading Slow","text":"<p>Symptoms: Kraken2 takes long time to start</p> <p>Solutions: <pre><code># Use memory mapping\ntaxonomic_profiling:\n  kraken2:\n    memory_mapping: true\n\n# Or use SSD for database storage\n</code></pre></p>"},{"location":"en/taxonomic-profiling.html#issue-empty-krona-charts","title":"Issue: Empty Krona Charts","text":"<p>Symptoms: Krona HTML shows no data</p> <p>Solutions: <pre><code># Check Kraken2 report format\nhead -5 sample.report\n\n# Regenerate Krona\nktImportTaxonomy sample.report -o sample.krona.html\n</code></pre></p>"},{"location":"en/taxonomic-profiling.html#see-also","title":"See Also","text":"<ul> <li>Diversity Analysis - Detailed diversity metrics</li> <li>Functional Profiling - Functional analysis</li> <li>Configuration Guide - Parameter reference</li> </ul>"},{"location":"en/troubleshooting.html","title":"Troubleshooting Guide","text":"<p>Comprehensive solutions for common MICOS-2024 issues.</p>"},{"location":"en/troubleshooting.html#table-of-contents","title":"Table of Contents","text":"<ul> <li>Diagnostic Quick Reference</li> <li>Installation Issues</li> <li>Configuration Issues</li> <li>Runtime Errors</li> <li>Performance Issues</li> <li>Data Quality Issues</li> <li>Output Issues</li> <li>Error Code Reference</li> <li>Getting Help</li> </ul>"},{"location":"en/troubleshooting.html#diagnostic-quick-reference","title":"Diagnostic Quick Reference","text":""},{"location":"en/troubleshooting.html#quick-diagnostic-commands","title":"Quick Diagnostic Commands","text":"<pre><code># System resources\nfree -h                              # Memory\ndf -h                                # Disk space\nnproc                                # CPU cores\nulimit -a                            # Resource limits\n\n# Environment\nwhich python\npython --version\nconda list | grep -E \"kraken2|humann|qiime\"\ncollecho $PATH\n\n# Installation check\n./scripts/verify_installation.sh\n\n# Database check\nls -la /path/to/kraken2_db/*.k2d\nls -la /path/to/kneaddata_db/*.bt2\n\n# Log analysis\ntail -f logs/analysis.log\ngrep -i \"error\\|fatal\\|exception\" logs/*.log\n</code></pre>"},{"location":"en/troubleshooting.html#diagnostic-flowchart","title":"Diagnostic Flowchart","text":"<pre><code>Problem occurs\n      \u2193\nCheck logs (logs/error.log)\n      \u2193\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2193                           \u2193\nInstallation Error      Runtime Error\n\u2193                           \u2193\nVerify dependencies    Check input data\n\u2193                           \u2193\nReinstall if needed    Adjust parameters\n</code></pre>"},{"location":"en/troubleshooting.html#installation-issues","title":"Installation Issues","text":""},{"location":"en/troubleshooting.html#issue-conda-environment-creation-fails","title":"Issue: Conda Environment Creation Fails","text":"<p>Symptoms: <pre><code>CondaEnvException: Pip failed\nResolvePackageNotFound\n</code></pre></p> <p>Causes &amp; Solutions:</p> Cause Solution Outdated conda <code>conda update -n base conda</code> Corrupted cache <code>conda clean --all</code> Channel conflicts Use mamba: <code>mamba env create -f environment.yml</code> Network issues Configure mirrors or use offline packages <p>Step-by-Step Fix: <pre><code># 1. Update conda\nconda update -n base -c conda-forge conda\n\n# 2. Clean cache\nconda clean --all -y\n\n# 3. Install mamba (faster solver)\nconda install -n base -c conda-forge mamba\n\n# 4. Create environment with mamba\nmamba env create -f environment.yml\n\n# 5. If still failing, try sequential installation\nconda create -n micos-2024 python=3.9\nconda activate micos-2024\nmamba install kraken2 kneaddata humann\npip install -e .\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-docker-permission-denied","title":"Issue: Docker Permission Denied","text":"<p>Symptoms: <pre><code>permission denied while trying to connect to Docker daemon\n</code></pre></p> <p>Solution: <pre><code># Add user to docker group\nsudo usermod -aG docker $USER\nnewgrp docker\n\n# Verify\ndocker run hello-world\n\n# If still failing, check socket permissions\nls -la /var/run/docker.sock\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-memory-error-during-installation","title":"Issue: Memory Error During Installation","text":"<p>Symptoms: <pre><code>MemoryError: Unable to allocate array\nOSError: Cannot allocate memory\n</code></pre></p> <p>Solutions: <pre><code># Increase swap space\nsudo fallocate -l 16G /swapfile\nsudo chmod 600 /swapfile\nsudo mkswap /swapfile\nsudo swapon /swapfile\n\n# Or reduce parallelism\nexport CONDA_SOLVER_THREADS=2\nmamba env create -f environment.yml\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-package-conflicts","title":"Issue: Package Conflicts","text":"<p>Symptoms: <pre><code>Found conflicts! Looking for incompatible packages.\n</code></pre></p> <p>Solution: <pre><code># Use fresh environment\nconda env create -f environment.yml --force\n\n# Or install in specific order\nconda create -n micos-2024 python=3.9\nconda activate micos-2024\nconda install -c bioconda -c conda-forge kraken2\nconda install -c bioconda -c conda-forge humann\nconda install -c bioconda -c conda-forge kneaddata\npip install -e .\n</code></pre></p>"},{"location":"en/troubleshooting.html#configuration-issues","title":"Configuration Issues","text":""},{"location":"en/troubleshooting.html#issue-database-path-not-found","title":"Issue: Database Path Not Found","text":"<p>Symptoms: <pre><code>FileNotFoundError: [Errno 2] No such file or directory: '/path/to/kraken2_db'\nkraken2: database does not contain necessary file hash.k2d\n</code></pre></p> <p>Diagnosis: <pre><code># Check database files\nls -la /path/to/kraken2_db/\n\n# Verify required files exist\nls hash.k2d opts.k2d taxo.k2d  # For Kraken2\nls *.bt2  # For KneadData/Bowtie2\n</code></pre></p> <p>Solution: <pre><code># 1. Update configuration\nnano config/databases.yaml\n\n# 2. Verify paths\necho \"kraken2: /correct/path/to/kraken2_db\"\n\n# 3. If database missing, download\n# See Installation Guide for database download\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-yaml-syntax-error","title":"Issue: YAML Syntax Error","text":"<p>Symptoms: <pre><code>yaml.scanner.ScannerError: mapping values are not allowed here\nParserError: while parsing a block mapping\n</code></pre></p> <p>Common Causes:</p> Error Example Fix Missing space after colon <code>key:value</code> <code>key: value</code> Tab indentation <code>\\tkey: value</code> <code>key: value</code> Quoted special chars <code>path: \"C:\\temp\"</code> <code>path: 'C:\\temp'</code> <p>Validation: <pre><code># Check YAML syntax\npython -c \"import yaml; yaml.safe_load(open('config/analysis.yaml'))\"\n\n# Or use yamllint\nyamllint config/analysis.yaml\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-sample-metadata-format-error","title":"Issue: Sample Metadata Format Error","text":"<p>Symptoms: <pre><code>ValueError: Sample metadata file format error\nError: Column 'sample-id' not found\n</code></pre></p> <p>Requirements Checklist: - [ ] Tab-delimited format (not comma) - [ ] Header row present - [ ] <code>sample-id</code> column exists - [ ] <code>group</code> column exists for comparisons - [ ] No spaces in column names (use underscores) - [ ] Sample IDs match FASTQ filenames</p> <p>Fix: <pre><code># Convert CSV to TSV\nsed 's/,/\\t/g' samples.csv &gt; samples.tsv\n\n# Verify format\nhead -3 samples.tsv | cat -A\n# Should show tabs (^I) not commas\n\n# Validate column names\nhead -1 samples.tsv | tr '\\t' '\\n' | nl\n</code></pre></p>"},{"location":"en/troubleshooting.html#runtime-errors","title":"Runtime Errors","text":""},{"location":"en/troubleshooting.html#issue-kraken2-classification-fails","title":"Issue: Kraken2 Classification Fails","text":"<p>Symptoms: <pre><code>kraken2: unable to open database\nError reading in hash table\n</code></pre></p> <p>Solutions:</p> <pre><code># 1. Check database integrity\nls -lh /path/to/kraken2_db/\n# Should have: hash.k2d, opts.k2d, taxo.k2d\n\n# 2. Check permissions\nls -la /path/to/kraken2_db/\n\n# 3. Verify memory\nfree -h\n# Database requires ~size of database in RAM\n\n# 4. Re-download if corrupted\nkraken2-build --download-taxonomy --db /new/path\n</code></pre>"},{"location":"en/troubleshooting.html#issue-kneaddata-bowtie2-error","title":"Issue: KneadData Bowtie2 Error","text":"<p>Symptoms: <pre><code>Error: Bowtie2 failed\nError: could not open index file\n</code></pre></p> <p>Solutions: <pre><code># Check index files\nls /path/to/kneaddata_db/*.bt2\n# Should have: .1.bt2, .2.bt2, .3.bt2, .4.bt2, .rev.1.bt2, .rev.2.bt2\n\n# Re-download if needed\nkneaddata_database --download human_genome bowtie2 /new/path\n\n# Check disk space\ndf -h\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-humann-running-very-slow","title":"Issue: HUMAnN Running Very Slow","text":"<p>Symptoms: - Analysis taking &gt;10x expected time - High CPU but minimal progress</p> <p>Solutions: <pre><code># Use faster settings in config\nfunctional_annotation:\n  humann:\n    diamond_options: \"--fast\"\n    threads: 8\n    # Use UniRef50 instead of UniRef90\n    protein_database: \"/db/uniref50\"\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-qiime2-import-error","title":"Issue: QIIME2 Import Error","text":"<p>Symptoms: <pre><code>ValueError: BIOM file appears to be empty\n</code></pre></p> <p>Diagnosis: <pre><code># Check BIOM file\nbiom summarize-table -i feature-table.biom\n\n# If empty, regenerate\nkraken-biom *.report --fmt hdf5 -o new-table.biom\n\n# Check Kraken2 reports\nhead *.report\n# Should have classification data\n</code></pre></p>"},{"location":"en/troubleshooting.html#performance-issues","title":"Performance Issues","text":""},{"location":"en/troubleshooting.html#issue-analysis-is-too-slow","title":"Issue: Analysis Is Too Slow","text":"<p>Optimization Strategies:</p> Strategy Command/Config Expected Speedup Increase threads <code>--threads 32</code> 2-4x Use SSD for temp <code>temp_dir: /ssd/tmp</code> 2-3x Use MiniKraken (testing) <code>--kraken2-db /db/minikraken</code> 5-10x Disable memory mapping <code>memory_mapping: false</code> 1.5x (less RAM) <p>Configuration: <pre><code>resources:\n  max_threads: 32\n  max_memory: \"64GB\"\n\npaths:\n  temp_dir: \"/fast_ssd/tmp\"\n\ntaxonomic_profiling:\n  kraken2:\n    memory_mapping: true    # Faster but more RAM\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-running-out-of-disk-space","title":"Issue: Running Out of Disk Space","text":"<p>Solutions: <pre><code># 1. Clean intermediate files\nrm -rf results/*/intermediate/\nrm -rf tmp/*\n\n# 2. Compress outputs\ngzip results/*/*.fastq\n\n# 3. Enable auto-cleanup in config\nquality_control:\n  kneaddata:\n    remove_intermediate: true\n\n# 4. Use external storage\nln -s /external/storage/results results\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-high-memory-usage","title":"Issue: High Memory Usage","text":"<p>Memory Reduction Strategies:</p> <pre><code># Reduce parallel jobs\nresources:\n  max_threads: 8    # Instead of 16+\n  max_memory: \"16GB\"\n\n# Disable memory mapping for Kraken2\ntaxonomic_profiling:\n  kraken2:\n    memory_mapping: false\n\n# Use smaller database\ndatabases:\n  kraken2: \"/db/minikraken2_v2_8GB\"\n</code></pre>"},{"location":"en/troubleshooting.html#data-quality-issues","title":"Data Quality Issues","text":""},{"location":"en/troubleshooting.html#issue-low-classification-rate","title":"Issue: Low Classification Rate","text":"<p>Normal vs Abnormal:</p> Classification Rate Assessment &gt; 70% Good 50-70% Normal for some environments 30-50% Check quality and database &lt; 30% Problematic <p>Solutions: <pre><code># Lower confidence threshold\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.05\n\n# Use broader database\ndatabases:\n  kraken2: \"/db/kraken2_pluspf\"  # Includes fungi/protozoa\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-sample-fails-qc","title":"Issue: Sample Fails QC","text":"<p>FastQC Warnings to Address:</p> Warning Action Low quality scores Increase <code>min_quality</code> in config Adapter contamination Enable adapter trimming High duplication May be normal for amplicon data GC bias Check for contamination <p>Configuration: <pre><code>quality_control:\n  kneaddata:\n    min_quality: 25      # Increase from 20\n    min_length: 75       # Increase from 50\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-batch-effects-detected","title":"Issue: Batch Effects Detected","text":"<p>Symptoms: - Samples cluster by sequencing run, not biological group - High beta diversity within expected similar samples</p> <p>Solutions: <pre><code># 1. Check metadata for batch information\ncut -f3 metadata.tsv | sort | uniq -c\n\n# 2. Include batch in statistical model\n# Use PERMANOVA with strata\nqiime diversity beta-group-significance \\\n  --i-distance-matrix braycurtis.qza \\\n  --m-metadata-file metadata.tsv \\\n  --m-metadata-column group \\\n  --p-method permanova \\\n  --p-permutations 999 \\\n  --o-visualization results.qzv\n</code></pre></p>"},{"location":"en/troubleshooting.html#output-issues","title":"Output Issues","text":""},{"location":"en/troubleshooting.html#issue-empty-reports","title":"Issue: Empty Reports","text":"<p>Diagnostic: <pre><code># Check if earlier steps produced output\nls -lh results/quality_control/\nls -lh results/taxonomic_profiling/\n\n# Check logs\ntail logs/analysis.log\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-krona-charts-not-displaying","title":"Issue: Krona Charts Not Displaying","text":"<p>Solutions: <pre><code># Check if data exists\nhead results/taxonomic_profiling/*.report\n\n# Regenerate manually\nktImportTaxonomy \\\n  -o new_krona.html \\\n  results/taxonomic_profiling/*.report\n\n# Check browser console for JavaScript errors\n</code></pre></p>"},{"location":"en/troubleshooting.html#issue-missing-sample-in-results","title":"Issue: Missing Sample in Results","text":"<p>Checklist: <pre><code># 1. Sample in metadata?\ngrep \"Sample001\" metadata.tsv\n\n# 2. Input files exist?\nls data/raw_input/Sample001*.fastq.gz\n\n# 3. Sample passed QC?\ngrep \"Sample001\" results/quality_control/kneaddata/*.log\n\n# 4. Check for errors\ngrep -i \"Sample001\" logs/*.log | grep -i error\n</code></pre></p>"},{"location":"en/troubleshooting.html#error-code-reference","title":"Error Code Reference","text":"Exit Code Meaning Common Cause 1 General error Check logs for details 2 Misuse of command Wrong arguments 126 Command not executable Permission denied 127 Command not found PATH issue, not installed 128 + N Fatal signal N Process killed 130 Ctrl+C User interrupted 137 SIGKILL (9) Out of memory 139 Segmentation fault Invalid memory access 143 SIGTERM (15) Terminated by system"},{"location":"en/troubleshooting.html#oom-out-of-memory-detection","title":"OOM (Out of Memory) Detection","text":"<pre><code># Exit code 137 indicates OOM\ndmesg | grep -i \"killed process\"\n# Shows processes killed by OOM killer\n</code></pre>"},{"location":"en/troubleshooting.html#getting-help","title":"Getting Help","text":""},{"location":"en/troubleshooting.html#before-asking-for-help","title":"Before Asking for Help","text":"<ol> <li>Check documentation:</li> <li>User Manual</li> <li>Configuration Guide</li> <li> <p>This troubleshooting guide</p> </li> <li> <p>Gather information:    <pre><code># System info\nuname -a\ncat /etc/os-release\n\n# Environment\nconda list\npip list | grep micos\n\n# Recent logs\ntail -n 100 logs/analysis.log\n</code></pre></p> </li> <li> <p>Try minimal reproduction:    <pre><code># Run on test data\npython -m micos.cli full-run \\\n  --input-dir test_data \\\n  --results-dir test_results \\\n  --threads 4\n</code></pre></p> </li> </ol>"},{"location":"en/troubleshooting.html#reporting-issues","title":"Reporting Issues","text":"<p>When reporting issues, include:</p> <pre><code>**Environment**\n- OS: [e.g., Ubuntu 20.04]\n- Python: [e.g., 3.9.12]\n- MICOS version: [e.g., 1.0.0]\n- Installation method: [Docker/Conda/Source]\n\n**Command**\n```bash\n# The exact command you ran\n</code></pre> <p>Error message <pre><code>Full error message or relevant log excerpt\n</code></pre></p> <p>What you've tried - Step 1: ... - Step 2: ... ```</p>"},{"location":"en/troubleshooting.html#support-channels","title":"Support Channels","text":"Channel Best For Response Time GitHub Issues Bug reports, feature requests 1-3 days Discussions Questions, best practices 1-7 days Documentation Quick reference Immediate <p> \u2192 View Frequently Asked Questions </p>"},{"location":"zh/index.html","title":"MICOS-2024","text":"<p>\u4e13\u4e1a\u5b8f\u57fa\u56e0\u7ec4\u5206\u6790\u5e73\u53f0</p> <p>\u7aef\u5230\u7aef\u5206\u6790\u4ece\u539f\u59cb\u6d4b\u5e8f\u6570\u636e\u5230\u751f\u7269\u5b66\u6d1e\u5bdf</p>"},{"location":"zh/index.html#micos-2024_1","title":"MICOS-2024 \u662f\u4ec0\u4e48\uff1f","text":"<p>MICOS-2024 (Metagenomic Intelligence and Comprehensive Omics Suite) \u662f\u4e00\u4e2a\u7aef\u5230\u7aef\u5b8f\u57fa\u56e0\u7ec4\u5206\u6790\u5e73\u53f0\uff0c\u5c06\u4e1a\u754c\u6807\u51c6\u751f\u7269\u4fe1\u606f\u5b66\u5de5\u5177\u96c6\u6210\u5230\u7edf\u4e00\u3001\u53ef\u91cd\u73b0\u7684\u5de5\u4f5c\u6d41\u4e2d\u3002</p>"},{"location":"zh/index.html#_1","title":"\u6838\u5fc3\u80fd\u529b","text":"\u6a21\u5757 \u63cf\u8ff0 \u5de5\u5177  \u8d28\u91cf\u63a7\u5236 \u5bbf\u4e3b DNA \u53bb\u9664\u4e0e\u8d28\u91cf\u8fc7\u6ee4 KneadData, FastQC :material-account-tree: \u7269\u79cd\u5206\u7c7b \u5feb\u901f\u7269\u79cd\u5206\u7c7b Kraken2, Bracken  \u591a\u6837\u6027\u5206\u6790 Alpha/Beta \u591a\u6837\u6027\u6307\u6807 QIIME2  \u529f\u80fd\u6ce8\u91ca \u57fa\u56e0\u5bb6\u65cf\u548c\u901a\u8def\u5206\u6790 HUMAnN 3.x  \u5dee\u5f02\u5206\u6790 \u7269\u79cd/\u529f\u80fd\u7684\u7edf\u8ba1\u6bd4\u8f83 DESeq2, ALDEx2  \u7f51\u7edc\u5206\u6790 \u5fae\u751f\u7269\u5171\u73b0\u7f51\u7edc NetworkX, igraph"},{"location":"zh/index.html#_2","title":"\u4e3b\u8981\u7279\u6027","text":"<ul> <li> \u5bb9\u5668\u5316 - \u652f\u6301 Docker \u548c Singularity\uff0c\u786e\u4fdd\u53ef\u91cd\u73b0\u6027</li> <li> \u9ad8\u6027\u80fd - \u591a\u7ebf\u7a0b\u652f\u6301\uff0c\u9488\u5bf9\u5927\u6570\u636e\u96c6\u4f18\u5316</li> <li> \u4e30\u5bcc\u53ef\u89c6\u5316 - \u4ea4\u4e92\u5f0f HTML \u62a5\u544a\u3001Krona \u56fe\u8868</li> <li> \u6a21\u5757\u5316\u8bbe\u8ba1 - \u53ef\u8fd0\u884c\u5b8c\u6574\u6d41\u7a0b\u6216\u5355\u72ec\u6b65\u9aa4</li> <li> WDL \u5de5\u4f5c\u6d41 - \u517c\u5bb9 Cromwell\uff0c\u652f\u6301\u4e91\u7aef/HPC \u90e8\u7f72</li> </ul>"},{"location":"zh/index.html#_3","title":"\u5feb\u901f\u5f00\u59cb","text":"<pre><code># 1. \u514b\u9686\u4ed3\u5e93\ngit clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\n\n# 2. Docker \u5b89\u88c5\uff08\u63a8\u8350\uff09\ndocker compose -f deploy/docker-compose.example.yml up -d\n\n# 3. \u8fd0\u884c\u5206\u6790\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16\n</code></pre> <p> \u5b8c\u6574\u5b89\u88c5\u6307\u5357</p>"},{"location":"zh/index.html#_4","title":"\u6587\u6863\u5bfc\u822a","text":"\u6587\u6863 \u63cf\u8ff0 \u5b89\u88c5\u6307\u5357 \u5b8c\u6574\u5b89\u88c5\u8bf4\u660e \u914d\u7f6e\u6307\u5357 \u53c2\u6570\u914d\u7f6e\u8bf4\u660e \u7269\u79cd\u5206\u7c7b\u5206\u6790 \u7269\u79cd\u5206\u7c7b\u4e0e\u53ef\u89c6\u5316 \u529f\u80fd\u6ce8\u91ca\u5206\u6790 \u57fa\u56e0\u5bb6\u65cf\u548c\u901a\u8def\u5206\u6790 API \u53c2\u8003 \u5b8c\u6574 CLI \u547d\u4ee4\u53c2\u8003"},{"location":"zh/index.html#_5","title":"\u5feb\u901f\u94fe\u63a5","text":"<ul> <li> GitHub \u4ed3\u5e93</li> <li> \u95ee\u9898\u8ffd\u8e2a</li> <li> \u793e\u533a\u8ba8\u8bba</li> </ul> <p> English Docs | GitHub </p>"},{"location":"zh/api-reference.html","title":"API \u53c2\u8003","text":"<p>MICOS-2024 \u547d\u4ee4\u884c\u63a5\u53e3\u5b8c\u6574\u53c2\u8003\u3002</p>"},{"location":"zh/api-reference.html#_1","title":"\u76ee\u5f55","text":"<ul> <li>\u6982\u8ff0</li> <li>\u5168\u5c40\u9009\u9879</li> <li>\u547d\u4ee4</li> <li>full-run</li> <li>run</li> <li>validate-config</li> </ul>"},{"location":"zh/api-reference.html#_2","title":"\u6982\u8ff0","text":"<p>MICOS-2024 \u63d0\u4f9b\u7edf\u4e00\u7684\u547d\u4ee4\u884c\u63a5\u53e3 (CLI) \u7528\u4e8e\u5b8f\u57fa\u56e0\u7ec4\u5206\u6790\u3002\u6240\u6709\u547d\u4ee4\u9075\u5faa\u4ee5\u4e0b\u6a21\u5f0f\uff1a</p> <pre><code>python -m micos.cli [\u5168\u5c40\u9009\u9879] &lt;\u547d\u4ee4&gt; [\u547d\u4ee4\u9009\u9879]\n</code></pre>"},{"location":"zh/api-reference.html#_3","title":"\u83b7\u53d6\u5e2e\u52a9","text":"<pre><code># \u901a\u7528\u5e2e\u52a9\npython -m micos.cli --help\n\n# \u547d\u4ee4\u7279\u5b9a\u5e2e\u52a9\npython -m micos.cli full-run --help\npython -m micos.cli run quality-control --help\n</code></pre>"},{"location":"zh/api-reference.html#_4","title":"\u5168\u5c40\u9009\u9879","text":"\u9009\u9879 \u7b80\u5199 \u63cf\u8ff0 \u9ed8\u8ba4\u503c <code>--config</code> <code>-c</code> \u914d\u7f6e\u6587\u4ef6\u8def\u5f84 <code>config/analysis.yaml</code> <code>--verbose</code> <code>-v</code> \u542f\u7528\u8be6\u7ec6\u8f93\u51fa <code>false</code> <code>--log-file</code> <code>-l</code> \u65e5\u5fd7\u6587\u4ef6\u8def\u5f84 <code>logs/micos.log</code> <code>--threads</code> <code>-t</code> \u5e76\u884c\u7ebf\u7a0b\u6570 <code>16</code> <code>--dry-run</code> <code>-n</code> \u663e\u793a\u5c06\u6267\u884c\u7684\u64cd\u4f5c <code>false</code> <code>--version</code> <code>-V</code> \u663e\u793a\u7248\u672c\u4fe1\u606f -"},{"location":"zh/api-reference.html#_5","title":"\u793a\u4f8b","text":"<pre><code># \u4f7f\u7528\u81ea\u5b9a\u4e49\u914d\u7f6e\npython -m micos.cli --config my_config.yaml full-run --input-dir data/\n\n# \u8be6\u7ec6\u8f93\u51fa\u4e0e\u81ea\u5b9a\u4e49\u65e5\u5fd7\npython -m micos.cli --verbose --log-file analysis.log full-run ...\n\n# \u8bd5\u8fd0\u884c\uff08\u4ec5\u9884\u89c8\uff09\npython -m micos.cli --dry-run full-run --input-dir data/\n</code></pre>"},{"location":"zh/api-reference.html#_6","title":"\u547d\u4ee4","text":""},{"location":"zh/api-reference.html#full-run","title":"full-run","text":"<p>\u4ece\u539f\u59cb reads \u5230\u6700\u7ec8\u62a5\u544a\u6267\u884c\u5b8c\u6574\u5206\u6790\u6d41\u7a0b\u3002</p>"},{"location":"zh/api-reference.html#_7","title":"\u8bed\u6cd5","text":"<pre><code>python -m micos.cli full-run [\u9009\u9879]\n</code></pre>"},{"location":"zh/api-reference.html#_8","title":"\u5fc5\u9700\u53c2\u6570","text":"\u53c2\u6570 \u63cf\u8ff0 \u793a\u4f8b <code>--input-dir</code> \u539f\u59cb FASTQ \u6587\u4ef6\u76ee\u5f55 <code>--input-dir data/raw</code> <code>--results-dir</code> \u8f93\u51fa\u6587\u4ef6\u76ee\u5f55 <code>--results-dir results</code>"},{"location":"zh/api-reference.html#_9","title":"\u6570\u636e\u5e93\u53c2\u6570","text":"\u53c2\u6570 \u63cf\u8ff0 \u793a\u4f8b <code>--kneaddata-db</code> KneadData \u6570\u636e\u5e93\u8def\u5f84 <code>--kneaddata-db /db/human_genome</code> <code>--kraken2-db</code> Kraken2 \u6570\u636e\u5e93\u8def\u5f84 <code>--kraken2-db /db/kraken2_standard</code>"},{"location":"zh/api-reference.html#_10","title":"\u53ef\u9009\u53c2\u6570","text":"\u53c2\u6570 \u63cf\u8ff0 \u9ed8\u8ba4\u503c <code>--threads</code> \u6700\u5927\u5e76\u884c\u7ebf\u7a0b <code>16</code> <code>--samples</code> \u9017\u53f7\u5206\u9694\u6837\u672c\u5217\u8868 \u6240\u6709\u6837\u672c <code>--skip-qc</code> \u8df3\u8fc7\u8d28\u91cf\u63a7\u5236 <code>false</code> <code>--skip-taxonomy</code> \u8df3\u8fc7\u7269\u79cd\u5206\u7c7b <code>false</code> <code>--skip-functional</code> \u8df3\u8fc7\u529f\u80fd\u6ce8\u91ca <code>false</code> <code>--skip-diversity</code> \u8df3\u8fc7\u591a\u6837\u6027\u5206\u6790 <code>false</code>"},{"location":"zh/api-reference.html#_11","title":"\u793a\u4f8b","text":"<pre><code># \u57fa\u672c\u7528\u6cd5\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16 \\\n  --kneaddata-db /db/human_genome \\\n  --kraken2-db /db/kraken2_standard\n\n# \u4ec5\u5206\u6790\u7279\u5b9a\u6837\u672c\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --samples SampleA,SampleB,SampleC\n\n# \u8df3\u8fc7\u529f\u80fd\u5206\u6790\uff08\u4ec5\u5206\u7c7b\uff09\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --skip-functional\n</code></pre>"},{"location":"zh/api-reference.html#_12","title":"\u8f93\u51fa\u7ed3\u6784","text":"<pre><code>results/\n\u251c\u2500\u2500 quality_control/\n\u2502   \u251c\u2500\u2500 fastqc_reports/\n\u2502   \u2514\u2500\u2500 kneaddata/\n\u251c\u2500\u2500 taxonomic_profiling/\n\u2502   \u251c\u2500\u2500 *.kraken\n\u2502   \u251c\u2500\u2500 *.report\n\u2502   \u251c\u2500\u2500 *.krona.html\n\u2502   \u2514\u2500\u2500 feature-table.biom\n\u251c\u2500\u2500 functional_annotation/\n\u2502   \u251c\u2500\u2500 *_genefamilies.tsv\n\u2502   \u2514\u2500\u2500 *_pathabundance.tsv\n\u251c\u2500\u2500 diversity_analysis/\n\u2502   \u251c\u2500\u2500 alpha_diversity/\n\u2502   \u2514\u2500\u2500 beta_diversity/\n\u2514\u2500\u2500 report.html\n</code></pre>"},{"location":"zh/api-reference.html#run","title":"run","text":"<p>\u6267\u884c\u5355\u72ec\u7684\u5206\u6790\u6a21\u5757\u3002</p>"},{"location":"zh/api-reference.html#_13","title":"\u8bed\u6cd5","text":"<pre><code>python -m micos.cli run &lt;\u6a21\u5757&gt; [\u9009\u9879]\n</code></pre>"},{"location":"zh/api-reference.html#_14","title":"\u53ef\u7528\u6a21\u5757","text":"\u6a21\u5757 \u63cf\u8ff0 <code>quality-control</code> FastQC \u548c KneadData \u5904\u7406 <code>taxonomic-profiling</code> Kraken2 \u5206\u7c7b <code>diversity-analysis</code> QIIME2 \u591a\u6837\u6027\u6307\u6807 <code>functional-annotation</code> HUMAnN \u529f\u80fd\u6ce8\u91ca <code>summarize-results</code> \u751f\u6210 HTML \u62a5\u544a"},{"location":"zh/api-reference.html#quality-control","title":"quality-control","text":"<pre><code>python -m micos.cli run quality-control [\u9009\u9879]\n</code></pre> <p>\u53c2\u6570:</p> \u53c2\u6570 \u5fc5\u9700 \u63cf\u8ff0 <code>--input-dir</code> \u2713 \u539f\u59cb FASTQ \u76ee\u5f55 <code>--output-dir</code> \u2713 QC \u7ed3\u679c\u76ee\u5f55 <code>--kneaddata-db</code> \u2713 \u5bbf\u4e3b\u57fa\u56e0\u7ec4\u6570\u636e\u5e93 <code>--threads</code> \u5e76\u884c\u7ebf\u7a0b <p>\u793a\u4f8b: <pre><code>python -m micos.cli run quality-control \\\n  --input-dir data/raw_input \\\n  --output-dir results/quality_control \\\n  --kneaddata-db /db/human_genome \\\n  --threads 8\n</code></pre></p>"},{"location":"zh/api-reference.html#taxonomic-profiling","title":"taxonomic-profiling","text":"<pre><code>python -m micos.cli run taxonomic-profiling [\u9009\u9879]\n</code></pre> <p>\u53c2\u6570:</p> \u53c2\u6570 \u5fc5\u9700 \u63cf\u8ff0 <code>--input-dir</code> \u2713 \u6e05\u6d17\u540e FASTQ \u76ee\u5f55 (QC \u8f93\u51fa) <code>--output-dir</code> \u2713 \u5206\u7c7b\u7ed3\u679c\u76ee\u5f55 <code>--kraken2-db</code> \u2713 Kraken2 \u6570\u636e\u5e93\u8def\u5f84 <code>--confidence</code> \u5206\u7c7b\u7f6e\u4fe1\u5ea6\u9608\u503c <code>--threads</code> \u5e76\u884c\u7ebf\u7a0b <p>\u793a\u4f8b: <pre><code>python -m micos.cli run taxonomic-profiling \\\n  --input-dir results/quality_control/kneaddata \\\n  --output-dir results/taxonomic_profiling \\\n  --kraken2-db /db/kraken2_standard \\\n  --confidence 0.1 \\\n  --threads 16\n</code></pre></p>"},{"location":"zh/api-reference.html#diversity-analysis","title":"diversity-analysis","text":"<pre><code>python -m micos.cli run diversity-analysis [\u9009\u9879]\n</code></pre> <p>\u53c2\u6570:</p> \u53c2\u6570 \u5fc5\u9700 \u63cf\u8ff0 <code>--input-biom</code> \u2713 BIOM \u7279\u5f81\u8868\u8def\u5f84 <code>--output-dir</code> \u2713 \u591a\u6837\u6027\u7ed3\u679c\u76ee\u5f55 <code>--metadata</code> \u6837\u672c\u5143\u6570\u636e\u6587\u4ef6 <code>--sampling-depth</code> \u7a00\u91ca\u6df1\u5ea6 <p>\u793a\u4f8b: <pre><code>python -m micos.cli run diversity-analysis \\\n  --input-biom results/taxonomic_profiling/feature-table.biom \\\n  --output-dir results/diversity_analysis \\\n  --metadata metadata.tsv \\\n  --sampling-depth 10000\n</code></pre></p>"},{"location":"zh/api-reference.html#functional-annotation","title":"functional-annotation","text":"<pre><code>python -m micos.cli run functional-annotation [\u9009\u9879]\n</code></pre> <p>\u53c2\u6570:</p> \u53c2\u6570 \u5fc5\u9700 \u63cf\u8ff0 <code>--input-dir</code> \u2713 \u6e05\u6d17\u540e FASTQ \u76ee\u5f55 <code>--output-dir</code> \u2713 \u529f\u80fd\u7ed3\u679c\u76ee\u5f55 <code>--threads</code> \u5e76\u884c\u7ebf\u7a0b <code>--nucleotide-db</code> ChocoPhlAN \u6570\u636e\u5e93 <code>--protein-db</code> UniRef \u6570\u636e\u5e93 <p>\u793a\u4f8b: <pre><code>python -m micos.cli run functional-annotation \\\n  --input-dir results/quality_control/kneaddata \\\n  --output-dir results/functional_annotation \\\n  --threads 8\n</code></pre></p>"},{"location":"zh/api-reference.html#summarize-results","title":"summarize-results","text":"<pre><code>python -m micos.cli run summarize-results [\u9009\u9879]\n</code></pre> <p>\u53c2\u6570:</p> \u53c2\u6570 \u5fc5\u9700 \u63cf\u8ff0 <code>--results-dir</code> \u2713 \u4e3b\u7ed3\u679c\u76ee\u5f55 <code>--output-file</code> \u2713 \u8f93\u51fa HTML \u62a5\u544a\u8def\u5f84 <code>--format</code> \u8f93\u51fa\u683c\u5f0f (html, pdf) <p>\u793a\u4f8b: <pre><code>python -m micos.cli run summarize-results \\\n  --results-dir results \\\n  --output-file results/final_report.html\n</code></pre></p>"},{"location":"zh/api-reference.html#validate-config","title":"validate-config","text":"<p>\u8fd0\u884c\u5206\u6790\u524d\u9a8c\u8bc1\u914d\u7f6e\u6587\u4ef6\u3002</p>"},{"location":"zh/api-reference.html#_15","title":"\u8bed\u6cd5","text":"<pre><code>python -m micos.cli validate-config [\u9009\u9879]\n</code></pre> <p>\u53c2\u6570:</p> \u53c2\u6570 \u5fc5\u9700 \u63cf\u8ff0 <code>--config</code> \u914d\u7f6e\u6587\u4ef6\u8def\u5f84 <p>\u793a\u4f8b: <pre><code># \u9a8c\u8bc1\u9ed8\u8ba4\u914d\u7f6e\npython -m micos.cli validate-config\n\n# \u9a8c\u8bc1\u81ea\u5b9a\u4e49\u914d\u7f6e\npython -m micos.cli validate-config --config my_config.yaml\n</code></pre></p> <p>\u8f93\u51fa: <pre><code>\u2713 \u914d\u7f6e\u6587\u4ef6\u8bed\u6cd5\u6709\u6548\n\u2713 \u5fc5\u9700\u5b57\u6bb5\u5b58\u5728\n\u2713 \u6570\u636e\u5e93\u8def\u5f84\u5b58\u5728\n\u2713 \u53c2\u6570\u503c\u5728\u6709\u6548\u8303\u56f4\u5185\n\u26a0 \u8b66\u544a: \u672a\u6307\u5b9a\u7a00\u91ca\u6df1\u5ea6 (\u5c06\u81ea\u52a8\u68c0\u6d4b)\n\u914d\u7f6e\u9a8c\u8bc1\u5b8c\u6210\uff01\n</code></pre></p>"},{"location":"zh/api-reference.html#_16","title":"\u914d\u7f6e\u6587\u4ef6\u53c2\u8003","text":""},{"location":"zh/api-reference.html#_17","title":"\u4f4d\u7f6e","text":"<p>\u9ed8\u8ba4\u914d\u7f6e\u641c\u7d22\u987a\u5e8f\uff1a 1. <code>--config</code> \u6307\u5b9a\u7684\u8def\u5f84 2. <code>./config/analysis.yaml</code> 3. <code>~/.config/micos/analysis.yaml</code></p>"},{"location":"zh/api-reference.html#_18","title":"\u7ed3\u6784","text":"<pre><code># config/analysis.yaml\n\nproject:\n  name: \"My_Study\"\n  description: \"\u80a0\u9053\u6837\u672c\u5b8f\u57fa\u56e0\u7ec4\u5206\u6790\"\n\npaths:\n  input_dir: \"data/raw\"\n  output_dir: \"results\"\n\nresources:\n  max_threads: 16\n  max_memory: \"32GB\"\n\nquality_control:\n  kneaddata:\n    min_quality: 20\n    min_length: 50\n\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.1\n    threads: 16\n\ndiversity_analysis:\n  qiime2:\n    sampling_depth: 10000\n\nfunctional_annotation:\n  humann:\n    threads: 8\n</code></pre>"},{"location":"zh/api-reference.html#_19","title":"\u8fd4\u56de\u7801","text":"\u7801 \u542b\u4e49 0 \u6210\u529f 1 \u4e00\u822c\u9519\u8bef 2 \u65e0\u6548\u53c2\u6570 3 \u914d\u7f6e\u9519\u8bef 4 \u7f3a\u5c11\u4f9d\u8d56 5 \u6570\u636e\u5e93\u9519\u8bef 6 I/O \u9519\u8bef 130 \u7528\u6237\u4e2d\u65ad"},{"location":"zh/api-reference.html#_20","title":"\u73af\u5883\u53d8\u91cf","text":"\u53d8\u91cf \u63cf\u8ff0 \u793a\u4f8b <code>MICOS_CONFIG</code> \u9ed8\u8ba4\u914d\u7f6e\u6587\u4ef6\u8def\u5f84 <code>/path/to/config.yaml</code> <code>MICOS_THREADS</code> \u9ed8\u8ba4\u7ebf\u7a0b\u6570 <code>16</code> <code>MICOS_LOG_LEVEL</code> \u65e5\u5fd7\u7ea7\u522b <code>INFO</code>, <code>DEBUG</code> <code>KRAKEN2_DB_PATH</code> \u9ed8\u8ba4 Kraken2 \u6570\u636e\u5e93 <code>/db/kraken2</code>"},{"location":"zh/api-reference.html#_21","title":"\u6279\u91cf\u5904\u7406","text":""},{"location":"zh/api-reference.html#_22","title":"\u8fd0\u884c\u591a\u6837\u672c","text":"<pre><code># \u5904\u7406\u591a\u4e2a\u6570\u636e\u96c6\nfor dataset in dataset1 dataset2 dataset3; do\n  python -m micos.cli full-run \\\n    --input-dir \"data/${dataset}\" \\\n    --results-dir \"results/${dataset}\" \\\n    --config \"config/${dataset}.yaml\"\ndone\n</code></pre>"},{"location":"zh/api-reference.html#_23","title":"\u5e76\u884c\u6837\u672c\u5904\u7406","text":"<pre><code># \u4f7f\u7528 GNU parallel \u5e76\u884c\u5904\u7406\u6837\u672c\nls data/*/ | parallel -j 4 \\\n  'python -m micos.cli run taxonomic-profiling \\\n    --input-dir data/{} \\\n    --output-dir results/{}/taxonomy'\n</code></pre>"},{"location":"zh/api-reference.html#_24","title":"\u76f8\u5173\u6587\u6863","text":"<ul> <li>\u914d\u7f6e\u6307\u5357 - \u8be6\u7ec6\u914d\u7f6e\u9009\u9879</li> <li>\u7528\u6237\u624b\u518c - \u5206\u6b65\u4f7f\u7528\u6307\u5357</li> <li>\u6545\u969c\u6392\u9664 - \u5e38\u89c1\u95ee\u9898\u4e0e\u89e3\u51b3\u65b9\u6848</li> </ul>"},{"location":"zh/configuration.html","title":"\u914d\u7f6e\u6307\u5357","text":"<p>MICOS-2024 \u5206\u6790\u53c2\u6570\u7684\u5b8c\u6574\u53c2\u8003\u3002</p>"},{"location":"zh/configuration.html#_2","title":"\u76ee\u5f55","text":"<ul> <li>\u914d\u7f6e\u6982\u8ff0</li> <li>\u914d\u7f6e\u6587\u4ef6</li> <li>\u9879\u76ee\u914d\u7f6e</li> <li>\u8d44\u6e90\u914d\u7f6e</li> <li>\u6a21\u5757\u7279\u5b9a\u53c2\u6570</li> <li>\u914d\u7f6e\u9a8c\u8bc1</li> <li>\u6700\u4f73\u5b9e\u8df5</li> </ul>"},{"location":"zh/configuration.html#_3","title":"\u914d\u7f6e\u6982\u8ff0","text":"<p>MICOS-2024 \u4f7f\u7528\u57fa\u4e8e YAML \u683c\u5f0f\u7684**\u591a\u5c42\u914d\u7f6e\u7cfb\u7edf**\u3002\u8be5\u7cfb\u7edf\u652f\u6301\uff1a</p> <ul> <li>\u6a21\u5757\u5316\u914d\u7f6e\uff1a\u6bcf\u4e2a\u5206\u6790\u6a21\u5757\u6709\u72ec\u7acb\u8bbe\u7f6e</li> <li>\u53d8\u91cf\u66ff\u4ee3\uff1a\u4f7f\u7528 <code>${variable}</code> \u8bed\u6cd5\u5b9e\u73b0\u53ef\u91cd\u7528\u503c</li> <li>\u914d\u7f6e\u7ee7\u627f\uff1a\u9ed8\u8ba4\u503c \u2192 \u9879\u76ee \u2192 \u547d\u4ee4\u884c\u8986\u76d6</li> <li>\u81ea\u52a8\u9a8c\u8bc1\uff1a\u5206\u6790\u5f00\u59cb\u524d\u68c0\u67e5\u914d\u7f6e\u6709\u6548\u6027</li> </ul>"},{"location":"zh/configuration.html#_4","title":"\u914d\u7f6e\u5c42\u6b21","text":"<pre><code>1. \u9ed8\u8ba4\u503c\uff08\u4ee3\u7801\u5185\u7f6e\uff09\n   \u2193\n2. \u914d\u7f6e\u6587\u4ef6\uff08config/analysis.yaml\uff09\n   \u2193\n3. \u73af\u5883\u53d8\u91cf\uff08MICOS_* \u53d8\u91cf\uff09\n   \u2193\n4. \u547d\u4ee4\u884c\u53c2\u6570\uff08\u6700\u9ad8\u4f18\u5148\u7ea7\uff09\n</code></pre>"},{"location":"zh/configuration.html#_5","title":"\u914d\u7f6e\u6587\u4ef6","text":""},{"location":"zh/configuration.html#_6","title":"\u6587\u4ef6\u7ed3\u6784","text":"<pre><code>config/\n\u251c\u2500\u2500 analysis.yaml          # \u4e3b\u8981\u5206\u6790\u53c2\u6570\n\u251c\u2500\u2500 databases.yaml         # \u6570\u636e\u5e93\u8def\u5f84\n\u251c\u2500\u2500 samples.tsv           # \u6837\u672c\u5143\u6570\u636e\n\u2514\u2500\u2500 config.conf           # Cromwell \u5de5\u4f5c\u6d41\u8bbe\u7f6e\n</code></pre>"},{"location":"zh/configuration.html#_7","title":"\u5feb\u901f\u8bbe\u7f6e","text":"<pre><code># \u590d\u5236\u6a21\u677f\u6587\u4ef6\ncp config/analysis.yaml.template config/analysis.yaml\ncp config/databases.yaml.template config/databases.yaml\ncp config/samples.tsv.template config/samples.tsv\n\n# \u7f16\u8f91\u914d\u7f6e\nnano config/analysis.yaml\nnano config/databases.yaml\nnano config/samples.tsv\n</code></pre>"},{"location":"zh/configuration.html#_8","title":"\u9879\u76ee\u914d\u7f6e","text":""},{"location":"zh/configuration.html#_9","title":"\u57fa\u672c\u9879\u76ee\u4fe1\u606f","text":"<pre><code>project:\n  name: \"\u80a0\u9053\u5fae\u751f\u7269\u7ec4\u7814\u7a76_2024\"\n  description: \"\u6cbb\u7597\u4e0e\u5bf9\u7167\u7684\u4eba\u80a0\u9053\u5fae\u751f\u7269\u7ec4\u5206\u6790\"\n  version: \"1.0.0\"\n  author: \"\u7814\u7a76\u56e2\u961f\"\n  email: \"team@example.com\"\n</code></pre>"},{"location":"zh/configuration.html#_10","title":"\u8def\u5f84\u914d\u7f6e","text":"<pre><code>paths:\n  input_dir: \"data/raw_input\"           # \u539f\u59cb\u6570\u636e\u76ee\u5f55\n  output_dir: \"results\"                  # \u7ed3\u679c\u76ee\u5f55\n  temp_dir: \"/tmp/micos\"                 # \u4e34\u65f6\u6587\u4ef6\uff08\u4f7f\u7528\u5feb\u901f\u5b58\u50a8\uff09\n  log_dir: \"logs\"                        # \u65e5\u5fd7\u6587\u4ef6\u76ee\u5f55\n\n  # \u6570\u636e\u5e93\u8def\u5f84\uff08\u4e5f\u53ef\u4f7f\u7528 databases.yaml\uff09\n  databases:\n    kraken2: \"/data/databases/kraken2/standard\"\n    kneaddata: \"/data/databases/kneaddata/human_genome\"\n    humann: \"/data/databases/humann\"\n</code></pre>"},{"location":"zh/configuration.html#_11","title":"\u8d44\u6e90\u914d\u7f6e","text":""},{"location":"zh/configuration.html#_12","title":"\u8ba1\u7b97\u8d44\u6e90","text":"<pre><code>resources:\n  max_threads: 16              # \u6700\u5927\u5e76\u884c\u7ebf\u7a0b\u6570\n  max_memory: \"32GB\"           # \u6700\u5927\u5185\u5b58\u5206\u914d\n  max_time: \"24h\"              # \u6bcf\u4e2a\u4efb\u52a1\u7684\u6700\u5927\u8fd0\u884c\u65f6\u95f4\n\n  # \u6bcf\u4e2a\u6a21\u5757\u7684\u7ebf\u7a0b\u5206\u914d\n  thread_allocation:\n    quality_control: 8\n    taxonomic_profiling: 16\n    functional_annotation: 8\n    diversity_analysis: 4\n</code></pre>"},{"location":"zh/configuration.html#_13","title":"\u8d44\u6e90\u6307\u5357","text":"\u6570\u636e\u96c6\u89c4\u6a21 \u7ebf\u7a0b \u5185\u5b58 \u4e34\u65f6\u5b58\u50a8 \u5c0f\u578b\uff08&lt; 10 \u4e2a\u6837\u672c\uff09 8 16 GB 50 GB \u4e2d\u578b\uff0810-50 \u4e2a\u6837\u672c\uff09 16 32 GB 200 GB \u5927\u578b\uff0850-200 \u4e2a\u6837\u672c\uff09 32 64 GB 1 TB \u8d85\u5927\u578b\uff08&gt; 200 \u4e2a\u6837\u672c\uff09 64+ 128 GB 2 TB+"},{"location":"zh/configuration.html#_14","title":"\u5b58\u50a8\u4f18\u5316","text":"<pre><code>resources:\n  # \u5bf9\u4e34\u65f6\u6587\u4ef6\u4f7f\u7528 SSD\n  temp_dir: \"/ssd/tmp\"\n\n  # \u542f\u7528\u538b\u7f29\n  compression:\n    enabled: true\n    level: 6              # gzip \u538b\u7f29\u7ea7\u522b (1-9)\n\n  # \u6e05\u7406\u8bbe\u7f6e\n  cleanup:\n    remove_intermediate: true\n    keep_logs: true\n</code></pre>"},{"location":"zh/configuration.html#_15","title":"\u6a21\u5757\u7279\u5b9a\u53c2\u6570","text":""},{"location":"zh/configuration.html#_16","title":"\u8d28\u91cf\u63a7\u5236\u6a21\u5757","text":"<pre><code>quality_control:\n  enabled: true\n\n  fastqc:\n    enabled: true\n    threads: 4\n    memory: \"2GB\"\n\n  kneaddata:\n    enabled: true\n    threads: 8\n\n    # \u8d28\u91cf\u8fc7\u6ee4\n    min_quality: 20           # \u6700\u5c0f\u78b1\u57fa\u8d28\u91cf\u5206\u6570\n    min_length: 50            # \u4fee\u526a\u540e\u6700\u5c0f\u8bfb\u957f\n\n    # Trimmomatic \u9009\u9879\n    trimmomatic_options: \"SLIDINGWINDOW:4:20 MINLEN:50\"\n\n    # \u5bbf\u4e3b\u53bb\u9664\n    reference_db: \"${paths.databases.kneaddata}\"\n\n    # \u5176\u4ed6\u9009\u9879\n    remove_intermediate: true\n    bypass_trf: false         # \u8df3\u8fc7\u4e32\u8054\u91cd\u590d\u8fc7\u6ee4\n    threads: 8\n</code></pre>"},{"location":"zh/configuration.html#_17","title":"\u7269\u79cd\u5206\u7c7b\u6a21\u5757","text":"<pre><code>taxonomic_profiling:\n  enabled: true\n\n  kraken2:\n    enabled: true\n    threads: 16\n\n    # \u5206\u7c7b\u53c2\u6570\n    confidence: 0.1           # \u7f6e\u4fe1\u5ea6\u9608\u503c (0-1)\n                            # \u66f4\u4f4e = \u66f4\u591a\u5206\u7c7b\u8bfb\u6570\uff0c\u6f5c\u5728\u66f4\u591a\u5047\u9633\u6027\n                            # \u66f4\u9ad8 = \u66f4\u5c11\u5206\u7c7b\u8bfb\u6570\uff0c\u66f4\u9ad8\u7cbe\u5ea6\n    min_base_quality: 20      # \u5206\u7c7b\u7684\u6700\u5c0f\u78b1\u57fa\u8d28\u91cf\n    min_hit_groups: 2         # \u6700\u5c0f\u547d\u4e2d\u7ec4\u6570\n\n    # \u5185\u5b58\u9009\u9879\n    memory_mapping: true      # \u4f7f\u7528\u5185\u5b58\u6620\u5c04 I/O\uff08\u66f4\u5feb\uff0c\u66f4\u591a\u5185\u5b58\uff09\n\n    # \u8f93\u51fa\u9009\u9879\n    use_names: true           # \u8f93\u51fa\u4e2d\u5305\u542b\u5206\u7c7b\u540d\u79f0\n    report_zeros: false       # \u5305\u62ec\u8ba1\u6570\u4e3a\u96f6\u7684\u5206\u7c7b\u7fa4\n\n  kraken_biom:\n    enabled: true\n    format: \"hdf5\"            # hdf5 \u6216 json\n\n  krona:\n    enabled: true\n    max_depth: 7              # \u53ef\u89c6\u5316\u7684\u6700\u5927\u5206\u7c7b\u6df1\u5ea6\n</code></pre>"},{"location":"zh/configuration.html#kraken2","title":"Kraken2 \u7f6e\u4fe1\u5ea6\u53c2\u6570\u6307\u5357","text":"\u7f6e\u4fe1\u5ea6 \u654f\u611f\u6027 \u7cbe\u786e\u5ea6 \u4f7f\u7528\u573a\u666f 0.0 \u6781\u9ad8 \u8f83\u4f4e \u63a2\u7d22\u6027\u5206\u6790 0.1 \u9ad8 \u826f\u597d \u9ed8\u8ba4\uff0c\u5e73\u8861 0.3 \u4e2d\u7b49 \u9ad8 \u4fdd\u5b88\u5206\u6790 0.5 \u4f4e \u6781\u9ad8 \u4ec5\u9ad8\u7f6e\u4fe1\u5ea6"},{"location":"zh/configuration.html#_18","title":"\u591a\u6837\u6027\u5206\u6790\u6a21\u5757","text":"<pre><code>diversity_analysis:\n  enabled: true\n\n  qiime2:\n    enabled: true\n\n    # \u7279\u5f81\u8868\u8fc7\u6ee4\n    feature_filtering:\n      min_frequency: 10       # \u6bcf\u4e2a\u7279\u5f81\u7684\u6700\u5c0f\u8ba1\u6570\n      min_samples: 3          # \u7279\u5f81\u5fc5\u987b\u51fa\u73b0\u7684\u6700\u5c0f\u6837\u672c\u6570\n\n    # \u7a00\u758f\u5316\u6df1\u5ea6\uff08\u5982\u679c\u672a\u6307\u5b9a\u5219\u81ea\u52a8\u68c0\u6d4b\uff09\n    # sampling_depth: 10000\n\n    # Alpha \u591a\u6837\u6027\u6307\u6807\n    alpha_metrics:\n      - \"shannon\"            # Shannon \u591a\u6837\u6027\u6307\u6570\n      - \"chao1\"              # Chao1 \u4e30\u5bcc\u5ea6\u4f30\u8ba1\n      - \"simpson\"            # Simpson \u6307\u6570\n      - \"observed_features\"   # \u89c2\u6d4b\u5230\u7684 ASV/OTU \u6570\u91cf\n      - \"pielou_e\"           # Pielou \u5747\u5300\u5ea6\n\n    # Beta \u591a\u6837\u6027\u6307\u6807\n    beta_metrics:\n      - \"braycurtis\"         # Bray-Curtis \u5dee\u5f02\u6027\n      - \"jaccard\"            # Jaccard \u8ddd\u79bb\n      - \"unweighted_unifrac\" # \u975e\u52a0\u6743 UniFrac\n      - \"weighted_unifrac\"   # \u52a0\u6743 UniFrac\n</code></pre>"},{"location":"zh/configuration.html#_19","title":"\u529f\u80fd\u6ce8\u91ca\u6a21\u5757","text":"<pre><code>functional_annotation:\n  enabled: true\n\n  humann:\n    enabled: true\n    threads: 8\n\n    # \u6570\u636e\u5e93\u8def\u5f84\n    nucleotide_database: \"${paths.databases}/humann/chocophlan\"\n    protein_database: \"${paths.databases}/humann/uniref90\"\n\n    # \u641c\u7d22\u9009\u9879\n    search_mode: \"diamond\"    # diamond \u6216 bowtie2\n\n    # \u654f\u611f\u6027\u4e0e\u901f\u5ea6\u6743\u8861\n    diamond_options: \"--mid-sensitive\"\n\n    # \u901a\u8def\u9009\u9879\n    pathway_coverage: true\n    gap_fill: true            # \u586b\u5145\u901a\u8def\u7f3a\u53e3\n    minpath: true             # \u4f7f\u7528 MinPath \u8fdb\u884c\u901a\u8def\u9009\u62e9\n\n    # \u8f93\u51fa\u9009\u9879\n    remove_temp: true\n</code></pre>"},{"location":"zh/configuration.html#_20","title":"\u914d\u7f6e\u9a8c\u8bc1","text":""},{"location":"zh/configuration.html#_21","title":"\u81ea\u52a8\u9a8c\u8bc1","text":"<p>MICOS-2024 \u5728\u8fd0\u884c\u524d\u9a8c\u8bc1\u914d\u7f6e\uff1a</p> <pre><code># \u9a8c\u8bc1\u914d\u7f6e\npython -m micos.cli validate-config --config config/analysis.yaml\n\n# \u5e72\u8fd0\u884c\u6d4b\u8bd5\u914d\u7f6e\npython -m micos.cli full-run \\\n  --config config/analysis.yaml \\\n  --dry-run\n</code></pre>"},{"location":"zh/configuration.html#_22","title":"\u9a8c\u8bc1\u68c0\u67e5","text":"\u68c0\u67e5 \u63cf\u8ff0 \u5931\u8d25\u64cd\u4f5c YAML \u8bed\u6cd5 \u6709\u6548\u7684 YAML \u683c\u5f0f \u9519\u8bef + \u9000\u51fa \u5fc5\u9700\u5b57\u6bb5 \u6240\u6709\u5fc5\u586b\u5b57\u6bb5\u5b58\u5728 \u9519\u8bef + \u9000\u51fa \u8def\u5f84\u5b58\u5728 \u8f93\u5165/\u8f93\u51fa\u76ee\u5f55\u5b58\u5728 \u8b66\u544a/\u9519\u8bef \u53c2\u6570\u8303\u56f4 \u503c\u5728\u6709\u6548\u8303\u56f4\u5185 \u8b66\u544a \u6570\u636e\u5e93\u5b8c\u6574\u6027 \u6570\u636e\u5e93\u6587\u4ef6\u6709\u6548 \u9519\u8bef + \u9000\u51fa \u8d44\u6e90\u9650\u5236 \u5185\u5b58/\u7ebf\u7a0b\u5728\u7cfb\u7edf\u9650\u5236\u5185 \u8b66\u544a"},{"location":"zh/configuration.html#_23","title":"\u6700\u4f73\u5b9e\u8df5","text":""},{"location":"zh/configuration.html#1","title":"1. \u4ece\u6a21\u677f\u5f00\u59cb","text":"<pre><code># \u59cb\u7ec8\u4ece\u6a21\u677f\u5f00\u59cb\ncp config/*.template config/\n# \u7136\u540e\u81ea\u5b9a\u4e49\n</code></pre>"},{"location":"zh/configuration.html#2","title":"2. \u4f7f\u7528\u76f8\u5bf9\u8def\u5f84","text":"<pre><code># \u597d\u7684 - \u8de8\u7cfb\u7edf\u53ef\u79fb\u690d\npaths:\n  input_dir: \"data/raw\"\n  output_dir: \"results\"\n\n# \u53ef\u79fb\u690d\u6027\u8f83\u5dee\npaths:\n  input_dir: \"/home/user/specific/path/data\"\n</code></pre>"},{"location":"zh/configuration.html#3","title":"3. \u7248\u672c\u63a7\u5236\u914d\u7f6e","text":"<pre><code># \u8ddf\u8e2a\u914d\u7f6e\u6a21\u677f\ngit add config/*.template\n\n# \u4e0d\u8981\u8ddf\u8e2a\u5b9e\u9645\u914d\u7f6e\uff08\u53ef\u80fd\u5305\u542b\u7cfb\u7edf\u7279\u5b9a\u8def\u5f84\uff09\necho \"config/*.yaml\" &gt;&gt; .gitignore\n</code></pre>"},{"location":"zh/configuration.html#4","title":"4. \u8bb0\u5f55\u81ea\u5b9a\u4e49","text":"<pre><code>project:\n  name: \"Study_2024\"\n\nanalysis:\n  # \u7531\u4e8e\u9ad8\u8d28\u91cf\u6570\u636e\uff0c\u63d0\u9ad8\u7f6e\u4fe1\u5ea6\n  kraken2:\n    confidence: 0.15\n</code></pre>"},{"location":"zh/configuration.html#5","title":"5. \u7528\u5b50\u96c6\u6d4b\u8bd5","text":"<pre><code># test_config.yaml - \u4ec5\u5206\u6790\u524d 3 \u4e2a\u6837\u672c\nsamples:\n  subset: 3\n</code></pre>"},{"location":"zh/configuration.html#_24","title":"\u4e0b\u4e00\u6b65","text":"<ul> <li>\ud83d\udcd6 \u7528\u6237\u624b\u518c - \u5b66\u4e60\u8fd0\u884c\u5206\u6790</li> <li>\ud83e\uddec \u7269\u79cd\u5206\u7c7b - \u7269\u79cd\u5206\u7c7b\u8be6\u60c5</li> <li>\ud83e\uddea \u529f\u80fd\u6ce8\u91ca - \u529f\u80fd\u6ce8\u91ca\u8be6\u60c5</li> </ul>"},{"location":"zh/diversity-analysis.html","title":"\u591a\u6837\u6027\u5206\u6790","text":"<p>MICOS-2024 \u5fae\u751f\u7269\u7fa4\u843d\u591a\u6837\u6027\u5206\u6790\u5b8c\u6574\u6307\u5357\u3002</p>"},{"location":"zh/diversity-analysis.html#_2","title":"\u76ee\u5f55","text":"<ul> <li>\u6982\u8ff0</li> <li>\u591a\u6837\u6027\u7c7b\u578b</li> <li>\u8f93\u5165\u8981\u6c42</li> <li>\u8fd0\u884c\u5206\u6790</li> <li>Alpha \u591a\u6837\u6027</li> <li>Beta \u591a\u6837\u6027</li> <li>\u7edf\u8ba1\u68c0\u9a8c</li> <li>\u53ef\u89c6\u5316</li> <li>\u89e3\u8bfb\u6307\u5357</li> <li>\u9ad8\u7ea7\u4e3b\u9898</li> </ul>"},{"location":"zh/diversity-analysis.html#_3","title":"\u6982\u8ff0","text":"<p>\u591a\u6837\u6027\u5206\u6790\u6d4b\u91cf\u5fae\u751f\u7269\u7fa4\u843d\u7684**\u4e30\u5bcc\u5ea6**\uff08\u7c7b\u7fa4\u6570\u91cf\uff09\u548c**\u5747\u5300\u5ea6**\uff08\u4e30\u5ea6\u5206\u5e03\uff09\u3002\u8fd9\u4e9b\u6307\u6807\u63d0\u4f9b\u4ee5\u4e0b\u6d1e\u5bdf\uff1a</p> <ul> <li>\u7fa4\u843d\u5065\u5eb7: \u8f83\u9ad8\u591a\u6837\u6027\u901a\u5e38\u4e0e\u7a33\u5b9a\u6027\u76f8\u5173</li> <li>\u5904\u7406\u6548\u5e94: \u4e0d\u540c\u6761\u4ef6\u4e0b\u591a\u6837\u6027\u7684\u53d8\u5316</li> <li>\u751f\u6001\u6a21\u5f0f: \u7a7a\u95f4\u548c\u65f6\u95f4\u53d8\u5f02</li> <li>\u6bd4\u8f83\u7814\u7a76: \u751f\u6001\u7cfb\u7edf\u95f4\u5dee\u5f02</li> </ul>"},{"location":"zh/diversity-analysis.html#_4","title":"\u591a\u6837\u6027\u7c7b\u578b","text":""},{"location":"zh/diversity-analysis.html#alpha","title":"Alpha \u591a\u6837\u6027 (\u6837\u672c\u5185)","text":"<p>\u6d4b\u91cf\u5355\u4e2a\u6837\u672c\u5185\u7684\u591a\u6837\u6027\uff1a</p> \u6307\u6807 \u6d4b\u91cf\u5185\u5bb9 \u6700\u4f73\u7528\u9014 \u4e30\u5bcc\u5ea6 \u7c7b\u7fa4\u6570\u91cf \u7fa4\u843d\u590d\u6742\u6027 Shannon \u4e30\u5bcc\u5ea6 + \u5747\u5300\u5ea6 \u901a\u7528\u591a\u6837\u6027 Simpson \u4f18\u52bf\u5ea6 \u68c0\u6d4b\u4f18\u52bf\u7c7b\u7fa4 Faith's PD \u7cfb\u7edf\u53d1\u80b2\u591a\u6837\u6027 \u8fdb\u5316\u5e7f\u5ea6"},{"location":"zh/diversity-analysis.html#beta","title":"Beta \u591a\u6837\u6027 (\u6837\u672c\u95f4)","text":"<p>\u6d4b\u91cf\u6837\u672c\u95f4\u5dee\u5f02\uff1a</p> \u6307\u6807 \u52a0\u6743\u65b9\u5f0f \u6700\u4f73\u7528\u9014 Bray-Curtis \u4e30\u5ea6 \u7fa4\u843d\u7ec4\u6210 Jaccard \u5b58\u5728/\u7f3a\u5931 \u7269\u79cd\u91cd\u53e0 UniFrac \u7cfb\u7edf\u53d1\u80b2 \u8fdb\u5316\u5468\u8f6c Aitchison \u7ec4\u5206 \u96f6\u81a8\u80c0\u6570\u636e"},{"location":"zh/diversity-analysis.html#_5","title":"\u8f93\u5165\u8981\u6c42","text":""},{"location":"zh/diversity-analysis.html#_6","title":"\u6570\u636e\u683c\u5f0f","text":"\u683c\u5f0f \u63cf\u8ff0 \u6765\u6e90 BIOM \u5fae\u751f\u7269\u7ec4\u6570\u636e\u6807\u51c6\u683c\u5f0f Kraken-biom, QIIME2 TSV \u5236\u8868\u7b26\u5206\u9694\u7279\u5f81\u8868 \u81ea\u5b9a\u4e49\u8868\u683c QZA QIIME2 \u5236\u54c1 QIIME2 \u5bfc\u51fa"},{"location":"zh/diversity-analysis.html#_7","title":"\u5143\u6570\u636e\u8981\u6c42","text":"\u5217 \u63cf\u8ff0 \u6240\u9700\u5206\u6790 sample-id \u552f\u4e00\u6807\u8bc6\u7b26 \u6240\u6709\u5206\u6790 group \u5b9e\u9a8c\u5206\u7ec4 \u7ec4\u95f4\u6bd4\u8f83 subject-id \u53d7\u8bd5\u8005\u6807\u8bc6\u7b26 \u914d\u5bf9/\u7eb5\u5411 time-point \u91c7\u96c6\u65f6\u95f4 \u7eb5\u5411"},{"location":"zh/diversity-analysis.html#_8","title":"\u8fd0\u884c\u5206\u6790","text":""},{"location":"zh/diversity-analysis.html#1-micos-cli","title":"\u65b9\u5f0f 1: MICOS CLI","text":"<pre><code># \u4ece BIOM \u6587\u4ef6\u8fdb\u884c\u591a\u6837\u6027\u5206\u6790\npython -m micos.cli run diversity-analysis \\\n  --input-biom results/taxonomic_profiling/feature-table.biom \\\n  --output-dir results/diversity_analysis \\\n  --metadata metadata.tsv\n\n# \u4f5c\u4e3a\u5b8c\u6574\u6d41\u7a0b\u4e00\u90e8\u5206\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16\n</code></pre>"},{"location":"zh/diversity-analysis.html#2-qiime2","title":"\u65b9\u5f0f 2: \u76f4\u63a5 QIIME2","text":"<pre><code># \u5bfc\u5165 BIOM \u5230 QIIME2\nqiime tools import \\\n  --input-path feature-table.biom \\\n  --type 'FeatureTable[Frequency]' \\\n  --output-path table.qza\n\n# \u7a00\u91ca\u8868\u683c\nqiime feature-table rarefy \\\n  --i-table table.qza \\\n  --p-sampling-depth 10000 \\\n  --o-rarefied-table table-rarefied.qza\n</code></pre>"},{"location":"zh/diversity-analysis.html#alpha_1","title":"Alpha \u591a\u6837\u6027","text":""},{"location":"zh/diversity-analysis.html#_9","title":"\u6307\u6807\u6982\u8ff0","text":""},{"location":"zh/diversity-analysis.html#1","title":"1. \u4e30\u5bcc\u5ea6\u4f30\u8ba1\u5668","text":"\u6307\u6807 \u63cf\u8ff0 \u89e3\u8bfb \u89c2\u5bdf\u7279\u5f81\u6570 \u539f\u59cb\u7c7b\u7fa4\u8ba1\u6570 \u7b80\u5355\u4e30\u5bcc\u5ea6 Chao1 \u4f30\u8ba1\u603b\u4e30\u5bcc\u5ea6 \u8003\u8651\u672a\u89c2\u5bdf\u7c7b\u7fa4 ACE \u57fa\u4e8e\u4e30\u5ea6\u7684\u8986\u76d6 \u66ff\u4ee3\u4e30\u5bcc\u5ea6\u4f30\u8ba1"},{"location":"zh/diversity-analysis.html#2","title":"2. \u591a\u6837\u6027\u6307\u6570","text":"\u6307\u6807 \u516c\u5f0f \u8303\u56f4 \u8bf4\u660e Shannon -\u03a3(p\u1d62 \u00d7 ln(p\u1d62)) 0 \u5230 ~7 \u8003\u8651\u4e30\u5bcc\u5ea6\u548c\u5747\u5300\u5ea6 Simpson 1 - \u03a3(p\u1d62\u00b2) 0 \u5230 1 \u4e24\u4e2a\u968f\u673a reads \u4e0d\u540c\u7684\u6982\u7387 \u9006 Simpson 1 / \u03a3(p\u1d62\u00b2) 1 \u5230 N \u8d8a\u9ad8\u8d8a\u591a\u6837"},{"location":"zh/diversity-analysis.html#_10","title":"\u5b9e\u73b0","text":"<pre><code># \u8ba1\u7b97 alpha \u591a\u6837\u6027\nqiime diversity alpha \\\n  --i-table table.qza \\\n  --p-metric shannon \\\n  --o-alpha-diversity shannon.qza\n\n# \u591a\u6307\u6807\u4e00\u6b21\u8ba1\u7b97\nqiime diversity alpha-rarefaction \\\n  --i-table table.qza \\\n  --p-metrics shannon \\\n  --p-metrics chao1 \\\n  --p-metrics observed_features \\\n  --p-min-depth 1000 \\\n  --p-max-depth 50000 \\\n  --m-metadata-file metadata.tsv \\\n  --o-visualization alpha-rarefaction.qzv\n</code></pre>"},{"location":"zh/diversity-analysis.html#_11","title":"\u7edf\u8ba1\u68c0\u9a8c","text":"<pre><code># \u7ec4\u95f4\u6bd4\u8f83\nqiime diversity alpha-group-significance \\\n  --i-alpha-diversity shannon.qza \\\n  --m-metadata-file metadata.tsv \\\n  --m-metadata-column group \\\n  --o-visualization shannon-significance.qzv\n</code></pre> <p>\u5e38\u7528\u68c0\u9a8c: - Kruskal-Wallis: \u975e\u53c2\u6570\u7ec4\u95f4\u6bd4\u8f83 - \u6210\u5bf9 Wilcoxon: \u4e8b\u540e\u6bd4\u8f83 - \u7ebf\u6027\u6df7\u5408\u6548\u5e94: \u7eb5\u5411\u6570\u636e</p>"},{"location":"zh/diversity-analysis.html#beta_1","title":"Beta \u591a\u6837\u6027","text":""},{"location":"zh/diversity-analysis.html#_12","title":"\u8ddd\u79bb\u6307\u6807","text":""},{"location":"zh/diversity-analysis.html#1_1","title":"1. \u7ec4\u5206\u6307\u6807","text":"\u6307\u6807 \u7c7b\u578b \u516c\u5f0f\u7279\u5f81 Bray-Curtis \u57fa\u4e8e\u4e30\u5ea6 D = \u03a3|A\u1d62 - B\u1d62| / \u03a3(A\u1d62 + B\u1d62) Jaccard \u4e8c\u5143 D = 1 - (|A \u2229 B| / |A \u222a B|)"},{"location":"zh/diversity-analysis.html#2_1","title":"2. \u7cfb\u7edf\u53d1\u80b2\u6307\u6807","text":"\u6307\u6807 \u52a0\u6743\u65b9\u5f0f \u654f\u611f\u4e8e \u672a\u52a0\u6743 UniFrac \u5b58\u5728/\u7f3a\u5931 \u7cfb\u7edf\u53d1\u80b2\u65b0\u9896\u6027 \u52a0\u6743 UniFrac \u4e30\u5ea6 \u7cfb\u7edf\u53d1\u80b2\u5468\u8f6c"},{"location":"zh/diversity-analysis.html#_13","title":"\u5b9e\u73b0","text":"<pre><code># \u8ba1\u7b97 beta \u591a\u6837\u6027\nqiime diversity beta \\\n  --i-table table.qza \\\n  --p-metric braycurtis \\\n  --o-distance-matrix braycurtis.qza\n\n# \u7cfb\u7edf\u53d1\u80b2\u591a\u6837\u6027\uff08\u9700\u8981\u6811\uff09\nqiime diversity beta-phylogenetic \\\n  --i-table table.qza \\\n  --i-phylogeny tree.qza \\\n  --p-metric unweighted_unifrac \\\n  --o-distance-matrix unweighted-unifrac.qza\n</code></pre>"},{"location":"zh/diversity-analysis.html#_14","title":"\u964d\u7ef4","text":"<pre><code># PCoA\nqiime diversity pcoa \\\n  --i-distance-matrix braycurtis.qza \\\n  --o-pcoa braycurtis-pcoa.qza\n\n# Emperor \u53ef\u89c6\u5316\nqiime emperor plot \\\n  --i-pcoa braycurtis-pcoa.qza \\\n  --m-metadata-file metadata.tsv \\\n  --o-visualization braycurtis-emperor.qzv\n</code></pre>"},{"location":"zh/diversity-analysis.html#_15","title":"\u7edf\u8ba1\u68c0\u9a8c","text":""},{"location":"zh/diversity-analysis.html#permanova","title":"PERMANOVA","text":"<p>\u68c0\u9a8c\u7ec4\u95f4\u662f\u5426\u5728\u591a\u7ef4\u7a7a\u95f4\u5b58\u5728\u5dee\u5f02\uff1a</p> <pre><code>qiime diversity beta-group-significance \\\n  --i-distance-matrix braycurtis.qza \\\n  --m-metadata-file metadata.tsv \\\n  --m-metadata-column group \\\n  --p-method permanova \\\n  --o-visualization braycurtis-permanova.qzv\n</code></pre> <p>\u89e3\u8bfb: - p &lt; 0.05: \u7ec4\u95f4\u663e\u8457\u5dee\u5f02 - R\u00b2: \u5206\u7ec4\u89e3\u91ca\u7684\u65b9\u5dee\u6bd4\u4f8b</p>"},{"location":"zh/diversity-analysis.html#_16","title":"\u53ef\u89c6\u5316","text":""},{"location":"zh/diversity-analysis.html#alpha_2","title":"Alpha \u591a\u6837\u6027\u56fe","text":"<pre><code>import seaborn as sns\nimport matplotlib.pyplot as plt\n\n# \u7bb1\u7ebf\u56fe\ndata = pd.read_csv('alpha_diversity.tsv', sep='\\t')\nsns.boxplot(data=data, x='group', y='shannon')\nplt.title('\u5404\u7ec4 Shannon \u591a\u6837\u6027')\nplt.savefig('shannon_boxplot.pdf')\n</code></pre>"},{"location":"zh/diversity-analysis.html#beta_2","title":"Beta \u591a\u6837\u6027\u56fe","text":"<pre><code>from skbio.stats.ordination import pcoa\nfrom skbio import DistanceMatrix\nimport matplotlib.pyplot as plt\n\n# \u52a0\u8f7d\u8ddd\u79bb\u77e9\u9635\ndm = DistanceMatrix.read('braycurtis.tsv')\n\n# PCoA\npcoa_results = pcoa(dm)\n\n# \u7ed8\u56fe\nfig, ax = plt.subplots(figsize=(8, 6))\nfor group in metadata['group'].unique():\n    mask = metadata['group'] == group\n    ax.scatter(pcoa_results.samples.loc[mask, 'PC1'],\n               pcoa_results.samples.loc[mask, 'PC2'],\n               label=group)\nax.set_xlabel(f'PC1 ({pcoa_results.proportion_explained[0]:.1%})')\nax.set_ylabel(f'PC2 ({pcoa_results.proportion_explained[1]:.1%})')\nax.legend()\nplt.savefig('pcoa_plot.pdf')\n</code></pre>"},{"location":"zh/diversity-analysis.html#_17","title":"\u89e3\u8bfb\u6307\u5357","text":""},{"location":"zh/diversity-analysis.html#alpha_3","title":"Alpha \u591a\u6837\u6027","text":""},{"location":"zh/diversity-analysis.html#_18","title":"\u5178\u578b\u503c\uff08\u4eba\u7c7b\u80a0\u9053\uff09","text":"\u6307\u6807 \u8303\u56f4 \u8bf4\u660e \u89c2\u5bdf\u7279\u5f81\u6570 50-200 \u968f\u6d4b\u5e8f\u6df1\u5ea6\u53d8\u5316 Shannon 2.5-4.5 &gt;4 \u8868\u793a\u9ad8\u591a\u6837\u6027 Chao1 100-400 \u603b\u4e30\u5bcc\u5ea6\u4f30\u8ba1 Pielou's J 0.6-0.9 &gt;0.8 \u8868\u793a\u5747\u5300\u5206\u5e03"},{"location":"zh/diversity-analysis.html#_19","title":"\u751f\u6001\u89e3\u8bfb","text":"\u60c5\u666f \u89e3\u8bfb \u4f4e\u4e30\u5bcc\u5ea6\uff0c\u9ad8\u5747\u5300\u5ea6 \u5c11\u6570\u4f18\u52bf\u79cd\uff0c\u5e73\u8861\u826f\u597d \u9ad8\u4e30\u5bcc\u5ea6\uff0c\u4f4e\u5747\u5300\u5ea6 \u591a\u6570\u7a00\u6709\u7269\u79cd\uff0c\u5c11\u6570\u4f18\u52bf \u5904\u7406\u7ec4\u4f4e alpha \u6f5c\u5728\u83cc\u7fa4\u5931\u8c03\u6216\u5e94\u6fc0 \u5065\u5eb7\u7ec4\u9ad8 alpha \u591a\u6837\u3001\u6709\u97e7\u6027\u7684\u7fa4\u843d"},{"location":"zh/diversity-analysis.html#beta_3","title":"Beta \u591a\u6837\u6027","text":""},{"location":"zh/diversity-analysis.html#pcoa","title":"PCoA \u89e3\u8bfb","text":"\u6a21\u5f0f \u89e3\u8bfb \u6309\u7ec4\u7d27\u5bc6\u805a\u7c7b \u5f3a\u7ec4\u6548\u5e94 \u805a\u7c7b\u91cd\u53e0 \u76f8\u4f3c\u7fa4\u843d \u68af\u5ea6\u6a21\u5f0f \u8fde\u7eed\u73af\u5883\u9a71\u52a8\u56e0\u5b50 \u79bb\u7fa4\u70b9 \u72ec\u7279\u7fa4\u843d\u7ec4\u6210"},{"location":"zh/diversity-analysis.html#_20","title":"\u9ad8\u7ea7\u4e3b\u9898","text":""},{"location":"zh/diversity-analysis.html#_21","title":"\u7a00\u91ca\u4e0e\u6d4b\u5e8f\u6df1\u5ea6","text":"<pre><code># \u7a00\u91ca\u914d\u7f6e\ndiversity_analysis:\n  qiime2:\n    sampling_depth: \"auto\"    # \u81ea\u52a8\u68c0\u6d4b\n    # \u6216\u624b\u52a8\u6307\u5b9a\n    # sampling_depth: 10000\n</code></pre> <p>\u9009\u62e9\u6d4b\u5e8f\u6df1\u5ea6: 1. \u68c0\u67e5\u7a00\u91ca\u66f2\u7ebf 2. \u9009\u62e9\u66f2\u7ebf\u5e73\u53f0\u671f\u7684\u6df1\u5ea6 3. \u5c3d\u53ef\u80fd\u5305\u542b\u6700\u591a\u6837\u672c 4. \u6392\u9664\u4f4e\u4e8e\u6700\u5c0f\u6df1\u5ea6\u7684\u6837\u672c</p>"},{"location":"zh/diversity-analysis.html#_22","title":"\u7eb5\u5411\u5206\u6790","text":"<pre><code># \u7eb5\u5411\u6570\u636e\u6df7\u5408\u6548\u5e94\u6a21\u578b\nfrom statsmodels.regression.mixed_linear_model import MixedLM\n\n# \u6a21\u578b: alpha ~ time * treatment + (1|subject)\nmodel = MixedLM.from_formula(\n    'shannon ~ time_point * treatment',\n    groups='subject_id',\n    data=metadata\n)\nresult = model.fit()\nprint(result.summary())\n</code></pre>"},{"location":"zh/diversity-analysis.html#_23","title":"\u6838\u5fc3\u5fae\u751f\u7269\u7ec4\u5206\u6790","text":"<pre><code># \u8bc6\u522b\u6838\u5fc3\u7279\u5f81\n# \u5b9a\u4e49\u6838\u5fc3\uff08\u5728 &gt;50% \u6837\u672c\u4e2d\u5b58\u5728\uff0c&gt;0.1% \u4e30\u5ea6\uff09\ncore_features = table.view(pd.DataFrame)\ncore_features = core_features[\n    (core_features &gt; 0).sum(axis=1) / len(core_features.columns) &gt; 0.5\n]\ncore_features = core_features[core_features.sum(axis=1) &gt; 0.001]\n</code></pre>"},{"location":"zh/diversity-analysis.html#_24","title":"\u76f8\u5173\u6587\u6863","text":"<ul> <li>\u7269\u79cd\u5206\u7c7b - \u7269\u79cd\u5206\u7c7b</li> <li>\u529f\u80fd\u6ce8\u91ca - \u529f\u80fd\u5206\u6790</li> <li>\u914d\u7f6e\u6307\u5357 - \u53c2\u6570\u8bbe\u7f6e</li> <li>QIIME2 \u6587\u6863 - \u8be6\u7ec6 QIIME2 \u6307\u5357</li> </ul>"},{"location":"zh/faq.html","title":"\u5e38\u89c1\u95ee\u9898 (FAQ)","text":"<p>MICOS-2024 \u5e38\u89c1\u95ee\u9898\u7684\u5feb\u901f\u89e3\u7b54\u3002</p>"},{"location":"zh/faq.html#_1","title":"\u4e00\u822c\u95ee\u9898","text":""},{"location":"zh/faq.html#micos-2024","title":"MICOS-2024 \u662f\u4ec0\u4e48\uff1f","text":"<p>MICOS-2024\uff08Metagenomic Intelligence and Comprehensive Omics Suite\uff09\u662f\u4e00\u4e2a\u7aef\u5230\u7aef\u5b8f\u57fa\u56e0\u7ec4\u5206\u6790\u5e73\u53f0\u3002\u5b83\u5c06\u8d28\u91cf\u63a7\u5236\u3001\u7269\u79cd\u5206\u7c7b\u3001\u529f\u80fd\u6ce8\u91ca\u548c\u591a\u6837\u6027\u5206\u6790\u6574\u5408\u5230\u7edf\u4e00\u7684\u5de5\u4f5c\u6d41\u4e2d\u3002</p>"},{"location":"zh/faq.html#micos-2024_1","title":"\u8c01\u5e94\u8be5\u4f7f\u7528 MICOS-2024\uff1f","text":"<ul> <li>\u751f\u7269\u5b66\u5bb6\uff1a\u751f\u7269\u4fe1\u606f\u5b66\u7ecf\u9a8c\u6700\u5c11</li> <li>\u751f\u7269\u4fe1\u606f\u5b66\u5bb6\uff1a\u9700\u8981\u6807\u51c6\u5316\u3001\u53ef\u91cd\u73b0\u7684\u5de5\u4f5c\u6d41</li> <li>\u4e34\u5e8a\u7814\u7a76\u4eba\u5458\uff1a\u5206\u6790\u5fae\u751f\u7269\u7ec4\u6837\u672c</li> <li>\u751f\u6001\u5b66\u5bb6\uff1a\u7814\u7a76\u73af\u5883\u5fae\u751f\u7269\u7ec4</li> </ul>"},{"location":"zh/faq.html#micos-2024_2","title":"MICOS-2024 \u4e0e\u5176\u4ed6\u5de5\u5177\u76f8\u6bd4\u5982\u4f55\uff1f","text":"\u7279\u6027 MICOS-2024 Qiime2 MG-RAST mothur \u7aef\u5230\u7aef\u5de5\u4f5c\u6d41 \u2705 \u90e8\u5206 \u2705 \u90e8\u5206 WDL \u5de5\u4f5c\u6d41 \u2705 \u274c \u274c \u274c Docker \u652f\u6301 \u2705 \u2705 \u274c \u274c CLI \u754c\u9762 \u2705 \u2705 Web \u2705 \u6d41\u7a0b\u7075\u6d3b\u6027 \u9ad8 \u4e2d \u4f4e \u4e2d"},{"location":"zh/faq.html#_2","title":"\u5b89\u88c5\u95ee\u9898","text":""},{"location":"zh/faq.html#_3","title":"\u63a8\u8350\u7684\u5b89\u88c5\u65b9\u6cd5\u662f\u4ec0\u4e48\uff1f","text":"<p>Docker \u9002\u5408\uff1a - \u6700\u5927\u53ef\u91cd\u73b0\u6027 - \u670d\u52a1\u5668\u8f7b\u677e\u90e8\u7f72 - \u751f\u4ea7\u73af\u5883</p> <p>Conda \u9002\u5408\uff1a - \u5f00\u53d1\u5de5\u4f5c - \u81ea\u5b9a\u4e49\u4fee\u6539 - \u65e0 Docker \u7684\u7cfb\u7edf</p>"},{"location":"zh/faq.html#_4","title":"\u6211\u9700\u8981\u591a\u5c11\u78c1\u76d8\u7a7a\u95f4\uff1f","text":"\u7ec4\u4ef6 \u6700\u4f4e \u63a8\u8350 \u8f6f\u4ef6\u5b89\u88c5 5 GB 10 GB Kraken2 \u6570\u636e\u5e93 70 GB 150 GB (PlusPF) HUMAnN \u6570\u636e\u5e93 30 GB 50 GB \u5206\u6790\u8f93\u51fa 100 GB 500 GB \u603b\u8ba1 ~200 GB ~700 GB"},{"location":"zh/faq.html#_5","title":"\u6211\u53ef\u4ee5\u5728\u6ca1\u6709\u7ba1\u7406\u5458\u6743\u9650\u7684\u60c5\u51b5\u4e0b\u5b89\u88c5\u5417\uff1f","text":"<p>\u53ef\u4ee5\uff01\u4e24\u79cd\u5b89\u88c5\u65b9\u6cd5\u90fd\u65e0\u9700 sudo\uff1a - Docker\uff1a\u9700\u8981\u5c06\u7528\u6237\u6dfb\u52a0\u5230 <code>docker</code> \u7ec4 - Conda\uff1a\u5b8c\u5168\u5b89\u88c5\u5728\u7528\u6237\u76ee\u5f55\u4e2d</p>"},{"location":"zh/faq.html#gpu","title":"\u6211\u9700\u8981 GPU \u5417\uff1f","text":"<p>\u4e0d\u9700\u8981\u3002MICOS-2024 \u57fa\u4e8e CPU\u3002\u76ee\u524d\u4e0d\u652f\u6301 GPU \u52a0\u901f\u3002</p>"},{"location":"zh/faq.html#_6","title":"\u5206\u6790\u95ee\u9898","text":""},{"location":"zh/faq.html#_7","title":"\u5206\u6790\u9700\u8981\u591a\u957f\u65f6\u95f4\uff1f","text":"<p>\u6bcf\u6837\u672c\u7684\u8fd1\u4f3c\u65f6\u95f4\uff081000 \u4e07\u5bf9\u7aef reads\uff09\uff1a</p> \u6b65\u9aa4 \u65f6\u95f4 \u6ce8\u610f \u8d28\u91cf\u63a7\u5236 10-30 \u5206\u949f \u53d6\u51b3\u4e8e\u5bbf\u4e3b\u57fa\u56e0\u7ec4\u5927\u5c0f \u7269\u79cd\u5206\u7c7b 5-15 \u5206\u949f \u4f7f\u7528 Kraken2 \u6807\u51c6\u5e93 \u529f\u80fd\u6ce8\u91ca 1-4 \u5c0f\u65f6 \u53d6\u51b3\u4e8e\u6570\u636e\u5e93 \u591a\u6837\u6027\u5206\u6790 10-30 \u5206\u949f \u6bcf\u6b21\u8ba1\u7b97 \u603b\u8ba1 2-6 \u5c0f\u65f6 \u9ad8\u5ea6\u53ef\u5e76\u884c\u5316 <p>\u63d0\u901f\u6280\u5de7\uff1a - \u5bf9\u4e34\u65f6\u6587\u4ef6\u4f7f\u7528 SSD - \u589e\u52a0 <code>--threads</code> \u53c2\u6570 - \u6d4b\u8bd5\u4f7f\u7528 MiniKraken</p>"},{"location":"zh/faq.html#_8","title":"\u6211\u9700\u8981\u591a\u5c11\u6d4b\u5e8f\u6df1\u5ea6\uff1f","text":"\u7814\u7a76\u7c7b\u578b \u6700\u4f4e \u63a8\u8350 \u8bd5\u70b9/\u6d4b\u8bd5 1M reads/\u6837\u672c 2M reads/\u6837\u672c \u4e00\u822c\u5206\u6790 5M reads/\u6837\u672c 10M reads/\u6837\u672c \u7a00\u6709\u7269\u79cd\u68c0\u6d4b 20M reads/\u6837\u672c 50M reads/\u6837\u672c \u529f\u80fd\u5206\u6790 10M reads/\u6837\u672c 30M reads/\u6837\u672c"},{"location":"zh/faq.html#_9","title":"\u6211\u53ef\u4ee5\u5206\u6790\u5355\u7aef\u6570\u636e\u5417\uff1f","text":"<p>\u53ef\u4ee5\uff0cMICOS-2024 \u652f\u6301\u53cc\u7aef\u548c\u5355\u7aef\u6570\u636e\u3002\u4f46\u662f\uff1a - \u63a8\u8350\u53cc\u7aef\uff1a\u66f4\u597d\u7684\u7269\u79cd\u5206\u7c7b\u5206\u8fa8\u7387 - \u5355\u7aef\u8db3\u591f\uff1a\u529f\u80fd\u6ce8\u91ca - \u5728\u914d\u7f6e\u4e2d\u6307\u5b9a\u683c\u5f0f\u6216\u8ba9\u81ea\u52a8\u68c0\u6d4b\u5904\u7406</p>"},{"location":"zh/faq.html#_10","title":"\u7ed3\u679c\u95ee\u9898","text":""},{"location":"zh/faq.html#reads","title":"\u4e3a\u4ec0\u4e48\u5927\u591a\u6570\u6211\u7684 reads \u672a\u5206\u7c7b\uff1f","text":"<p>\u53ef\u80fd\u7684\u539f\u56e0\uff1a</p> \u539f\u56e0 \u68c0\u67e5 \u89e3\u51b3\u65b9\u6848 \u6570\u636e\u5e93\u592a\u5c0f \u4f7f\u7528\u6807\u51c6\u5e93\u800c\u975e MiniKraken \u4e0b\u8f7d\u66f4\u5927\u7684\u6570\u636e\u5e93 \u7f6e\u4fe1\u5ea6\u8fc7\u9ad8 \u68c0\u67e5\u914d\u7f6e \u964d\u4f4e\u5230 0.05-0.1 \u65b0\u751f\u7269 \u6587\u732e\u68c0\u7d22 \u6784\u5efa\u81ea\u5b9a\u4e49\u6570\u636e\u5e93 \u6570\u636e\u8d28\u91cf \u8fd0\u884c FastQC \u6539\u8fdb QC \u53c2\u6570 \u73af\u5883\u6837\u672c \u6837\u672c\u7c7b\u578b \u4f7f\u7528 PlusPF \u6570\u636e\u5e93"},{"location":"zh/faq.html#_11","title":"\u6211\u5e94\u8be5\u4f7f\u7528\u54ea\u4e2a\u591a\u6837\u6027\u6307\u6807\uff1f","text":"<p>Alpha \u591a\u6837\u6027\uff1a - Shannon\uff1a\u4e00\u822c\u591a\u6837\u6027\uff08\u4e30\u5bcc\u5ea6 + \u5747\u5300\u5ea6\uff09 - Chao1\uff1a\u4e30\u5bcc\u5ea6\u4f30\u8ba1 - Observed\uff1a\u7b80\u5355\u7269\u79cd\u8ba1\u6570</p> <p>Beta \u591a\u6837\u6027\uff1a - Bray-Curtis\uff1a\u4e30\u5ea6\u6570\u636e\u7684\u6807\u51c6 - UniFrac\uff1a\u5f53\u7cfb\u7edf\u53d1\u80b2\u91cd\u8981\u65f6 - Aitchison\uff1a\u542b\u96f6\u7684\u7ec4\u6210\u6570\u636e</p>"},{"location":"zh/faq.html#_12","title":"\u5982\u4f55\u89e3\u91ca\u7edf\u8ba1\u7ed3\u679c\uff1f","text":"\u68c0\u9a8c p &lt; 0.05 \u8868\u793a \u53ef\u89c6\u5316 PERMANOVA \u7ec4\u95f4\u663e\u8457\u5dee\u5f02 PCoA \u56fe Kruskal-Wallis Alpha \u591a\u6837\u6027\u4e0d\u540c \u7bb1\u7ebf\u56fe LEfSe \u7279\u5b9a\u5206\u7c7b\u7fa4\u4e0d\u540c \u67f1\u72b6\u56fe"},{"location":"zh/faq.html#_13","title":"\u66f4\u591a\u95ee\u9898\uff1f","text":"<ul> <li>\ud83d\udcd6 \u67e5\u770b \u7528\u6237\u624b\u518c</li> <li>\ud83d\udd27 \u67e5\u770b \u6545\u969c\u6392\u9664</li> <li>\ud83d\udcac \u53d1\u8d77 \u8ba8\u8bba</li> <li>\ud83d\udc1b \u62a5\u544a \u95ee\u9898</li> </ul>"},{"location":"zh/functional-profiling.html","title":"\u529f\u80fd\u6ce8\u91ca\u5206\u6790","text":"<p>MICOS-2024 \u529f\u80fd\u6ce8\u91ca\u4e0e\u901a\u8def\u5206\u6790\u5b8c\u6574\u6307\u5357\u3002</p>"},{"location":"zh/functional-profiling.html#_2","title":"\u76ee\u5f55","text":"<ul> <li>\u6982\u8ff0</li> <li>\u65b9\u6cd5\u8bba</li> <li>\u8f93\u5165\u8981\u6c42</li> <li>\u8fd0\u884c\u5206\u6790</li> <li>\u53c2\u6570\u914d\u7f6e</li> <li>\u8f93\u51fa\u6587\u4ef6</li> <li>\u7ed3\u679c\u89e3\u8bfb</li> <li>\u4e0b\u6e38\u5206\u6790</li> <li>\u9ad8\u7ea7\u4e3b\u9898</li> <li>\u6545\u969c\u6392\u9664</li> </ul>"},{"location":"zh/functional-profiling.html#_3","title":"\u6982\u8ff0","text":"<p>\u529f\u80fd\u6ce8\u91ca\u901a\u8fc7\u5b9a\u91cf\u57fa\u56e0\u5bb6\u65cf\u548c\u4ee3\u8c22\u901a\u8def\u6765\u8868\u5f81\u5fae\u751f\u7269\u7fa4\u843d\u7684\u4ee3\u8c22\u6f5c\u529b\u3002\u7269\u79cd\u5206\u7c7b\u56de\u7b54\"\u8c01\u5728\u90a3\u91cc\uff1f\"\uff0c\u800c\u529f\u80fd\u6ce8\u91ca\u56de\u7b54\"\u5b83\u4eec\u80fd\u505a\u4ec0\u4e48\uff1f\"</p>"},{"location":"zh/functional-profiling.html#_4","title":"\u6838\u5fc3\u7279\u6027","text":"<ul> <li>\u57fa\u56e0\u5bb6\u65cf\u5b9a\u91cf: UniRef90 \u86cb\u767d\u7c07</li> <li>\u901a\u8def\u5206\u6790: MetaCyc \u4ee3\u8c22\u901a\u8def</li> <li>\u7269\u79cd\u5206\u5c42: \u5c06\u529f\u80fd\u5f52\u5c5e\u5230\u7279\u5b9a\u5206\u7c7b\u7fa4</li> <li>\u591a\u6837\u672c\u6574\u5408: \u6bd4\u8f83\u6837\u672c\u95f4\u529f\u80fd\u8c31</li> </ul>"},{"location":"zh/functional-profiling.html#_5","title":"\u65b9\u6cd5\u8bba","text":""},{"location":"zh/functional-profiling.html#humann","title":"HUMAnN \u5206\u6790\u6d41\u7a0b","text":"<pre><code>\u8f93\u5165 Reads\n    \u2502\n    \u25bc\n[MetaPhlAn] \u2192 \u7269\u79cd\u8c31\n    \u2502\n    \u25bc\n[Mapping] \u2192 \u6309\u7269\u79cd\u5206\u5272 reads\n    \u2502\n    \u25bc\n[ChocoPhlAn] \u2192 \u6bd4\u5bf9\u5230\u6cdb\u57fa\u56e0\u7ec4 (\u6838\u9178)\n    \u2502\n    \u25bc\n[UniRef90] \u2192 \u672a\u6bd4\u5bf9\u5e8f\u5217\u6bd4\u5bf9\u5230\u86cb\u767d\u8d28\n    \u2502\n    \u25bc\n[\u901a\u8def\u91cd\u6784] \u2192 MinPath + gap filling\n    \u2502\n    \u25bc\n\u57fa\u56e0\u5bb6\u65cf + \u901a\u8def\u4e30\u5ea6 + \u8986\u76d6\u5ea6\n</code></pre>"},{"location":"zh/functional-profiling.html#_6","title":"\u529f\u80fd\u672c\u4f53\u8bba","text":"\u5c42\u7ea7 \u6570\u636e\u5e93 \u63cf\u8ff0 \u57fa\u56e0\u5bb6\u65cf UniRef90 \u86cb\u767d\u5e8f\u5217\u7ec4 (&gt;90% \u76f8\u540c) \u901a\u8def MetaCyc \u7cbe\u9009\u4ee3\u8c22\u901a\u8def \u6a21\u5757 KEGG \u4ee3\u8c22\u529f\u80fd\u5355\u5143"},{"location":"zh/functional-profiling.html#_7","title":"\u8f93\u5165\u8981\u6c42","text":""},{"location":"zh/functional-profiling.html#_8","title":"\u8f93\u5165\u6570\u636e","text":"\u6765\u6e90 \u683c\u5f0f \u63cf\u8ff0 KneadData \u8f93\u51fa FASTQ \u8d28\u63a7\u540e\u3001\u53bb\u9664\u5bbf\u4e3b\u7684 reads \u4efb\u4f55\u6e05\u6d17\u540e reads FASTQ/FASTA \u53bb\u63a5\u5934\u3001\u8d28\u91cf\u8fc7\u6ee4"},{"location":"zh/functional-profiling.html#_9","title":"\u6570\u636e\u5e93\u8981\u6c42","text":"\u6570\u636e\u5e93 \u5927\u5c0f \u63cf\u8ff0 ChocoPhlAn ~10 GB \u6838\u9178\u6cdb\u57fa\u56e0\u7ec4\u6570\u636e\u5e93 UniRef90 ~20 GB \u86cb\u767d\u5bb6\u65cf (&gt;90% \u4e00\u81f4\u6027) MetaCyc \u5185\u7f6e \u4ee3\u8c22\u901a\u8def\u5b9a\u4e49"},{"location":"zh/functional-profiling.html#_10","title":"\u8fd0\u884c\u5206\u6790","text":""},{"location":"zh/functional-profiling.html#1-micos-cli","title":"\u65b9\u5f0f 1: MICOS CLI","text":"<pre><code># \u4ec5\u529f\u80fd\u6ce8\u91ca\npython -m micos.cli run functional-annotation \\\n  --input-dir results/quality_control/kneaddata \\\n  --output-dir results/functional_annotation \\\n  --threads 16\n\n# \u4f5c\u4e3a\u5b8c\u6574\u6d41\u7a0b\u4e00\u90e8\u5206\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16\n</code></pre>"},{"location":"zh/functional-profiling.html#2-humann","title":"\u65b9\u5f0f 2: \u76f4\u63a5 HUMAnN","text":"<pre><code># \u57fa\u672c\u8fd0\u884c\nhumann --input sample.fastq \\\n  --output output_dir/ \\\n  --nucleotide-database /db/chocophlan \\\n  --protein-database /db/uniref90 \\\n  --threads 16\n</code></pre>"},{"location":"zh/functional-profiling.html#_11","title":"\u53c2\u6570\u914d\u7f6e","text":""},{"location":"zh/functional-profiling.html#humann_1","title":"HUMAnN \u914d\u7f6e","text":"<pre><code>functional_annotation:\n  enabled: true\n\n  humann:\n    enabled: true\n    threads: 16\n\n    # \u6570\u636e\u5e93\u8def\u5f84\n    nucleotide_database: \"${paths.databases}/humann/chocophlan\"\n    protein_database: \"${paths.databases}/humann/uniref90\"\n\n    # \u641c\u7d22\u9009\u9879\n    search_mode: \"diamond\"    # diamond \u6216 usearch\n\n    # \u7075\u654f\u5ea6\u4e0e\u901f\u5ea6\u6743\u8861\n    diamond_options: \"--mid-sensitive\"\n\n    # \u901a\u8def\u9009\u9879\n    pathway_coverage: true\n    gap_fill: true            # \u586b\u8865\u901a\u8def\u7f3a\u53e3\n    minpath: true             # \u4f7f\u7528 MinPath \u9009\u62e9\u901a\u8def\n</code></pre>"},{"location":"zh/functional-profiling.html#_12","title":"\u8f93\u51fa\u6587\u4ef6","text":""},{"location":"zh/functional-profiling.html#_13","title":"\u76ee\u5f55\u7ed3\u6784","text":"<pre><code>results/functional_annotation/\n\u251c\u2500\u2500 sample_genefamilies.tsv         # \u57fa\u56e0\u5bb6\u65cf\u4e30\u5ea6\n\u251c\u2500\u2500 sample_genefamilies-cpm.tsv     # CPM \u6807\u51c6\u5316\n\u251c\u2500\u2500 sample_pathabundance.tsv        # \u901a\u8def\u4e30\u5ea6\n\u251c\u2500\u2500 sample_pathcoverage.tsv         # \u901a\u8def\u8986\u76d6\u5ea6\n\u2514\u2500\u2500 sample.log                      # \u8fd0\u884c\u65e5\u5fd7\n</code></pre>"},{"location":"zh/functional-profiling.html#_14","title":"\u57fa\u56e0\u5bb6\u65cf\u6587\u4ef6","text":"\u5217 \u63cf\u8ff0 \u793a\u4f8b # Gene Family UniRef90 \u7c07 UniRef90_A0A0A0MQD6 Sample1 \u4e30\u5ea6 (RPK) 45.23"},{"location":"zh/functional-profiling.html#_15","title":"\u901a\u8def\u4e30\u5ea6\u6587\u4ef6","text":"<p>\u5206\u5c42\u683c\u5f0f: <code>PATHWAY|Species</code> \u663e\u793a\u7269\u79cd\u8d21\u732e</p> <p>\u793a\u4f8b: <pre><code>GLYCOLYSIS|g__Bacteroides.s__Bacteroides_thetaiotaomicron    45.2\nGLYCOLYSIS|g__Faecalibacterium.s__Faecalibacterium_prausnitzii    32.1\nGLYCOLYSIS|unclassified    12.5\n</code></pre></p>"},{"location":"zh/functional-profiling.html#_16","title":"\u7ed3\u679c\u89e3\u8bfb","text":""},{"location":"zh/functional-profiling.html#_17","title":"\u8d28\u91cf\u6307\u6807","text":""},{"location":"zh/functional-profiling.html#_18","title":"\u6bd4\u5bf9\u7387","text":"\u6bd4\u5bf9\u7387 \u89e3\u8bfb \u64cd\u4f5c &lt; 20% \u5dee \u68c0\u67e5\u6570\u636e\u8d28\u91cf\u548c\u6570\u636e\u5e93 20-50% \u4e2d\u7b49 \u65b0\u9896\u7fa4\u843d\u53ef\u63a5\u53d7 50-70% \u826f\u597d \u6807\u51c6\u6027\u80fd &gt; 70% \u4f18\u79c0 \u9ad8\u8d28\u91cf\u53c2\u8003\u57fa\u56e0\u7ec4"},{"location":"zh/functional-profiling.html#_19","title":"\u529f\u80fd\u4e30\u5bcc\u5ea6","text":"<p>\u4eba\u7c7b\u80a0\u9053\u5178\u578b\u8303\u56f4: - \u57fa\u56e0\u5bb6\u65cf: 100,000-500,000 - \u901a\u8def: 200-400</p>"},{"location":"zh/functional-profiling.html#_20","title":"\u4e0b\u6e38\u5206\u6790","text":""},{"location":"zh/functional-profiling.html#_21","title":"\u6807\u51c6\u5316","text":"<pre><code># CPM (\u6bcf\u767e\u4e07\u62f7\u8d1d) \u6807\u51c6\u5316\nhumann_renorm_table \\\n  -i sample_genefamilies.tsv \\\n  -o sample_genefamilies-cpm.tsv \\\n  --units cpm\n</code></pre>"},{"location":"zh/functional-profiling.html#_22","title":"\u8f6c\u6362\u5230\u5176\u4ed6\u672c\u4f53\u8bba","text":"<pre><code># \u5230 KEGG \u6b63\u4ea4\u7fa4 (KO)\nhumann_regroup_table \\\n  -i sample_genefamilies.tsv \\\n  -g uniref90_ko \\\n  -o sample_ko.tsv\n\n# \u5230 GO terms\nhumann_regroup_table \\\n  -i sample_genefamilies.tsv \\\n  -g uniref90_go \\\n  -o sample_go.tsv\n</code></pre>"},{"location":"zh/functional-profiling.html#_23","title":"\u591a\u6837\u672c\u5206\u6790","text":"<pre><code># \u5408\u5e76\u591a\u6837\u672c\nhumann_join_tables \\\n  -i results/functional_annotation/ \\\n  -o merged_genefamilies.tsv \\\n  --file_name genefamilies\n</code></pre>"},{"location":"zh/functional-profiling.html#_24","title":"\u9ad8\u7ea7\u4e3b\u9898","text":""},{"location":"zh/functional-profiling.html#_25","title":"\u81ea\u5b9a\u4e49\u57fa\u56e0\u5bb6\u65cf","text":"<pre><code># \u521b\u5efa\u81ea\u5b9a\u4e49\u6570\u636e\u5e93\nhumann_databases --download chocophlan full /custom/path\n\n# \u6dfb\u52a0\u81ea\u5b9a\u4e49\u5e8f\u5217\ncat custom_genes.fa &gt;&gt; /custom/path/chocophlan/*.ffn\n</code></pre>"},{"location":"zh/functional-profiling.html#_26","title":"\u5b8f\u8f6c\u5f55\u7ec4\u6574\u5408","text":"<pre><code># \u4f7f\u7528 HUMAnN \u5904\u7406\u8f6c\u5f55\u7ec4\u6570\u636e\nhumann --input sample_rna.fastq \\\n  --output rnaseq_output/ \\\n  --bypass-prescreen  # \u4e0d\u8df3\u8fc7\u86cb\u767d\u641c\u7d22\n</code></pre>"},{"location":"zh/functional-profiling.html#_27","title":"\u6545\u969c\u6392\u9664","text":""},{"location":"zh/functional-profiling.html#_28","title":"\u95ee\u9898: \u8fd0\u884c\u592a\u6162","text":"<p>\u89e3\u51b3\u65b9\u6848: <pre><code>functional_annotation:\n  humann:\n    diamond_options: \"--fast\"\n    threads: 32\n    # \u6216\u4f7f\u7528 UniRef50 \u4ee3\u66ff UniRef90\n    protein_database: \"/db/uniref50\"\n</code></pre></p>"},{"location":"zh/functional-profiling.html#_29","title":"\u95ee\u9898: \u5185\u5b58\u9519\u8bef","text":"<p>\u89e3\u51b3\u65b9\u6848: <pre><code># \u51cf\u5c11\u7ebf\u7a0b\nhumann --threads 8 ...\n\n# \u4f7f\u7528\u5185\u5b58\u9ad8\u6548\u6a21\u5f0f\nhumann --memory-use minimum ...\n\n# \u987a\u5e8f\u5904\u7406\u6837\u672c\u800c\u975e\u5e76\u884c\n</code></pre></p>"},{"location":"zh/functional-profiling.html#reads","title":"\u95ee\u9898: \u5927\u90e8\u5206 reads \u672a\u6bd4\u5bf9","text":"<p>\u8bca\u65ad\u6b65\u9aa4: <pre><code># 1. \u68c0\u67e5\u8f93\u5165\u8d28\u91cf\nfastqc sample.fastq\n\n# 2. \u9a8c\u8bc1\u6570\u636e\u5e93\u5b89\u88c5\nls -lh /db/humann/chocophlan/\nls -lh /db/humann/uniref90/\n\n# 3. \u68c0\u67e5 MetaPhlAn \u8f93\u51fa\u4e2d\u7684\u7269\u79cd\u8986\u76d6\u5ea6\n# \u5982\u679c\u672a\u77e5\u7269\u79cd\u5360\u4e3b\u5bfc\uff0c\u9700\u8981\u66f4\u5e7f\u6cdb\u7684\u6570\u636e\u5e93\n</code></pre></p>"},{"location":"zh/functional-profiling.html#_30","title":"\u76f8\u5173\u6587\u6863","text":"<ul> <li>\u7269\u79cd\u5206\u7c7b - \u7269\u79cd\u5206\u7c7b</li> <li>\u591a\u6837\u6027\u5206\u6790 - \u7fa4\u843d\u7ed3\u6784</li> <li>\u914d\u7f6e\u6307\u5357 - \u53c2\u6570\u8be6\u60c5</li> <li>HUMAnN \u6587\u6863 - \u5b98\u65b9 HUMAnN \u6587\u6863</li> </ul>"},{"location":"zh/installation.html","title":"\u5b89\u88c5\u6307\u5357","text":"<p>MICOS-2024 \u7684\u5b8c\u6574\u5b89\u88c5\u8bf4\u660e\u3002</p>"},{"location":"zh/installation.html#_2","title":"\u76ee\u5f55","text":"<ul> <li>\u7cfb\u7edf\u8981\u6c42</li> <li>\u5b89\u88c5\u65b9\u6cd5</li> <li>\u6570\u636e\u5e93\u8bbe\u7f6e</li> <li>\u9a8c\u8bc1</li> <li>\u79bb\u7ebf\u5b89\u88c5</li> <li>\u6545\u969c\u6392\u9664</li> </ul>"},{"location":"zh/installation.html#_3","title":"\u7cfb\u7edf\u8981\u6c42","text":""},{"location":"zh/installation.html#_4","title":"\u6700\u4f4e\u8981\u6c42","text":"\u7ec4\u4ef6 \u6700\u4f4e\u914d\u7f6e \u63a8\u8350\u914d\u7f6e \u64cd\u4f5c\u7cfb\u7edf Linux (Ubuntu 18.04+) / macOS 11+ Linux (Ubuntu 20.04+) CPU 4 \u6838 16+ \u6838 \u5185\u5b58 (RAM) 16 GB 32+ GB \u5b58\u50a8 100 GB HDD 500+ GB SSD \u7f51\u7edc \u5b89\u88c5\u7684\u4e92\u8054\u7f51\u8fde\u63a5 \u6570\u636e\u5e93\u4e0b\u8f7d\u7684\u4e92\u8054\u7f51\u8fde\u63a5"},{"location":"zh/installation.html#_5","title":"\u8f6f\u4ef6\u524d\u63d0\u6761\u4ef6","text":"\u8f6f\u4ef6 \u7248\u672c \u7528\u4e8e Python 3.9+ \u6838\u5fc3\u5e73\u53f0 Docker 20.10+ \u5bb9\u5668\u5316\u90e8\u7f72 Conda/Mamba 4.10+ \u5305\u7ba1\u7406"},{"location":"zh/installation.html#_6","title":"\u6570\u636e\u5e93\u5b58\u50a8\u8981\u6c42","text":"\u6570\u636e\u5e93 \u5927\u5c0f \u7528\u9014 Kraken2 \u6807\u51c6\u5e93 ~70 GB \u7269\u79cd\u5206\u7c7b Kraken2 MiniKraken ~8 GB \u5feb\u901f\u6d4b\u8bd5 KneadData \u4eba\u7c7b\u57fa\u56e0\u7ec4 ~4 GB \u5bbf\u4e3b DNA \u53bb\u9664 HUMAnN ChocoPhlAn ~10 GB \u529f\u80fd\u6ce8\u91ca HUMAnN UniRef90 ~20 GB \u86cb\u767d\u8d28\u5bb6\u65cf"},{"location":"zh/installation.html#_7","title":"\u5b89\u88c5\u65b9\u6cd5","text":""},{"location":"zh/installation.html#1docker","title":"\u65b9\u5f0f 1\uff1aDocker \u5b89\u88c5\uff08\u63a8\u8350\uff09","text":"<p>Docker \u63d0\u4f9b\u6700\u53ef\u91cd\u73b0\u7684\u73af\u5883\uff0c\u6240\u6709\u4f9d\u8d56\u9879\u5747\u5df2\u9884\u5b89\u88c5\u3002</p>"},{"location":"zh/installation.html#1-docker","title":"\u6b65\u9aa4 1\uff1a\u5b89\u88c5 Docker","text":"<pre><code># Linux (Ubuntu/Debian)\ncurl -fsSL https://get.docker.com -o get-docker.sh\nsudo sh get-docker.sh\nsudo usermod -aG docker $USER\nnewgrp docker\n\n# \u9a8c\u8bc1\u5b89\u88c5\ndocker --version\ndocker compose version\n</code></pre>"},{"location":"zh/installation.html#2","title":"\u6b65\u9aa4 2\uff1a\u514b\u9686\u4ed3\u5e93","text":"<pre><code>git clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\n</code></pre>"},{"location":"zh/installation.html#3-docker-compose","title":"\u6b65\u9aa4 3\uff1a\u4f7f\u7528 Docker Compose \u90e8\u7f72","text":"<pre><code># \u542f\u52a8\u6240\u6709\u670d\u52a1\ndocker compose -f deploy/docker-compose.example.yml up -d\n\n# \u9a8c\u8bc1\u670d\u52a1\u8fd0\u884c\ndocker compose -f deploy/docker-compose.example.yml ps\n\n# \u67e5\u770b\u65e5\u5fd7\ndocker compose -f deploy/docker-compose.example.yml logs -f\n</code></pre>"},{"location":"zh/installation.html#4","title":"\u6b65\u9aa4 4\uff1a\u8fdb\u5165\u5bb9\u5668","text":"<pre><code># \u8fdb\u5165\u4e3b\u5206\u6790\u5bb9\u5668\ndocker compose -f deploy/docker-compose.example.yml exec micos bash\n\n# \u8fd0\u884c\u5206\u6790\npython -m micos.cli --help\n</code></pre> <p>\u4f18\u70b9\uff1a - \u2705 \u5b8c\u6574\u7684\u73af\u5883\u9694\u79bb - \u2705 \u65e0\u4f9d\u8d56\u51b2\u7a81 - \u2705 \u8de8\u7cfb\u7edf\u6613\u4e8e\u91cd\u73b0</p>"},{"location":"zh/installation.html#2conda","title":"\u65b9\u5f0f 2\uff1aConda \u5b89\u88c5","text":"<p>Conda/Mamba \u63d0\u4f9b\u7075\u6d3b\u7684\u5b89\u88c5\uff0c\u6027\u80fd\u826f\u597d\u3002</p>"},{"location":"zh/installation.html#1-miniforge","title":"\u6b65\u9aa4 1\uff1a\u5b89\u88c5 Miniforge\uff08\u63a8\u8350\uff09","text":"<pre><code># \u4e0b\u8f7d Miniforge \u5b89\u88c5\u7a0b\u5e8f\nwget https://github.com/conda-forge/miniforge/releases/latest/download/Miniforge3-Linux-x86_64.sh\n\n# \u8fd0\u884c\u5b89\u88c5\u7a0b\u5e8f\nbash Miniforge3-Linux-x86_64.sh -b -p $HOME/miniforge\n\n# \u521d\u59cb\u5316 shell\n$HOME/miniforge/bin/conda init bash\nsource ~/.bashrc\n</code></pre>"},{"location":"zh/installation.html#2_1","title":"\u6b65\u9aa4 2\uff1a\u521b\u5efa\u73af\u5883","text":"<pre><code># \u514b\u9686\u4ed3\u5e93\ngit clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\n\n# \u4f7f\u7528 mamba \u521b\u5efa\u73af\u5883\uff08\u66f4\u5feb\uff09\nmamba env create -f environment.yml\n\n# \u6fc0\u6d3b\u73af\u5883\nconda activate micos-2024\n</code></pre>"},{"location":"zh/installation.html#3-micos","title":"\u6b65\u9aa4 3\uff1a\u5b89\u88c5 MICOS \u5305","text":"<pre><code># \u4ee5\u53ef\u7f16\u8f91\u6a21\u5f0f\u5b89\u88c5\uff08\u5f00\u53d1\u7528\uff09\npip install -e .\n\n# \u6216\u6b63\u5e38\u5b89\u88c5\npip install .\n</code></pre>"},{"location":"zh/installation.html#4_1","title":"\u6b65\u9aa4 4\uff1a\u9a8c\u8bc1\u5de5\u5177","text":"<pre><code># \u68c0\u67e5\u6838\u5fc3\u4f9d\u8d56\nkraken2 --version\nhumann --version\nqiime --version\nkneaddata --version\n</code></pre> <p>\u4f18\u70b9\uff1a - \u2705 \u539f\u751f\u6027\u80fd - \u2705 \u6613\u4e8e\u5b9a\u5236 - \u2705 \u9002\u5408\u5f00\u53d1</p>"},{"location":"zh/installation.html#_8","title":"\u6570\u636e\u5e93\u8bbe\u7f6e","text":""},{"location":"zh/installation.html#_9","title":"\u81ea\u52a8\u5316\u6570\u636e\u5e93\u4e0b\u8f7d","text":"<pre><code># \u8fd0\u884c\u6570\u636e\u5e93\u4e0b\u8f7d\u811a\u672c\npython scripts/download_databases.py \\\n  --output-dir /path/to/databases \\\n  --databases kraken2,kneaddata,humann\n</code></pre>"},{"location":"zh/installation.html#_10","title":"\u624b\u52a8\u6570\u636e\u5e93\u8bbe\u7f6e","text":""},{"location":"zh/installation.html#kraken2","title":"Kraken2 \u6570\u636e\u5e93","text":"<pre><code># \u521b\u5efa\u6570\u636e\u5e93\u76ee\u5f55\nmkdir -p /path/to/kraken2_db\n\n# \u4e0b\u8f7d\u5e76\u6784\u5efa\u6807\u51c6\u6570\u636e\u5e93\uff08\u9700\u8981 ~70GB\uff09\nkraken2-build --download-taxonomy --db /path/to/kraken2_db\nkraken2-build --download-library bacteria --db /path/to/kraken2_db\nkraken2-build --download-library archaea --db /path/to/kraken2_db\nkraken2-build --build --db /path/to/kraken2_db --threads 16\n\n# \u6216\u4e0b\u8f7d\u9884\u6784\u5efa\u7684 MiniKraken\uff08\u5feb\u901f\u5f00\u59cb\uff0c~8GB\uff09\nwget https://genome-idx.s3.amazonaws.com/kraken/minikraken2_v2_8GB_201904_UPDATE.tgz\ntar -xzf minikraken2_v2_8GB_201904_UPDATE.tgz\n</code></pre>"},{"location":"zh/installation.html#kneaddata","title":"KneadData \u6570\u636e\u5e93","text":"<pre><code># \u4e0b\u8f7d\u4eba\u7c7b\u57fa\u56e0\u7ec4\u53c2\u8003\nkneaddata_database --download human_genome bowtie2 /path/to/kneaddata_db\n</code></pre>"},{"location":"zh/installation.html#humann","title":"HUMAnN \u6570\u636e\u5e93","text":"<pre><code># \u4e0b\u8f7d\u529f\u80fd\u6570\u636e\u5e93\nhumann_databases --download chocophlan full /path/to/humann_db\nhumann_databases --download uniref uniref90_diamond /path/to/humann_db\n</code></pre>"},{"location":"zh/installation.html#_11","title":"\u6570\u636e\u5e93\u914d\u7f6e","text":"<p>\u521b\u5efa <code>config/databases.yaml</code>\uff1a</p> <pre><code>database_root: \"/path/to/databases\"\n\nquality_control:\n  kneaddata:\n    human_genome: \"${database_root}/kneaddata/human_genome\"\n\ntaxonomy:\n  kraken2:\n    standard: \"${database_root}/kraken2/standard\"\n    minikraken: \"${database_root}/kraken2/minikraken\"\n\nfunctional:\n  humann:\n    chocophlan: \"${database_root}/humann/chocophlan\"\n    uniref90: \"${database_root}/humann/uniref90\"\n</code></pre>"},{"location":"zh/installation.html#_12","title":"\u9a8c\u8bc1","text":""},{"location":"zh/installation.html#1","title":"\u6b65\u9aa4 1\uff1a\u5b89\u88c5\u9a8c\u8bc1","text":"<pre><code># \u8fd0\u884c\u9a8c\u8bc1\u811a\u672c\n./scripts/verify_installation.sh\n</code></pre> <p>\u9884\u671f\u8f93\u51fa\uff1a <pre><code>\u2713 Python 3.9+ \u5df2\u627e\u5230\n\u2713 Kraken2 \u5df2\u5b89\u88c5\n\u2713 HUMAnN \u5df2\u5b89\u88c5\n\u2713 QIIME2 \u5df2\u5b89\u88c5\n\u2713 Kneaddata \u5df2\u5b89\u88c5\n\u2713 \u6240\u6709\u4f9d\u8d56\u5df2\u6ee1\u8db3\n</code></pre></p>"},{"location":"zh/installation.html#2_2","title":"\u6b65\u9aa4 2\uff1a\u6d4b\u8bd5\u8fd0\u884c","text":"<pre><code># \u4e0b\u8f7d\u6d4b\u8bd5\u6570\u636e\npython scripts/download_test_data.py --output-dir test_data\n\n# \u8fd0\u884c\u5feb\u901f\u6d4b\u8bd5\npython -m micos.cli full-run \\\n  --input-dir test_data \\\n  --results-dir test_results \\\n  --threads 4 \\\n  --kneaddata-db /path/to/kneaddata_db \\\n  --kraken2-db /path/to/kraken2_minikraken\n</code></pre>"},{"location":"zh/installation.html#3","title":"\u6b65\u9aa4 3\uff1a\u68c0\u67e5\u8f93\u51fa","text":"<pre><code># \u9a8c\u8bc1\u8f93\u51fa\u662f\u5426\u5b58\u5728\nls test_results/\n# \u5e94\u663e\u793a\uff1aquality_control/, taxonomic_profiling/, functional_annotation/, report.html\n</code></pre>"},{"location":"zh/installation.html#_13","title":"\u79bb\u7ebf\u5b89\u88c5","text":"<p>\u5bf9\u4e8e\u65e0\u4e92\u8054\u7f51\u8bbf\u95ee\u7684\u7cfb\u7edf\uff1a</p>"},{"location":"zh/installation.html#1_1","title":"\u6b65\u9aa4 1\uff1a\u5728\u8054\u7f51\u7cfb\u7edf\u51c6\u5907","text":"<pre><code># \u4e0b\u8f7d\u5305\npip download \\\n  -r requirements.txt \\\n  -d ./offline_packages \\\n  --platform manylinux2014_x86_64\n\n# \u5bfc\u51fa conda \u73af\u5883\nconda env export --no-builds &gt; environment-offline.yml\n\n# \u4e0b\u8f7d\u6570\u636e\u5e93\uff08\u89c1\u6570\u636e\u5e93\u8bbe\u7f6e\u90e8\u5206\uff09\n</code></pre>"},{"location":"zh/installation.html#2_3","title":"\u6b65\u9aa4 2\uff1a\u4f20\u8f93\u5230\u79bb\u7ebf\u7cfb\u7edf","text":"<p>\u5c06\u8fd9\u4e9b\u76ee\u5f55\u4f20\u8f93\u5230\u79bb\u7ebf\u7cfb\u7edf\uff1a - <code>offline_packages/</code> - <code>MICOS-2024/</code>\uff08\u6e90\u4ee3\u7801\uff09 - \u6570\u636e\u5e93\u6587\u4ef6</p>"},{"location":"zh/installation.html#3_1","title":"\u6b65\u9aa4 3\uff1a\u79bb\u7ebf\u5b89\u88c5","text":"<pre><code># \u4ece\u672c\u5730\u5305\u5b89\u88c5\npip install --no-index --find-links=./offline_packages -r requirements.txt\n\n# \u5b89\u88c5 MICOS\npip install -e MICOS-2024/\n</code></pre>"},{"location":"zh/installation.html#_14","title":"\u6545\u969c\u6392\u9664","text":""},{"location":"zh/installation.html#docker","title":"\u95ee\u9898\uff1aDocker \u6743\u9650\u88ab\u62d2\u7edd","text":"<pre><code># \u5c06\u7528\u6237\u6dfb\u52a0\u5230 docker \u7ec4\nsudo usermod -aG docker $USER\nnewgrp docker\n\n# \u9a8c\u8bc1\ndocker run hello-world\n</code></pre>"},{"location":"zh/installation.html#conda","title":"\u95ee\u9898\uff1aConda \u73af\u5883\u521b\u5efa\u5931\u8d25","text":"<pre><code># \u6e05\u9664 conda \u7f13\u5b58\nconda clean --all\n\n# \u66f4\u65b0 conda\nconda update -n base conda\n\n# \u5c1d\u8bd5\u4f7f\u7528 mamba\nconda install mamba -c conda-forge -n base\nmamba env create -f environment.yml --force\n</code></pre>"},{"location":"zh/installation.html#_15","title":"\u95ee\u9898\uff1a\u6570\u636e\u5e93\u4e0b\u8f7d\u5931\u8d25","text":"<pre><code># \u4f7f\u7528\u955c\u50cf\u7ad9\u70b9\n# \u5bf9\u4e8e\u4e2d\u56fd\u7528\u6237\uff1a\nexport KRAKEN2_DB_MIRROR=\"https://mirrors.tuna.tsinghua.edu.cn/\"\n\n# \u6216\u4ece\u4ee5\u4e0b\u5730\u5740\u624b\u52a8\u4e0b\u8f7d\uff1a\n# https://benlangmead.github.io/aws-indexes/k2\n</code></pre>"},{"location":"zh/installation.html#_16","title":"\u95ee\u9898\uff1a\u6570\u636e\u5e93\u6784\u5efa\u65f6\u5185\u5b58\u9519\u8bef","text":"<pre><code># \u6784\u5efa\u671f\u95f4\u51cf\u5c11\u7ebf\u7a0b\u6570\nkraken2-build --build --db /path/to/db --threads 4\n\n# \u6216\u4f7f\u7528\u9884\u6784\u5efa\u6570\u636e\u5e93\nwget https://genome-idx.s3.amazonaws.com/kraken/k2_standard_20231009.tar.gz\n</code></pre>"},{"location":"zh/installation.html#_17","title":"\u4e0b\u4e00\u6b65","text":"<ul> <li>\ud83d\udcd6 \u7528\u6237\u624b\u518c - \u5b66\u4e60\u5982\u4f55\u4f7f\u7528 MICOS-2024</li> <li>\u2699\ufe0f \u914d\u7f6e\u6307\u5357 - \u81ea\u5b9a\u4e49\u60a8\u7684\u5206\u6790</li> <li>\ud83e\uddea \u6d4b\u8bd5\u6570\u636e - \u8fd0\u884c\u793a\u4f8b\u5206\u6790</li> </ul>"},{"location":"zh/installation.html#_18","title":"\u83b7\u53d6\u5e2e\u52a9","text":"<ul> <li>\ud83d\udccb FAQ</li> <li>\ud83d\udd27 \u6545\u969c\u6392\u9664</li> <li>\ud83d\udcac GitHub \u8ba8\u8bba</li> <li>\ud83d\udc1b \u62a5\u544a\u95ee\u9898</li> </ul>"},{"location":"zh/taxonomic-profiling.html","title":"\u7269\u79cd\u5206\u7c7b\u5206\u6790","text":"<p>MICOS-2024 \u7269\u79cd\u5206\u7c7b\u4e0e\u591a\u6837\u6027\u5206\u6790\u5b8c\u6574\u6307\u5357\u3002</p>"},{"location":"zh/taxonomic-profiling.html#_2","title":"\u76ee\u5f55","text":"<ul> <li>\u6982\u8ff0</li> <li>\u65b9\u6cd5\u8bba</li> <li>\u5de5\u4f5c\u6d41\u7a0b</li> <li>\u8f93\u5165\u8981\u6c42</li> <li>\u8fd0\u884c\u5206\u6790</li> <li>\u53c2\u6570\u914d\u7f6e</li> <li>\u8f93\u51fa\u6587\u4ef6</li> <li>\u7ed3\u679c\u89e3\u8bfb</li> <li>\u9ad8\u7ea7\u4e3b\u9898</li> <li>\u6545\u969c\u6392\u9664</li> </ul>"},{"location":"zh/taxonomic-profiling.html#_3","title":"\u6982\u8ff0","text":"<p>\u7269\u79cd\u5206\u7c7b\u6a21\u5757\u8bc6\u522b\u5e76\u5b9a\u91cf\u5206\u6790\u5b8f\u57fa\u56e0\u7ec4\u6837\u672c\u4e2d\u7684\u5fae\u751f\u7269\u79cd\u7c7b\u3002\u5b83\u5c06\u8d28\u91cf\u63a7\u5236\u3001\u5e8f\u5217\u5206\u7c7b\u548c\u591a\u6837\u6027\u5206\u6790\u6574\u5408\u4e3a\u4e00\u4e2a\u5b8c\u6574\u7684\u5206\u6790\u6d41\u7a0b\u3002</p>"},{"location":"zh/taxonomic-profiling.html#_4","title":"\u6838\u5fc3\u7279\u6027","text":"<ul> <li>\u9ad8\u901f\u5206\u7c7b: Kraken2 \u5904\u7406\u901f\u5ea6\u7ea6 1000 \u4e07 reads/\u5206\u949f</li> <li>\u7cbe\u786e\u4e30\u5ea6\u4f30\u8ba1: Bracken \u6539\u5584\u79cd\u6c34\u5e73\u5b9a\u91cf</li> <li>\u4ea4\u4e92\u5f0f\u53ef\u89c6\u5316: Krona \u56fe\u8868\u63a2\u7d22\u5206\u7c7b\u7ec4\u6210</li> <li>\u591a\u6837\u6027\u6307\u6807: \u901a\u8fc7 QIIME2 \u8ba1\u7b97 Alpha \u548c Beta \u591a\u6837\u6027</li> <li>\u7edf\u8ba1\u5206\u6790: \u5dee\u5f02\u4e30\u5ea6\u68c0\u9a8c</li> </ul>"},{"location":"zh/taxonomic-profiling.html#_5","title":"\u65b9\u6cd5\u8bba","text":""},{"location":"zh/taxonomic-profiling.html#kraken2","title":"\u5206\u7c7b\u7b97\u6cd5 (Kraken2)","text":"<p>Kraken2 \u4f7f\u7528 k-mer \u8fdb\u884c\u5206\u7c7b\uff1a</p> <ol> <li>\u6570\u636e\u5e93\u6784\u5efa: \u53c2\u8003\u57fa\u56e0\u7ec4\u88ab\u5206\u89e3\u4e3a k-mers\uff08\u9ed8\u8ba4 k=35\uff09</li> <li>\u6700\u5c0f\u5316\u7d22\u5f15: \u4ec5\u5b58\u50a8\u6700\u5c0f\u5316\u5b50\u4ee5\u51cf\u5c11\u5185\u5b58\u4f7f\u7528</li> <li>\u5206\u7c7b: \u4f7f\u7528 LCA\uff08\u6700\u8fd1\u516c\u5171\u7956\u5148\uff09 \u7b97\u6cd5\u5c06\u8f93\u5165 reads \u4e0e\u6570\u636e\u5e93\u5339\u914d</li> <li>\u7f6e\u4fe1\u5ea6\u8bc4\u5206: \u57fa\u4e8e k-mer \u8986\u76d6\u5ea6\u8ba1\u7b97\u5206\u7c7b\u7f6e\u4fe1\u5ea6</li> </ol>"},{"location":"zh/taxonomic-profiling.html#bracken","title":"\u4e30\u5ea6\u6821\u6b63 (Bracken)","text":"<p>Bracken \u6821\u6b63\u4ee5\u4e0b\u504f\u5dee\uff1a - \u57fa\u56e0\u7ec4\u5927\u5c0f\u504f\u5dee: \u8f83\u5927\u57fa\u56e0\u7ec4\u8d21\u732e\u66f4\u591a reads - \u6570\u636e\u5e93\u8986\u76d6\u5ea6: \u4e0d\u5b8c\u6574\u7684\u53c2\u8003\u6570\u636e\u5e93 - \u83cc\u682a\u53d8\u5f02: \u540c\u4e00\u7269\u79cd\u7684\u591a\u4e2a\u83cc\u682a</p>"},{"location":"zh/taxonomic-profiling.html#_6","title":"\u5206\u7c7b\u5c42\u7ea7","text":"\u5c42\u7ea7 \u4ee3\u7801 \u793a\u4f8b \u57df D Bacteria \u95e8 P Proteobacteria \u7eb2 C Gammaproteobacteria \u76ee O Enterobacterales \u79d1 F Enterobacteriaceae \u5c5e G Escherichia \u79cd S Escherichia coli"},{"location":"zh/taxonomic-profiling.html#_7","title":"\u5de5\u4f5c\u6d41\u7a0b","text":"<pre><code>\u539f\u59cb FASTQ\n    \u2502\n    \u25bc\n\u8d28\u91cf\u63a7\u5236 (KneadData)\n    \u2502\n    \u25bc\n\u7269\u79cd\u5206\u7c7b (Kraken2)\n    \u2502\n    \u251c\u2500\u25ba \u4e30\u5ea6\u6821\u6b63 (Bracken)\n    \u2502\n    \u2514\u2500\u25ba Krona \u53ef\u89c6\u5316\n         \u2502\n         \u25bc\n    BIOM \u683c\u5f0f\u8f6c\u6362\n         \u2502\n         \u25bc\n    \u591a\u6837\u6027\u5206\u6790 (QIIME2)\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#_8","title":"\u8f93\u5165\u8981\u6c42","text":""},{"location":"zh/taxonomic-profiling.html#_9","title":"\u6570\u636e\u683c\u5f0f","text":"\u683c\u5f0f \u6269\u5c55\u540d \u914d\u5bf9/\u5355\u7aef FASTQ (gzip) <code>.fastq.gz</code> \u914d\u5bf9\u6216\u5355\u7aef FASTQ <code>.fastq</code> \u914d\u5bf9\u6216\u5355\u7aef"},{"location":"zh/taxonomic-profiling.html#_10","title":"\u547d\u540d\u89c4\u8303","text":"<pre><code>\u53cc\u7aef\u6d4b\u5e8f:\n  Sample1_R1.fastq.gz\n  Sample1_R2.fastq.gz\n\n\u5355\u7aef\u6d4b\u5e8f:\n  Sample1.fastq.gz\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#_11","title":"\u8d28\u91cf\u8981\u6c42","text":"\u6307\u6807 \u6700\u4f4e\u503c \u63a8\u8350\u503c \u8bfb\u957f \u2265 50 bp \u2265 100 bp \u8d28\u91cf\u5206\u6570 (Q30) &gt; 70% &gt; 85% \u6bcf\u6837\u672c\u6d4b\u5e8f\u6df1\u5ea6 100 \u4e07 reads 1000 \u4e07+ reads"},{"location":"zh/taxonomic-profiling.html#_12","title":"\u8fd0\u884c\u5206\u6790","text":""},{"location":"zh/taxonomic-profiling.html#1","title":"\u65b9\u5f0f 1: \u5b8c\u6574\u6d41\u7a0b","text":"<pre><code>python -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16 \\\n  --kneaddata-db /path/to/kneaddata_db \\\n  --kraken2-db /path/to/kraken2_db\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#2","title":"\u65b9\u5f0f 2: \u4ec5\u7269\u79cd\u5206\u7c7b","text":"<pre><code>python -m micos.cli run taxonomic-profiling \\\n  --input-dir data/cleaned_reads \\\n  --output-dir results/taxonomy \\\n  --threads 16 \\\n  --kraken2-db /path/to/kraken2_db \\\n  --confidence 0.1\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#3","title":"\u65b9\u5f0f 3: \u624b\u52a8\u6b65\u9aa4","text":"<pre><code># \u6b65\u9aa4 1: \u8fd0\u884c Kraken2\nkraken2 --db /path/to/kraken2_db \\\n  --paired sample_R1.fastq sample_R2.fastq \\\n  --output sample.kraken \\\n  --report sample.report \\\n  --confidence 0.1 \\\n  --threads 16\n\n# \u6b65\u9aa4 2: \u8fd0\u884c Bracken\nbracken -d /path/to/kraken2_db \\\n  -i sample.report \\\n  -o sample.bracken \\\n  -r 150 \\\n  -l S\n\n# \u6b65\u9aa4 3: \u8f6c\u6362\u4e3a BIOM\nkraken-biom *.report --fmt hdf5 -o feature-table.biom\n\n# \u6b65\u9aa4 4: \u751f\u6210 Krona\nktImportTaxonomy -o sample.krona.html sample.report\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#_13","title":"\u53c2\u6570\u914d\u7f6e","text":""},{"location":"zh/taxonomic-profiling.html#kraken2_1","title":"Kraken2 \u53c2\u6570","text":"<pre><code>taxonomic_profiling:\n  kraken2:\n    # \u5206\u7c7b\u7f6e\u4fe1\u5ea6 (0.0 - 1.0)\n    # \u8d8a\u9ad8\u8d8a\u4e25\u683c\uff0c\u5206\u7c7b\u7684 reads \u8d8a\u5c11\n    confidence: 0.1\n\n    # k-mer \u5339\u914d\u7684\u6700\u4f4e\u78b1\u57fa\u8d28\u91cf\n    min_base_quality: 20\n\n    # \u662f\u5426\u4f7f\u7528\u5185\u5b58\u6620\u5c04\u6570\u636e\u5e93\uff08\u66f4\u5feb\uff0c\u66f4\u591a\u5185\u5b58\uff09\n    memory_mapping: true\n\n    # \u5728\u8f93\u51fa\u4e2d\u5305\u542b\u5b66\u540d\n    use_names: true\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#_14","title":"\u7f6e\u4fe1\u5ea6\u9608\u503c\u9009\u62e9","text":"\u503c \u7075\u654f\u5ea6 \u7cbe\u786e\u5ea6 \u9002\u7528\u573a\u666f 0.0 \u5f88\u9ad8 \u8f83\u4f4e \u63a2\u7d22\u6027\u5206\u6790 0.1 \u9ad8 \u826f\u597d \u9ed8\u8ba4\uff0c\u5e73\u8861 0.3 \u4e2d\u7b49 \u9ad8 \u4fdd\u5b88\u5206\u6790 0.5 \u4f4e \u5f88\u9ad8 \u4ec5\u9ad8\u7f6e\u4fe1\u5ea6"},{"location":"zh/taxonomic-profiling.html#_15","title":"\u8f93\u51fa\u6587\u4ef6","text":""},{"location":"zh/taxonomic-profiling.html#_16","title":"\u76ee\u5f55\u7ed3\u6784","text":"<pre><code>results/taxonomic_profiling/\n\u251c\u2500\u2500 raw/\n\u2502   \u251c\u2500\u2500 sample1.kraken      # \u539f\u59cb\u5206\u7c7b\u8f93\u51fa\n\u2502   \u2514\u2500\u2500 sample1.report      # \u5206\u7c7b\u62a5\u544a\n\u251c\u2500\u2500 bracken/\n\u2502   \u2514\u2500\u2500 sample1.bracken     # \u6821\u6b63\u540e\u4e30\u5ea6\n\u251c\u2500\u2500 krona/\n\u2502   \u2514\u2500\u2500 sample1.krona.html  # \u4ea4\u4e92\u5f0f\u53ef\u89c6\u5316\n\u2514\u2500\u2500 biom/\n    \u2514\u2500\u2500 feature-table.biom  # QIIME2 \u517c\u5bb9\u8868\u683c\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#kraken2_2","title":"Kraken2 \u62a5\u544a\u683c\u5f0f","text":"\u5217 \u63cf\u8ff0 \u793a\u4f8b 1 reads \u767e\u5206\u6bd4 56.32 2 reads \u6570\u91cf (\u5206\u652f) 563200 3 reads \u6570\u91cf (\u76f4\u63a5) 10000 4 \u5c42\u7ea7\u4ee3\u7801 S 5 NCBI TaxID 562 6 \u5b66\u540d Escherichia coli"},{"location":"zh/taxonomic-profiling.html#_17","title":"\u7ed3\u679c\u89e3\u8bfb","text":""},{"location":"zh/taxonomic-profiling.html#_18","title":"\u5206\u7c7b\u7387","text":"\u5206\u7c7b\u7387 \u89e3\u8bfb \u64cd\u4f5c &lt; 50% \u9ad8\u672a\u5206\u7c7b\u7387 \u68c0\u67e5\u6570\u636e\u5e93\u8986\u76d6\u5ea6\uff0c\u8003\u8651\u964d\u4f4e\u7f6e\u4fe1\u5ea6 50-70% \u4e2d\u7b49 \u5927\u591a\u6570\u5206\u6790\u53ef\u63a5\u53d7 70-90% \u826f\u597d \u6807\u51c6\u6027\u80fd &gt; 90% \u4f18\u79c0 \u9ad8\u8d28\u91cf\u6570\u636e\u548c\u826f\u597d\u6570\u636e\u5e93\u8986\u76d6"},{"location":"zh/taxonomic-profiling.html#_19","title":"\u591a\u6837\u6027\u6307\u6807","text":""},{"location":"zh/taxonomic-profiling.html#alpha","title":"Alpha \u591a\u6837\u6027 (\u6837\u672c\u5185)","text":"\u6307\u6807 \u6d4b\u91cf\u5185\u5bb9 \u8303\u56f4 \u8bf4\u660e Shannon \u591a\u6837\u6027 (\u4e30\u5bcc\u5ea6 + \u5747\u5300\u5ea6) 0 - ~7 \u8d8a\u9ad8\u8d8a\u591a\u6837 Chao1 \u4e30\u5bcc\u5ea6\u4f30\u8ba1\u5668 0+ \u5bf9\u7a00\u6709\u7c7b\u7fa4\u654f\u611f Simpson \u5747\u5300\u5ea6 0-1 \u8d8a\u4f4e\u8d8a\u5747\u5300 <p>\u4eba\u7c7b\u80a0\u9053\u5178\u578b\u503c: - Shannon: 2.5-4.5 - \u89c2\u5bdf\u7269\u79cd\u6570: 50-200</p>"},{"location":"zh/taxonomic-profiling.html#_20","title":"\u9ad8\u7ea7\u4e3b\u9898","text":""},{"location":"zh/taxonomic-profiling.html#_21","title":"\u81ea\u5b9a\u4e49\u6570\u636e\u5e93\u521b\u5efa","text":"<pre><code># \u6784\u5efa\u81ea\u5b9a\u4e49 Kraken2 \u6570\u636e\u5e93\nkraken2-build --download-taxonomy --db custom_db\nkraken2-build --add-to-library custom_genome.fa --db custom_db\nkraken2-build --build --threads 16 --db custom_db\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#_22","title":"\u83cc\u682a\u6c34\u5e73\u5206\u6790","text":"<pre><code># \u4f7f\u7528\u66f4\u9ad8\u7f6e\u4fe1\u5ea6\u9608\u503c\u8fdb\u884c\u83cc\u682a\u5206\u6790\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.3\n    use_names: true\n</code></pre>"},{"location":"zh/taxonomic-profiling.html#_23","title":"\u6545\u969c\u6392\u9664","text":""},{"location":"zh/taxonomic-profiling.html#_24","title":"\u95ee\u9898: \u5206\u7c7b\u7387\u4f4e","text":"<p>\u75c7\u72b6: &lt;50% reads \u88ab\u5206\u7c7b</p> <p>\u89e3\u51b3\u65b9\u6848: <pre><code># 1. \u964d\u4f4e\u7f6e\u4fe1\u5ea6\u9608\u503c\ntaxonomic_profiling:\n  kraken2:\n    confidence: 0.05\n\n# 2. \u4f7f\u7528\u66f4\u5927\u7684\u6570\u636e\u5e93\n# \u4ece MiniKraken \u5207\u6362\u5230 Standard\n\n# 3. \u68c0\u67e5\u6570\u636e\u8d28\u91cf\n# \u5bf9\u8f93\u5165 reads \u8fd0\u884c FastQC\n</code></pre></p>"},{"location":"zh/taxonomic-profiling.html#_25","title":"\u95ee\u9898: \u6570\u636e\u5e93\u52a0\u8f7d\u6162","text":"<p>\u89e3\u51b3\u65b9\u6848: <pre><code># \u4f7f\u7528\u5185\u5b58\u6620\u5c04\ntaxonomic_profiling:\n  kraken2:\n    memory_mapping: true\n\n# \u6216\u4f7f\u7528 SSD \u5b58\u50a8\u6570\u636e\u5e93\n</code></pre></p>"},{"location":"zh/taxonomic-profiling.html#_26","title":"\u76f8\u5173\u6587\u6863","text":"<ul> <li>\u591a\u6837\u6027\u5206\u6790 - \u8be6\u7ec6\u591a\u6837\u6027\u6307\u6807</li> <li>\u529f\u80fd\u6ce8\u91ca - \u529f\u80fd\u5206\u6790</li> <li>\u914d\u7f6e\u6307\u5357 - \u53c2\u6570\u53c2\u8003</li> </ul>"},{"location":"zh/troubleshooting.html","title":"\u6545\u969c\u6392\u9664 (Troubleshooting)","text":"<p>\u672c\u9875\u9762\u5217\u51fa\u4e86 MICOS-2024 \u5e38\u89c1\u95ee\u9898\u53ca\u5176\u89e3\u51b3\u65b9\u6848\u3002</p>"},{"location":"zh/troubleshooting.html#_1","title":"\u5b89\u88c5\u95ee\u9898","text":""},{"location":"zh/troubleshooting.html#q","title":"Q: \u5b89\u88c5\u4f9d\u8d56\u65f6\u51fa\u73b0\u7248\u672c\u51b2\u7a81","text":"<p>A: \u5efa\u8bae\u4f7f\u7528 conda \u521b\u5efa\u72ec\u7acb\u73af\u5883\uff1a</p> <pre><code>conda create -n micos python=3.10\nconda activate micos\npip install -e .\n</code></pre>"},{"location":"zh/troubleshooting.html#q-kraken2","title":"Q: Kraken2 \u6570\u636e\u5e93\u4e0b\u8f7d\u5931\u8d25","text":"<p>A: Kraken2 \u6807\u51c6\u6570\u636e\u5e93\u8f83\u5927\uff08~8GB\uff09\uff0c\u53ef\u4ee5\u5c1d\u8bd5\uff1a</p> <ol> <li> <p>\u4f7f\u7528 MiniKraken \u6570\u636e\u5e93\uff08\u8f83\u5c0f\uff09\uff1a <pre><code>wget https://genome-idx.s3.amazonaws.com/kraken/minikraken2_v2_8GB.tar.gz\n</code></pre></p> </li> <li> <p>\u6216\u4f7f\u7528\u56fd\u5185\u955c\u50cf\u6e90\u4e0b\u8f7d</p> </li> </ol>"},{"location":"zh/troubleshooting.html#_2","title":"\u8fd0\u884c\u95ee\u9898","text":""},{"location":"zh/troubleshooting.html#q-command-not-found","title":"Q: \u8fd0\u884c\u65f6\u63d0\u793a \"command not found\"","text":"<p>A: \u786e\u4fdd\u6240\u6709\u4f9d\u8d56\u5de5\u5177\u5df2\u5b89\u88c5\u5e76\u6dfb\u52a0\u5230 PATH\uff1a - FastQC - KneadData - Kraken2 - HUMAnN - QIIME2</p> <p>\u53ef\u4ee5\u4f7f\u7528 <code>micos --help</code> \u68c0\u67e5\u73af\u5883\u662f\u5426\u6b63\u786e\u914d\u7f6e\u3002</p>"},{"location":"zh/troubleshooting.html#q_1","title":"Q: \u5185\u5b58\u4e0d\u8db3\u9519\u8bef","text":"<p>A: \u53ef\u4ee5\u901a\u8fc7\u4ee5\u4e0b\u65b9\u5f0f\u51cf\u5c11\u5185\u5b58\u4f7f\u7528\uff1a - \u51cf\u5c11\u5e76\u884c\u7ebf\u7a0b\u6570\uff1a<code>--threads 4</code> - \u4f7f\u7528\u8f83\u5c0f\u7684\u6570\u636e\u5e93\uff08MiniKraken\uff09 - \u5206\u6279\u5904\u7406\u6837\u672c</p>"},{"location":"zh/troubleshooting.html#q-kneaddata","title":"Q: KneadData \u8fd0\u884c\u65f6\u95f4\u8fc7\u957f","text":"<p>A: KneadData \u9700\u8981\u6bd4\u5bf9\u5bbf\u4e3b\u57fa\u56e0\u7ec4\uff0c\u5efa\u8bae\uff1a - \u4f7f\u7528 SSD \u5b58\u50a8\u6570\u636e\u5e93 - \u589e\u52a0\u7ebf\u7a0b\u6570 - \u786e\u4fdd\u6570\u636e\u5e93\u8def\u5f84\u6b63\u786e</p>"},{"location":"zh/troubleshooting.html#_3","title":"\u6570\u636e\u95ee\u9898","text":""},{"location":"zh/troubleshooting.html#q_2","title":"Q: \u8f93\u5165\u6587\u4ef6\u683c\u5f0f\u8981\u6c42","text":"<p>A: MICOS-2024 \u652f\u6301\uff1a - FASTQ \u683c\u5f0f\uff08.fastq, .fq, .fastq.gz, .fq.gz\uff09 - \u914d\u5bf9\u7aef\u6d4b\u5e8f\u6570\u636e\u547d\u540d\u683c\u5f0f\uff1a<code>{sample}_1.fastq</code> \u548c <code>{sample}_2.fastq</code></p>"},{"location":"zh/troubleshooting.html#q_3","title":"Q: \u6837\u672c\u547d\u540d\u89c4\u8303","text":"<p>A: \u6837\u672c\u540d\u5e94\u9075\u5faa\u4ee5\u4e0b\u89c4\u5219\uff1a - \u53ea\u4f7f\u7528\u5b57\u6bcd\u3001\u6570\u5b57\u548c\u4e0b\u5212\u7ebf - \u907f\u514d\u7279\u6b8a\u5b57\u7b26\u548c\u7a7a\u683c - \u4ee5\u5b57\u6bcd\u5f00\u5934</p>"},{"location":"zh/troubleshooting.html#_4","title":"\u8f93\u51fa\u95ee\u9898","text":""},{"location":"zh/troubleshooting.html#q_4","title":"Q: \u7ed3\u679c\u6587\u4ef6\u5728\u54ea\u91cc\uff1f","text":"<p>A: \u9ed8\u8ba4\u8f93\u51fa\u7ed3\u6784\uff1a <pre><code>results/\n\u251c\u2500\u2500 quality_control/\n\u251c\u2500\u2500 taxonomic_profiling/\n\u251c\u2500\u2500 functional_annotation/\n\u251c\u2500\u2500 diversity_analysis/\n\u2514\u2500\u2500 micos_summary_report.html\n</code></pre></p>"},{"location":"zh/troubleshooting.html#q_5","title":"Q: \u62a5\u544a\u751f\u6210\u5931\u8d25","text":"<p>A: \u786e\u4fdd\u524d\u9762\u7684\u6b65\u9aa4\u90fd\u6210\u529f\u5b8c\u6210\uff0c\u68c0\u67e5\uff1a - \u5404\u6a21\u5757\u8f93\u51fa\u76ee\u5f55\u662f\u5426\u5b58\u5728 - \u65e5\u5fd7\u6587\u4ef6\u4e2d\u662f\u5426\u6709\u9519\u8bef\u4fe1\u606f</p>"},{"location":"zh/troubleshooting.html#_5","title":"\u5176\u4ed6\u95ee\u9898","text":"<p>\u5982\u679c\u4ee5\u4e0a\u5185\u5bb9\u672a\u80fd\u89e3\u51b3\u60a8\u7684\u95ee\u9898\uff0c\u8bf7\uff1a</p> <ol> <li>\u67e5\u770b GitHub Issues</li> <li>\u63d0\u4ea4\u65b0\u7684 Issue\uff0c\u5305\u542b\uff1a</li> <li>\u9519\u8bef\u4fe1\u606f</li> <li>\u8fd0\u884c\u547d\u4ee4</li> <li>\u7cfb\u7edf\u73af\u5883\u4fe1\u606f</li> </ol>"},{"location":"zh/user_manual.html","title":"MICOS-2024 \u7528\u6237\u624b\u518c","text":""},{"location":"zh/user_manual.html#_1","title":"\u76ee\u5f55","text":"<ul> <li>\u5feb\u901f\u5f00\u59cb</li> <li>\u8be6\u7ec6\u5b89\u88c5\u6307\u5357</li> <li>\u6570\u636e\u51c6\u5907</li> <li>\u8fd0\u884c\u5206\u6790</li> <li>\u7ed3\u679c\u89e3\u8bfb</li> <li>\u547d\u4ee4\u53c2\u8003</li> <li>\u5e38\u89c1\u95ee\u9898</li> <li>\u9ad8\u7ea7\u529f\u80fd</li> </ul>"},{"location":"zh/user_manual.html#_2","title":"\u5feb\u901f\u5f00\u59cb","text":""},{"location":"zh/user_manual.html#_3","title":"\u7cfb\u7edf\u8981\u6c42","text":"\u9879\u76ee \u6700\u4f4e\u914d\u7f6e \u63a8\u8350\u914d\u7f6e \u64cd\u4f5c\u7cfb\u7edf Linux (Ubuntu 18.04+) / macOS 11+ Linux (Ubuntu 20.04+) \u5185\u5b58 16GB 32GB+ \u5b58\u50a8 100GB 500GB+ SSD CPU 4 \u6838 16+ \u6838"},{"location":"zh/user_manual.html#_4","title":"\u5feb\u901f\u6d4b\u8bd5","text":"<pre><code># \u6fc0\u6d3b\u73af\u5883\nconda activate micos-2024\n\n# \u8fd0\u884c\u6d4b\u8bd5\u6570\u636e\n./scripts/run_test_data.sh\n\n# \u67e5\u770b\u7ed3\u679c\nfirefox results/reports/analysis_report.html\n</code></pre>"},{"location":"zh/user_manual.html#_5","title":"\u8be6\u7ec6\u5b89\u88c5\u6307\u5357","text":""},{"location":"zh/user_manual.html#1docker","title":"\u65b9\u5f0f 1\uff1aDocker \u5b89\u88c5\uff08\u63a8\u8350\uff09","text":"<pre><code># 1. \u5b89\u88c5 Docker \u548c Docker Compose\ncurl -fsSL https://get.docker.com -o get-docker.sh\nsudo sh get-docker.sh\nsudo usermod -aG docker $USER\n\n# 2. \u514b\u9686\u9879\u76ee\ngit clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\n\n# 3. \u542f\u52a8\u670d\u52a1\ndocker compose -f deploy/docker-compose.example.yml up -d\n\n# 4. \u9a8c\u8bc1\u5b89\u88c5\ndocker compose -f deploy/docker-compose.example.yml ps\n</code></pre>"},{"location":"zh/user_manual.html#2conda","title":"\u65b9\u5f0f 2\uff1aConda \u5b89\u88c5","text":"<pre><code># 1. \u5b89\u88c5 Miniforge\nwget https://github.com/conda-forge/miniforge/releases/latest/download/Miniforge3-Linux-x86_64.sh\nbash Miniforge3-Linux-x86_64.sh\n\n# 2. \u521b\u5efa\u73af\u5883\ngit clone https://github.com/BGI-MICOS/MICOS-2024.git\ncd MICOS-2024\nmamba env create -f environment.yml\nconda activate micos-2024\n\n# 3. \u9a8c\u8bc1\u5b89\u88c5\n./scripts/verify_installation.sh\n</code></pre>"},{"location":"zh/user_manual.html#_6","title":"\u6570\u636e\u51c6\u5907","text":""},{"location":"zh/user_manual.html#_7","title":"\u8f93\u5165\u6570\u636e\u683c\u5f0f","text":"<p>MICOS-2024 \u652f\u6301\u4ee5\u4e0b\u8f93\u5165\u683c\u5f0f\uff1a</p> \u683c\u5f0f \u7c7b\u578b \u547d\u540d\u89c4\u8303 FASTQ\uff08\u63a8\u8350\uff09 \u53cc\u7aef\u6d4b\u5e8f <code>sample_R1.fastq.gz</code>, <code>sample_R2.fastq.gz</code> FASTQ \u5355\u7aef\u6d4b\u5e8f <code>sample.fastq.gz</code>"},{"location":"zh/user_manual.html#_8","title":"\u6570\u636e\u7ec4\u7ec7\u7ed3\u6784","text":"<pre><code>data/\n\u251c\u2500\u2500 raw_input/\n\u2502   \u251c\u2500\u2500 Sample001_R1.fastq.gz\n\u2502   \u251c\u2500\u2500 Sample001_R2.fastq.gz\n\u2502   \u251c\u2500\u2500 Sample002_R1.fastq.gz\n\u2502   \u2514\u2500\u2500 Sample002_R2.fastq.gz\n\u2514\u2500\u2500 metadata/\n    \u2514\u2500\u2500 samples.tsv\n</code></pre>"},{"location":"zh/user_manual.html#_9","title":"\u6570\u636e\u8d28\u91cf\u8981\u6c42","text":"\u6307\u6807 \u8981\u6c42 \u6d4b\u5e8f\u6df1\u5ea6 \u6bcf\u6837\u672c \u2265 1M reads \u5e8f\u5217\u957f\u5ea6 \u2265 75bp \u8d28\u91cf\u503c \u5e73\u5747 Q \u503c \u2265 20"},{"location":"zh/user_manual.html#_10","title":"\u8fd0\u884c\u5206\u6790","text":""},{"location":"zh/user_manual.html#_11","title":"\u5b8c\u6574\u6d41\u7a0b\u5206\u6790","text":"<pre><code># 1. \u51c6\u5907\u914d\u7f6e\u6587\u4ef6\ncp config/analysis.yaml.template config/analysis.yaml\ncp config/samples.tsv.template config/samples.tsv\n\n# 2. \u7f16\u8f91\u914d\u7f6e\u6587\u4ef6\nnano config/analysis.yaml\nnano config/samples.tsv\n\n# 3. \u8fd0\u884c\u5b8c\u6574\u5206\u6790\n./scripts/run_full_analysis.sh\n\n# 4. \u76d1\u63a7\u8fdb\u5ea6\ntail -f logs/analysis.log\n</code></pre>"},{"location":"zh/user_manual.html#cli","title":"\u4f7f\u7528 CLI \u547d\u4ee4","text":"<pre><code># \u5b8c\u6574\u6d41\u7a0b\npython -m micos.cli full-run \\\n  --input-dir data/raw_input \\\n  --results-dir results \\\n  --threads 16 \\\n  --kneaddata-db /path/to/kneaddata_db \\\n  --kraken2-db /path/to/kraken2_db\n\n# \u5355\u72ec\u6a21\u5757\npython -m micos.cli run quality-control \\\n  --input-dir data/raw_input \\\n  --output-dir results/quality_control \\\n  --threads 16\n\npython -m micos.cli run taxonomic-profiling \\\n  --input-dir results/quality_control/kneaddata \\\n  --output-dir results/taxonomic_profiling \\\n  --threads 16\n</code></pre>"},{"location":"zh/user_manual.html#_12","title":"\u7ed3\u679c\u89e3\u8bfb","text":""},{"location":"zh/user_manual.html#_13","title":"\u8f93\u51fa\u76ee\u5f55\u7ed3\u6784","text":"<pre><code>results/\n\u251c\u2500\u2500 reports/                    # HTML \u62a5\u544a\n\u2502   \u2514\u2500\u2500 analysis_report.html\n\u251c\u2500\u2500 1_quality_control/          # \u8d28\u91cf\u63a7\u5236\u7ed3\u679c\n\u2502   \u251c\u2500\u2500 fastqc_reports/\n\u2502   \u2514\u2500\u2500 kneaddata/\n\u251c\u2500\u2500 2_taxonomic_profiling/      # \u7269\u79cd\u5206\u7c7b\u7ed3\u679c\n\u2502   \u251c\u2500\u2500 kraken_reports/\n\u2502   \u251c\u2500\u2500 krona_charts/\n\u2502   \u2514\u2500\u2500 feature-table.biom\n\u251c\u2500\u2500 3_diversity_analysis/       # \u591a\u6837\u6027\u5206\u6790\n\u2502   \u251c\u2500\u2500 alpha_diversity/\n\u2502   \u251c\u2500\u2500 beta_diversity/\n\u2502   \u2514\u2500\u2500 pcoa_plots/\n\u251c\u2500\u2500 4_functional_annotation/    # \u529f\u80fd\u5206\u6790\n\u2502   \u251c\u2500\u2500 genefamilies/\n\u2502   \u2514\u2500\u2500 pathways/\n\u2514\u2500\u2500 logs/                       # \u8fd0\u884c\u65e5\u5fd7\n</code></pre>"},{"location":"zh/user_manual.html#_14","title":"\u5173\u952e\u6307\u6807\u89e3\u91ca","text":""},{"location":"zh/user_manual.html#alpha","title":"Alpha \u591a\u6837\u6027\u6307\u6807","text":"\u6307\u6807 \u542b\u4e49 \u89e3\u8bfb Shannon \u7fa4\u843d\u591a\u6837\u6027 \u503c\u8d8a\u9ad8\u591a\u6837\u6027\u8d8a\u5927 Chao1 \u7fa4\u843d\u4e30\u5bcc\u5ea6\u4f30\u8ba1 \u4f30\u8ba1\u603b\u7269\u79cd\u6570 Observed Features \u89c2\u6d4b\u7279\u5f81\u6570 \u5b9e\u9645\u89c2\u6d4b\u5230\u7684 ASV/OTU \u6570\u91cf"},{"location":"zh/user_manual.html#beta","title":"Beta \u591a\u6837\u6027\u6307\u6807","text":"\u6307\u6807 \u542b\u4e49 \u9002\u7528\u573a\u666f Bray-Curtis \u57fa\u4e8e\u4e30\u5ea6\u7684\u7fa4\u843d\u5dee\u5f02 \u6bd4\u8f83\u7fa4\u843d\u7ec4\u6210\u5dee\u5f02 Jaccard \u57fa\u4e8e\u5b58\u5728/\u7f3a\u5931\u7684\u5dee\u5f02 \u6bd4\u8f83\u7269\u79cd\u6709\u65e0\u5dee\u5f02 UniFrac \u57fa\u4e8e\u7cfb\u7edf\u53d1\u80b2\u7684\u5dee\u5f02 \u8003\u8651\u8fdb\u5316\u5173\u7cfb"},{"location":"zh/user_manual.html#_15","title":"\u547d\u4ee4\u53c2\u8003","text":""},{"location":"zh/user_manual.html#cli_1","title":"CLI \u547d\u4ee4\u4e00\u89c8","text":"\u547d\u4ee4 \u63cf\u8ff0 <code>python -m micos.cli full-run</code> \u8fd0\u884c\u5b8c\u6574\u5206\u6790\u6d41\u7a0b <code>python -m micos.cli run quality-control</code> \u8d28\u91cf\u63a7\u5236\u6a21\u5757 <code>python -m micos.cli run taxonomic-profiling</code> \u7269\u79cd\u5206\u7c7b\u6a21\u5757 <code>python -m micos.cli run diversity-analysis</code> \u591a\u6837\u6027\u5206\u6790\u6a21\u5757 <code>python -m micos.cli run functional-annotation</code> \u529f\u80fd\u6ce8\u91ca\u6a21\u5757"},{"location":"zh/user_manual.html#_16","title":"\u5168\u5c40\u9009\u9879","text":"\u9009\u9879 \u63cf\u8ff0 <code>--config PATH</code> \u6307\u5b9a\u914d\u7f6e\u6587\u4ef6\u8def\u5f84 <code>--log-file PATH</code> \u65e5\u5fd7\u8f93\u51fa\u6587\u4ef6 <code>--verbose</code> \u542f\u7528\u8be6\u7ec6\u65e5\u5fd7"},{"location":"zh/user_manual.html#_17","title":"\u5e38\u89c1\u95ee\u9898","text":""},{"location":"zh/user_manual.html#q1","title":"Q1: \u73af\u5883\u521b\u5efa\u5931\u8d25\uff1f","text":"<p>\u89e3\u51b3\u65b9\u6848\uff1a</p> <pre><code># \u6e05\u7406 conda \u7f13\u5b58\nconda clean --all\n\n# \u4f7f\u7528 mamba \u66ff\u4ee3\nconda install mamba -c conda-forge\nmamba env create -f environment.yml\n</code></pre>"},{"location":"zh/user_manual.html#q2-docker","title":"Q2: Docker \u6743\u9650\u9519\u8bef\uff1f","text":"<p>\u89e3\u51b3\u65b9\u6848\uff1a</p> <pre><code>sudo usermod -aG docker $USER\nnewgrp docker\n</code></pre>"},{"location":"zh/user_manual.html#q3","title":"Q3: \u6570\u636e\u5e93\u8def\u5f84\u9519\u8bef\uff1f","text":"<p>\u89e3\u51b3\u65b9\u6848\uff1a</p> <pre><code># \u68c0\u67e5\u6570\u636e\u5e93\u662f\u5426\u5b58\u5728\nls -la /path/to/kraken2_db\n\n# \u66f4\u65b0\u914d\u7f6e\u6587\u4ef6\nnano config/databases.yaml\n</code></pre>"},{"location":"zh/user_manual.html#q4","title":"Q4: \u5185\u5b58\u4e0d\u8db3\uff1f","text":"<p>\u89e3\u51b3\u65b9\u6848\uff1a</p> <pre><code># \u5728 config/analysis.yaml \u4e2d\u51cf\u5c11\u5e76\u884c\u5ea6\nresources:\n  max_threads: 8\n  max_memory: \"16GB\"\n</code></pre>"},{"location":"zh/user_manual.html#_18","title":"\u9ad8\u7ea7\u529f\u80fd","text":""},{"location":"zh/user_manual.html#_19","title":"\u5dee\u5f02\u4e30\u5ea6\u5206\u6790","text":"<p>MICOS-2024 \u652f\u6301\u591a\u79cd\u5dee\u5f02\u4e30\u5ea6\u5206\u6790\u65b9\u6cd5\uff1a</p> <pre><code>./scripts/run_module.sh differential_abundance\n</code></pre>"},{"location":"zh/user_manual.html#_20","title":"\u7f51\u7edc\u5206\u6790","text":"<pre><code>./scripts/run_module.sh network_analysis\n</code></pre>"},{"location":"zh/user_manual.html#16s-rrna","title":"16S rRNA \u6269\u589e\u5b50\u5206\u6790","text":"<pre><code>./scripts/run_module.sh amplicon_analysis\n</code></pre>"},{"location":"zh/user_manual.html#_21","title":"\u53c2\u8003","text":""},{"location":"zh/user_manual.html#_22","title":"\u76f8\u5173\u6587\u6863","text":"<ul> <li>\u914d\u7f6e\u6307\u5357</li> <li>\u6545\u969c\u6392\u9664</li> <li>\u7269\u79cd\u5206\u7c7b\u5206\u6790</li> <li>\u529f\u80fd\u6ce8\u91ca</li> </ul>"},{"location":"zh/user_manual.html#_23","title":"\u9879\u76ee\u4ed3\u5e93","text":"<ul> <li>GitHub</li> <li>\u95ee\u9898\u53cd\u9988</li> <li>\u8ba8\u8bba\u533a</li> </ul>"}]}